COLLDATA("sh10802","ar",[[1,"الْإِمَامُ الدَّارَقُطْنِيُّ"],[2,"هُوَ الإِمَامُ أَبُو الْحَسَنِ عَلِيُّ بْنُ عُمَرَ بْنِ أَحْمَدَ بْنِ مَهْدِيٍّ الْبَغْدَادِيُّ صَاحِبُ السُّنَنِ. وُلِدَ سَنَةَ سِتٍّ وَثَلاَثَ مِائَةٍ."],[3,"سَمِعَ الْبَغَوِيَّ وَابْنُ صَاعِدٍ وَابْنُ دُرَيْدٍ."],[4,"وَمِنْ تَلامِذَتِهِ أَبُو بَكْرٍ الْبَرْقَانِيُّ وَحَمْزَةُ بْنُ مُحَمَّدِ بْنِ طَاهِرٍ وَالأَزْهَرِيُّ. وَخَلْقٍ."],[5,"قَالَ الذَّهَبِيُّ: - \"سَمِعَ بِبَغْدَادَ وَالْبَصْرَةِ وَالْكُوفَةِ وَوَاسِطٍ وَارْتَحَلَ فِي كُهُولَتِهِ إِلَى مِصْرَ وَالشَّامِ وَصِنَّفَ التَّصَانِيفَ الْفَائِقَةَ\"."],[6,"قَالَ الْخَطِيبُ الْبَغْدَادِيُّ: - \"كَانَ فَرِيدُ عَصْرِهِ وَإِمَامُ وَقْتِهِ وَانْتَهَى عِلْمُ الْأَثَرِ وَالْمَعْرِفَةُ بِالْعِلَلِ وَأَسْمَاءُ الرِّجَالِ مَعَ الصَّدَقَةِ وَالثِّقَةِ وَصِحَّةِ الِاعْتِقَادِ وَالِاِضْطِلَاعِ مِنْ عُلُومٍ كَالْقِرَاءَاتِ فَإِنَّ لَهُ فِيهَا مُصَنَّفًا سَبَقَ فِيهِ إِلَى عَقْدِ الأَبْوَابِ قَبْلَ فُرُشِ الْحُرُوفِ وَتَأَسَّى الْقُرَّاءِ بَعْدَهُ\"."],[7,"قُلْتُ: \"وَكِتَابُهُ الْعِلَلُ الْكَبِيرُ يَشْهَدُ لَهُ بِالْعِلْمِ وَسَعَةِ الإِطْلَاعِ فِي أَقْوَالِ الْمُتَقَدِّمِينَ وَأَهْلِ عَصْرِهِ\"."],[8,"وَقَدْ نُسِبَ إِلَى التَّشَيُّعِ لِسَبَبِ حِفْظِهِ دِيوَانُ السَّيِّدِ الْحِمْيَرِيِّ. وَهِىَ تُهْمَةٌ رَدَّهَا الإِمَامُ الذَّهَبِيُّ رَحِمَهُ اللَّهُ."],[9,"وَهُنَاكَ مَوَاقِفُ تَدُلُّ عَلَى عَظِيمِ شَأْنِهِ وَدِقَّةُ انْتِبَاهِهِ لِمَا يُمْلَى فِي الْمَجَالِسِ فَمِنْ تِلْكَ مَا نَقَلَهُ الْخَطِيبُ الْبَغْدَادِيُّ عَنِ الأَزْهَرِيِّ حَيْثُ قَالَ: \" بَلَغَنِي أَنَّ الدَّارَقُطْنِىَّ حَضَرَ فِي حَدَاثَتِهِ مَجْلِسَ إِسْمَاعِيلَ الصَّفَّارِ وَقَعَدَ يَنْسَخُ جُزْءًا وَالصَّفَّارَ يُمْلَى. فَقَالَ رَجُلٌ- لِلدَّارَقُطْنِىِّ-: لاَ يَصِحُّ. سَمَاعُكَ وَأَنْتَ تَنْسَخُ. فَقَالَ: فَهَمِي لِلإِمْلاَءِ خِلاَفُ فَهْمِكَ. أَتَحْفَظُ كَمْ أَمْلَى الشَّيْخُ. قَالَ: لاَ أَدْرِى. قَالَ: أَمْلَى ثَمَانِيَةَ عَشَرَ حَدِيثًا. الْحَدِيثَ الأَوَّلُ عَنْ فُلاَنٍ عَنْ فُلاَنٍ وَمَتْنِهِ كَذَا وَكَذَا. وَالْحَدِيثُ الثَّانِي عَنْ فُلاَنٍ عَنْ فُلاَنٍ. وَمَتْنُهُ كَذَا وَكَذَا. وَمَرَّ فِي ذَلِكَ حَتَّى أَتَى عَلَى الأَحَادِيثِ فَتَعَجَّبَ النَّاسُ مِنْهُ\"."],[10,"مَاتَ رَحِمَهُ اللَّهُ سَنَةَ خَمْسٍ وَثَمَانِينَ وَثَلَاثِمِائَةٍ (١) ."],[11,"كِتَابُ الضُّعَفَاءِ:"],[12,"يُعْتَبَرُ كِتَابُ الإِمَامِ الدَّارَقُطْنِيِّ مِنْ أُمَّهَاتِ الْكُتُبِ الَّتِي اعْتَمَدَ عَلَيْهَا الْمُصَنِّفُونَ فِي عِلْمِ الْجُرْحِ وَالتَّعْدِيلِ. كَمِيزَانِ الاِعْتِدَالِ - وَلِسَانِ الْمِيزَانِ - وَتَهْذِيبِ الْكَمَالِ وَغَيْرِهَا مِنَ الْكُتُبِ الَّتِي أَصْبَحَتْ فِيمَا بَعْدُ مِنَ الْمَرَاجِعِ الْمُهِمَّةِ لِلْبَاحِثِينَ."],[13,"وَأَنَّ كَلاَمَ الدَّارَقُطْنِيِّ فِي الضُّعَفَاءِ لَيْسَ مَقْصُورًا عَلَى كِتَابِهِ الَّذِي بَيْنَ أَيْدِينَا بَلْ تَكَلَّمَ عَنْهُمْ فِي كِتَابِهِ السُّنَنُ وَكِتَابُهُ الْعِلَلُ وَهَذَا مَا يُفَسَّرُ لَنَا اخْتِلاَفُ لَفْظِ التَّضْعِيفِ فِي رَاوِ مَا فِي الْمَرَاجِعِ الْمُخْتَلِفَةِ الَّتِي وَقَفَتْ عَلَيْهَا."],[14,"وَمِنْ الْغَرِيبِ حَقًّا أَنْ نَرَى ثُبُوتَ الْمُصَنِّفِ عَلَى قَوْلِهِ فِي التَّصْنِيفِ بِعَكْسِ الإِمَامِ ابْنِ حِبَّانَ الْبُسْتِيِّ مَثَلًا حَيْثُ يَذْكُرُ- أَحْيَانًا- بَعْضَ الرُّوَاةِ فِي كِتَابِهِ الْمَجْرُوحِينَ ثُمَّ يُعِيدُ ذِكْرَهُمْ فِي كِتَابِ الثِّقَاتِ. مِمَّا يَدُلُّ عَلَى أَنَّ الدَّارَقُطْنِيَّ لَمْ يَصْدُرْ حُكْمُهُ فِي ذَلِكَ الرَّاوِي إِلاَّ بَعْدَ دِرَاسَةٍ لِحَالِهِ وَرِوَايَاتِهِ وَمِنْ أَجْلِ هَذَا جَاءَ كَلامُهُ ثَابِتًا عَنْهُ."],[15,"وَعِنْدَ مُقَابَلَتِي لأَقْوَالِهِ مَعَ أَقْوَالِ غَيْرِهِ لَمْ أَجِدْ مِنَ الْغَيْرِ تَرَدُّدًا فِي أَيِّ رَاوٍ تَكَلَّمَ عَنْهُ الدَّارَقُطْنِيُّ بَلْ هُنَاكَ بَعْضُ عُلَمَاءِ الْجُرْحِ تَكَلَّمُوا فِي الرَّاوِي كَلاَمًا أَشَدَّ مِنْ كَلاَمِ الدَّارَقُطْنِىِّ مِمَّا يُرَجَّحُ تَأَدُّبُ الدَّارَقُطْنِيِّ فِي هَذِهِ النَّاحِيَةِ طَالِمًا أَنَّهُ اسْتَطَاعَ أَنْ يُبَيِّنَ حَالَ الرُّوَاةِ."],[16,"وَفِي الْحَقِيقَةِ لَمْ أَتَمَكَّنْ مِنَ التَّعْلِيقِ عَلَى جَمِيعِ الَّذِينَ تَكَلَّمَ عَنْهُمْ لأَنَّ الْغَرَضَ هُوَ إحْيَاءُ هَذَا الْجُزْءِ لِيَكُونَ فِي مُتَنَاوِلِ الْبَاحِثِينَ الَّذِينَ يَفْتَقِدُونَ هَذَا الْكِتَابَ إِنْ لَمْ يَكُنْ كُلُّهُمْ فَجُلَّهُمْ. وَلَعَلَّ نَشْرَهُ فِي مَجَلَّةٍ جَامِعِيَّةٍ يُعْفِينِي مِنَ الْمُطَالَبَةِ بِتَكْثِيرِ الْحَوَاشِي لأَنَّ الْغَرَضَ هُوَ الْكِتَابُ وَلَيْسَتِ الْحَاشِيَةُ."],[17,"وَأَرْجُو أَنْ أَكُونَ مِمَّنْ سَاهِمٌ وَلَوْ بِجَهْدٍ قَلِيلٍ فِي إِحْيَاءِ هَذَا التُّرَاثِ النَّادِرِ. وَإِنَّنِي آمِلٌ أَنْ أَقْدِّمَ مَوْضُوعًا مُنْفَصِلًا عَنِ الدَّارَقُطْنِيِّ وَمُؤَلَّفَاتِهِ وَجُهُودِهِ فِي إِحْيَاءِ السُّنَّةِ النَّبَوِيَّةِ."],[18,"جُزْءٌ فِيهِ الضُّعَفَاءُ وَالْمَتْرُوكُونَ:"],[19,"لأَبِي الْحَسَنِ عَلِيِّ بْنِ عُمَرَ بْنِ أَحْمَدَ بْنِ مَهْدِيٍّ الدَّارَقُطْنِيِّ."],[20,"رِوَايَةُ: أَبِي مُحَمَّدٍ الْحَسَنِ بْنِ عَلِيِّ بْنِ مُحَمَّدٍ الْجَوْهَرِيِّ عَنْهُ."],[21,"رِوَايَةُ: أَبِي مَنْصُورٍ مُحَمَّدِ بْنِ عَبْدِ الْمَلِكِ بْنِ خَيْرُونَ عَنْهُ إِجَازَةٌ."],[22,"رِوَايَةٌ: الشَّيْخَةُ أُمُّ عَبْدِ الْكَرِيمِ فَاطِمَةُ بِنْتُ أَبِي الْحَسَنِ سَعْدٌ الْخَيْرُ بْنُ مُحَمَّدِ بْنِ سَهْلٍ الأَنْصَارِيُّ."],[23,"رِوَايَةُ: أَبِي عَبْدِ اللَّهِ مُحَمَّدِ بْنِ إِسْمَاعِيلَ بْنِ أَحْمَدَ الْمَقْدِسِيَّ عَنْهَا سَمَاعًا مِنْهُ لِعَبْدِ الْحَافِظِ بْنِ عَبْدِ الْمُنْعِمِ بْنِ غَازِيٍّ الْكُورِيِّ."],[24,"قَالَ أَبُو بَكْرٍ أَحْمَدُ بْنُ مُحَمَّدِ بْنِ غَالِبٍ الْخُوَارِزْمِيُّ الْبَرْقَانِيُّ: \"طَالَتْ مُحَاوَرَتِي مَعَ أَبُو مَنْصُورٍ إِبْرَاهِيمُ بْنُ الْحُسَيْنِ بْنِ حَمْكَانَ لأَبِي الْحَسَنِ عَلِيِّ بْنِ عُمَرَ الدَّارَقُطْنِيِّ - عَفَا اللَّهُ عَنْهُ وَعَنْهُمَا- فِي الْمَتْرُوكِينَ مِنْ أَصْحَابِ الْحَدِيثِ فَتَقَرَّرَ بَيْنَنَا وَبَيْنَهُ عَلَى تَرْكِ مَنْ أَثْبَتَهُ عَلَى حُرُوفِ الْمُعْجَمِ فِي هَذِهِ الْوَرَقَاتِ."],[25,"إبْرَاهِيمُ بْنُ الْفَضْلِ الْمَدَنِيُّ الْمَخْزُومِيُّ عَنْ الْمَقْبُرِيِّ رَوَى عَنْهُ إسْرَائِيلُ وَكَنَّاهُ أَبَا إِسْحَاقَ .\n• قَالَ الذَّهَبِيُّ: تَرَكَهُ غَيْرُ وَاحِدٍ- ت ق- (دِيوَانٌ ١١) ."],[26,"إِبْرَاهِيمُ بْنُ الْحَكَمِ بْنِ أَبَانَ الْعَدَنِيُّ. قَالَ أَحْمَدُ بْنُ حَنْبَلٍ: \"فِي سَبِيلِ اللَّهِ دَرَاهِمُ أَنْفَقْنَاهَا إِلَى عَدَنٍ إِلَى إِبْرَاهِيمَ بْنِ الْحَكَمِ\" .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكٌ- ق-."],[27,"إِبْرَاهِيمُ بْنُ عَلِيٍّ الرَّافِعِيُّ. يَرْوِي عَنْ كَثِيرِ بْنِ عَبْدِ اللَّهِ عَنْ أَبِيهِ عَنْ جَدِّهِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"صَلَّى عَلِىٌّ النَّجَاشِيِّ فَكَبَّرَ عَلَيْهِ خَمْسًا\". رَوَى عَنْهُ أَيُّوبُ بْنُ حَسَنِ بْنِ عَلِيِّ بْنِ أَبِي رَافِعٍ عَنْ أَبِيهِ .\n• قَالَ الْبُخَارِيُّ: فِيهِ نَظَرُ التَّارِيخِ الْكَبِيرِ ١/٣١٠."],[28,"إبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ إبْرَاهِيمَ بْنِ الْحَارِثِ التَّمِيمِيُّ . يُحَدِّثُ عَنْ أَبِيهِ عَنْ جَابِرٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"لاَ تَجْعَلُونِي كَقَدَحِ الرَّاكِبِ\" . لاَ يُتَابَعُ عَلَيْهِ. رَوَى عَنْهُ مُوسَى بْنُ عُبَيْدَةَ.\n• قَالَ الْبُخَارِيُّ: لَمْ يَثْبُتْ حَدِيثُهُ رَوَى عَنْهُ مُوسَى بْنُ عُبَيْدَةَ. ضَعُفَ لِذَلِكَ.\n• الْعُقَيْلِىُّ."],[29,"إبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ عَبْدِ الْعَزِيزِ الزُّهْرِيُّ مَدَنِيٌّ يَرْوِي عَنْ أَبِيهِ .\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ (دِيوَانٌ ١٢) ."],[30,"إِبْرَاهِيمُ بْنُ خُثَيْمِ بْنِ عِرَاكِ بْنِ مَالِكٍ. بَغْدَادِيٌّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ بَغْدَادِيٌّ (الضُّعَفَاءُ وَالْمَتْرُوكِينَ ١٣) ."],[31,"إِبْرَاهِيمُ بْنُ عُثْمَانَ. أَبُو شَيْبَهْ قَاضِي وَاسِطٍ. حَدَّثَنِي أَبُو شَيْبَهٍ عَنِ الْحَكَمِ بْنِ إِبْرَاهِيمَ بْنِ عَطِيَّةَ أَبُو إِسْمَاعِيلَ الثَّقَفِيِّ وَاسْطِي. ذَكَرَ عَنْهُ هُشَيْمٌ عَنْ مُغِيرَةَ عَنْ إِبْرَاهِيمَ. \"النَّظَرُ فِي مِرْآةِ الْحَجَّامِ دَنْأَةٌ\" .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ (الضُّعَفَاءُ وَالْمَتْرُوكِينَ ١٣) ."],[32,"إِبْرَاهِيمُ بْنُ عُمَرَ بْنِ أَبَانَ بَصْرِيٌّ سَمِعَ أَبَاهُ يُحَدِّثُ عَنْ عُمَرَ وَعُثْمَانَ بْنِ عَفَّانَ. رَوَى عَنْهُ أَبُو مَعْبَدٍ الْبَرَّادُ رَوَى عَنْ الزُّهْرِيِّ حَدِيثًا لَمْ يُتَابَعْ عَلَيْهِ .\n• قَالَ ابْنُ حِبَّانَ: لَيْسَ مِمَّنْ يَحْتَجُّ بِخَبَرِهِ إِذَا انْفَرَدَ. (الْمَجْرُوحِينَ١ /. ١١) .."],[33,"إِبْرَاهِيمُ بْنُ عُمَرَ بْنِ سَفِينَةَ يُقَالُ لَهُ بَرِيَّةُ. حَدَّثَ عَنْهُ أَبُو مَعْشَرٍ الْبَرَاءُ. لاَ يُعْرَفُ أَبُوهُ إِلاَّ بِهِ. رَوَى عَنْهُ ابْنُ أَبِي فُدَيْكٍ وَإِبْرَاهِيمُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ وَالْبَصْرِيُّونَ .\n• تَرْجَمَ لَهُ الذَّهَبِيُّ فِي مَوْضِعَيْنِ: الأَوَّلُ فِي بَابِ إِبْرَاهِيمَ- وَالثَّانِي فِي بَابِ بَرِيَّةَ. اُنْظُرْ (مِيزَانَ الِاعْتِدَالِ ١/٥٠/٣٠٦) .."],[34,"إبْرَاهِيمُ بْنُ هُرَاسَةَ الْكُوفِيُّ أَبُو إِسْحَاقَ الشَّيْبَانِيُّ يَرْوِي عَنْ الثَّوْرِيِّ مَا لَا يُتَابَعُ عَلَيْهِ .\n• قَالَ فِيهِ مُسْلِمٌ: ذَاهِبُ الْحَدِيثِ (الْكُنِّى وَالْأَسْمَاءِ ١/٦) ."],[35,"إِبْرَاهِيمُ بْنُ هَدْبِهِ بَصْرِيٌّ. عَنْ أَنَسٍ .\n• قَالَ الذَّهَبِيُّ: كَذَّابٌ (دِيوَانٌ ١٣) ."],[36,"إِبْرَاهِيمُ بْنُ يَزِيدَ الْخَوْزِيُّ. أَبُو إسْمَاعِيلَ سَكَنَ شَعْبَ الْخَوْزِ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكُ (دِيوَانٌ ١٤) ."],[37,"إبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ أَبِي يَحْيِي الْأَسْلَمِيُّ الْمَدِينِيُّ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكٌ عِنْدَ الْجُمْهُورِ. وَقَالَ أَبُو دَاوُدَ: كَانَ قَدَرِيًّا رَافِضِيًّا (دِيوَانٌ ١٣) ."],[38,"إبْرَاهِيمُ بْنُ حَيَّانَ بْنِ حَكِيمٍ وَيُقَالُ ابْنُ الْبَرَأِ مِنْ وَلَدِ أَنَسٍ عَنْ شُعْبَةَ وَمَالِكٍ وَحَمَّادِ بْنِ زَيْدٍ وَشَرِيكٍ .\n• قَالَ الذَّهَبِيُّ: كَأَنَّهُ ابْنُ الْبَرَأِ وَاهٍ (دِيوَانٌ ٩) ."],[39,"إبْرَاهِيمُ بْنُ أَبِي بَكْرِ بْنِ الْمُنْكَدِرِ التَّمِيمِيُّ جَازِيَ عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ ضَعِيفٌ (مِيزَانُ الِاعْتِدَالِ ١/٢٤) ."],[40,"إِبْرَاهِيمُ بْنُ أَبِي حَيَّةَ وَاسْمُ أَبِي حَيَّةَ الْيَسَعُ- رَوَى عَنْهُ قُتَيْبَةُ وَدَاوُدُ بْنُ حَمَّادِ بْنِ فُرَاصَةَ .\n• قَالَ ابْنُ عِرَاقٍ: ابْنُ أَبِي حَيَّةَ بِالْمُثَنَّاةِ التَّحْتِيَّةِ الْمُشَدَّدَةِ (تَنْزِيهُ الشَّرِيعَةِ ١/٢١) ."],[41,"إبْرَاهِيمُ بْنُ زَيْدٍ الْأَسْمَلِيُّ عَنْ مَالِكٍ .\n• قَالَ ابْنُ حِبَّانَ: مُنْكَرُ الْحَدِيثِ جِدًّا (الْمَجْرُوحِينَ ١/١١٣) ."],[42,"إِبْرَاهِيمُ بْنُ عُمَيْرِ بْنِ بَكْرٍ السَّكْسَكِيُّ رَمْلِيٌّ مَتْرُوكٌ يَرْوِي عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ وَعَنِ ابْنِ جُرَيْجٍ وَإِسْمَاعِيلَ بْنِ أُمَيَّةَ. وَرُوَى عَنْ هِشَامِ بْنِ عُرْوَةَ حَدِيثًا مُسْنَدًا .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ (دِيوَانٌ ١١) ."],[43,"إبْرَاهِيمُ بْنُ مُهَاجِرِ بْنِ مِسْمَارٍ الْمَدَنِيُّ . وَالْكُوفِيُّ هُوَ جَابِرٌ يُعْتَبَرُ بِهِ.\n• قَالَ النَّسَائِيُّ: ضَعِيفٌ مَدَنِيٌّ (الضُّعَفَاءُ وَالْمَتْرُوكِينَ ١٢) ."],[44,"إبْرَاهِيمُ بْنُ عُبَيْدِ اللَّهِ بْنِ هَمَّامِ بْنِ أَخِي عَبْدِ الرَّزَّاقِ عَنْ عَمِّهِ كَذَّابٍ يَضَعُ الْحَدِيثَ .\n• انْظُرْ (تَنْزِيهَ الشَّرِيعَةَ ٢٢١) ."],[45,"إبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ خَالِدٍ الْمِصِّيصِيُّ عَنْ الْحَارِثِ بْنِ عَطِيَّةَ وَوَكِيعٍ .\n• قَالَ ابْنُ حِبَّانَ: يُسَوِّي الْحَدِيثَ وَيَسْرِقُهُ (الْمَجْرُوحِينَ ١/١١٦) ."],[46,"إبْرَاهِيمُ بْنُ زَكَرِيَّا الْعَبْدَسَانِيُّ يَرْوِي عَنْ خَالِدٍ الْوَاسِطِيِّ .\n• قَالَ الذَّهَبِيُّ: هُوَ الْعَبْدْسِيُّ وَعَبْدِسِيٌّ مِنْ قُرًى وَاسِطٍ (مِيزَانُ الِاعْتِدَالِ ١/٣١) ."],[47,"إبْرَاهِيمُ بْنُ عَلِىٍّ الْغَزِّيُّ سَكَنَ الْكُوفَةَ عَنْ مَالِكٍ وَيَزِيدَ بْنِ عَبْدِ الْعَزِيزِ بْنِ سِيَاهٍ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِىُّ رَوَى عَنْ سُوَيْدِ بْنِ عَبْدِ الْعَزِيزِ بْنِ سِيَاهٍ (لِسَانِ الْمِيزَانِ ١/٨٤) ."],[48,"إبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ صَدَقَةَ الْعَامِرِيُّ كُوفِيٌّ يَرْوِي عَنْ مَرْوَانَ الْفَزَارِيِّ وَسَعِيدِ بْنِ عَبْدِ الْعَزِيزِ .\n• قَالَ الذَّهَبُ: ي ضَعِيفٌ (دِيوَانٌ ١٢) ."],[49,"إبْرَاهِيمُ بْنُ صَالِحِ بْنِ دِرْهَمٍ الْبَاهِلِيُّ بَصْرِيٌّ مُقِلٌّ يَرْوِي عَنْ أَبِيهِ . أَبُوهُ صَالِحٌ ثِقَةٌ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِىُّ (دِيوَانٌ ١٠) .\n• وَثَّقَهُ ابْنُ مَعِينٍ مِنْ الرَّابِعَةِ- د- (التَّقْرِيبِ وَالتَّهْذِيبِ ١٤٩) ."],[50,"إبْرَاهِيمُ بْنُ صَرَمَةَ بْنِ أَبِي صِرْمَةَ الْأَنْصَارِيُّ عَنْ يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ .\n• قَالَ ابْنُ مَعِينٍ: كَذَّابٌ خَبِيثٌ (لِسَانُ الْمِيزَانِ ١/٥٠) ."],[51,"إبْرَاهِيمُ بْنُ حَمَّادِ بْنِ أَبُو حَازِمٍ الزُّهْرِيُّ الضَّرِيرُ سَكَنَ مِصْرَ عَنْ مَالِكٍ وَالْحِجَازِيِّ .\n• قَالَ ابْنُ حَجَرٍ: ضَعَّفَهُ الدَّارَقُطْنِيُّ (لِسَانُ الْمِيزَانِ ١/٥٠) ."],[52,"إبْرَاهِيمُ بْنُ بَشِيرٍ مَكِّيٌّ عَنْ مَالِكٍ وَابْنِ عُيَيْنِهِ وَمُعَاوِيَةُ الضَّالِّ وَحُبَابِ بْنِ فَضَالَةَ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِىُّ ضَعِيفٌ (لِسَانُ الْمِيزَانِ ١/٤٠) ."],[53,"إبْرَاهِيمُ بْنُ إسْمَاعِيلَ بْنِ مُجَمِّعٍ سَمِعْتُهُ يَقُولُ مَتْرُوكٌ .\n• قَالَ ابْنُ حَجَرٍ ضَعِيفٌ مِنَ السَّابِعَةِ- خت ق-."],[54,"إبْرَاهِيمُ بْنُ إِسْمَاعِيلَ الصِّينِيُّ سَمِعْتُهُ يَقُولُ مَتْرُوكٌ .\n• اُنْظُرْ (دِيوَانَ ٨) ."],[55,"إبْرَاهِيمُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي حَبِيبَةَ سَمِعْتُهُ يَقُولُ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ وَنَفْسُهُ أَحْمَدُ وَضَعَّفَهُ غَيْرُهُ (دِيوَانٌ ٨) ."],[56,"أَحْمَدُ بْنُ عَطَاءٍ الْهُجَيْمِيُّ بَصْرِيٌّ يَرْوِي عَنْ خَالِدٍ الْعَبْدِ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِىُّ مَتْرُوكٌ (لِسَانُ الْمِيزَانِ ١/٢٢١) ."],[57,"أَحْمَدُ بْنُ أُخْتِ عَبْدِ الرَّزَّاقِ كَذَّابٌ .\n• قَالَ ابْنُ عِرَاقٍ مُتَّهَمٌ (تَنْزِيهُ الشَّرِيعَةِ ١/٣٠) ."],[58,"أَحْمَدُ بْنُ الْحَسَنِ الْمُضْرِيُّ مُتَأَخِّرٌ كَذَّابٌ .\n• قَالَ ابْنُ عِرَاقٍ: الْمُضَرِّي بِضَمِّ الْمِيمِ وَبِالضَّادِ الْمُعْجَمَةِ. كَذَّبَهُ الدَّارَقُطْنِىُّ (تَنْزِيهُ الشَّرِيعَةِ ١/٢٦) ."],[59,"أَحْمَدُ بْنُ عَبْدِ اللَّهِ الْفِرْيَابِيُّ مَرْوَزِيٌّ حَدَّثُونَا عَنْهُ يَرْوِي عَنْ أَبِي عَاصِمٍ النَّبِيلِ .\n• قَالَ أَبُو نُعَيْمٍ: كَانَ وَضَاعَا (تَنْزِيهِ الشَّرِيعَةِ ١/٢٨) ."],[60,"أَحْمَدُ بْنُ عَبْدِ اللَّهِ الْجُوَيْبَارِيُّ هَرْوِىٌّ كَذَّابٌ .\n• قَالَ ابْنُ عِرَاقٍ: دَجَّالٌ وَضَعَ حَدِيثًا كَثِيرًا (تَنْزِيهُ الشَّرِيعَةِ ١/٢٨) ."],[61,"أَحْمَدُ بْنُ مَعْدَانَ الْعَبْدِيُّ عَنْ ثَوْرِ بْنِ يَزِيدَ رَوَى عَنْهُ مُحَمَّدٌ ابْنُ وَزِيرٍ الْوَاسِطِيُّ مَتْرُوكٌ .\n• دِيوَانٌ ٦) ."],[62,"أَحْمَدُ بْنُ عَلِيِّ بْنِ أُخْتِ عَبْدِ الْقُدُّوسِ عَنْ مَالِكٍ. مُقِلٌّ مَتْرُوكٌ."],[63,"أَحْمَدُ بْنُ مُحَمَّدٍ الْأَنْصَارِيُّ أَبُو عُقْبَةَ بَصْرِيٌّ سَكَنَ الْجَزِيرَةَ عَنْ عَبْدِ الْأَعْلَى بْنِ عَبْدِ الْأَعْلَى حَدَّثَ عَنْهُ هِلَالُ بْنُ الْعَلَا .\n• قَالَ الذَّهَبِيُّ: ضَعِيفٌ وَاهٍ (دِيوَانٌ ٦) ."],[64,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ مَالِكِ بْنِ أَنَسٍ عَنْ ابْنِ أَبِي أُوَيْسٍ عَنْ أَبِيهِ عَنْ جَدِّهِ .\n• قَالَ ابْنُ حِبَّانَ: مُنْكِرُ الْحَدِيثِ (لِسَانُ الْمِيزَانِ ١/٢٩٢) ."],[65,"أَحْمَدُ بْنُ عَاصِمٍ الْمَوْصِلِيُّ عَنْ مَالِكٍ .\n• دِيوَانٌ ٥) ."],[66,"أَحْمَدُ بْنُ دَهْثَمٍ الْأَسَدِيُّ عَنْ مَالِكٍ مَتْرُوكٌ .\n• دِيوَانٌ ٣) ."],[67,"أَحْمَدُ بْنُ سُلَيْمَانَ الْقُرَشِيُّ الْخُفَّتَانِيُّ عَنْ مَالِكٍ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ كَذَّابٌ (دِيوَانٌ ٣) ."],[68,"أَحْمَدُ بْنُ الْحَكَمِ الْعَبْدِيُّ كُوفِيٌّ عَنْ شَرِيكٍ وَالْكُوفِيِّينَ .\n• اُنْظُرْ (دِيوَانَ ٣) ."],[69,"أَحْمَدُ بْنُ يُحَيِّ الْأَحْوَلُ الْكُوفِيُّ عَنْ مَالِكٍ وَشَرِيكٍ .\n• اُنْظُرْ (دِيوَانَ ٧) ."],[70,"أَحْمَدُ بْنُ عَمَّارِ بْنِ نَصْرٍ عَنْ مَالِكٍ مُقِلٌّ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِىُّ مَتْرُوكٌ (لِسَانُ الْمِيزَانِ ١/٢٣٤) ."],[71,"أَحْمَدُ بْنُ مُحَمَّدٍ صَاحِبُ بَيْتِ الْحِكْمَةِ لَهُ حَدِيثٌ وَاحِدٌ عَنْ مَتْرُوكٍ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِيُّ حَدَّثْ عَنْ مَالِكٍ. مَتْرُوكٌ (لِسَانُ الْمِيزَانِ ١/٢٩٦) ."],[72,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ عُمَرَ بْنِ يُونُسَ بْنِ الْقَاسِمِ يَمَانِي عَنْ جَدِّهِ وَعَبْدِ الرَّزَّاقِ .\n• قَالَ الْحَاكِمُ: لَهُ أَفْرَادٌ وَعَجَائِبُ (مِيزَانُ الاِعْتِدَالِ ١/١٤٧) ."],[73,"أَحْمَدُ بْنُ الْحَسَنِ بْنِ الْقَاسِمِ الْكُوفِيُّ سَكَنَ مِصْرً- يَعْرِفُ بِرَسُولِ نَفْسِهِ عَنْ ابْنِ عُيَيْنِهِ وَوَكِيعٌ مَتْرُوكٍ .\n• اُنْظُرْ (مِيزَانَ الِاعْتِدَالِ ١/٩٠) ."],[74,"أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ مَيْسَرَةَ النَّهَاوَنْدِيُّ أَبُو مَيْسَرَةَ عَنْ أَبِي مُعَاوِيَةَ وَالْكُوفِيِّينَ .\n• قَالَ ابْنُ حِبَّانَ: يَسْرِقُ أَحَادِيثَ الثِّقَاتِ وَيَلْزِقُهَا بِأَقْوَامِ أَثْبَاتٍ لاَ يَحِلُّ الاِحْتِجَاجُ بِهِ (الْمَجْرُوحِينَ ١/ ١٤٤) ."],[75,"أَحْمَدُ بْنُ دَاوُد بْنِ عَبْدِ الْغَفَّارِ الْحَرَّانِيُّ عَنْ أَبِي مُصْعَبٍ مَتْرُوكٌ كَذَّابٌ - وَجَدَهُ عَبْدُ الْغَفَّارِ بْنُ دَاوُد مِنْ الثِّقَاتِ ـ\n• اُنْظُرْ (دِيوَانَ ٣) .\n• قَالَ ابْنُ حَجَرٍ: ثِقَةٌ فَقِيهٌ مِنَ الْعَاشِرَةِ- خ دَسَّ ق- (تَقْرِيبُ التَّهْذِيبِ ٢١٦) ."],[76,"أَحْمَدُ بْنُ عِيسَى بْنِ عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ أَبُو طَاهِرٍ عَنِ ابْنِ أَبِي فُدَيْكٍ وَابْنُهِ وَأَبُوهُ عِيسَى يُعْرَفُ بِمُبَارَكٍ وَجَدَهُ عَبْدُ اللَّهِ بْنُ صَالِحٍ حَدَّثَ عَنْهُ أَبُو أُسَامَةَ كَذَّابٌ .\n• انْظُرْ (مِيزَانَ الاِعْتِدَالِ ١/١٢٦) ."],[77,"أَحْمَدُ بْنُ طَاهِرِ بْنِ حَرْمَلَهِ بْنِ يُحَيٍّ التُّجِيبِيُّ مِصْرِيٌّ يَكْذِبُ .\n• اُنْظُرْ (دِيوَانٍ٤) ."],[78,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ عِيسَى السَّكُونِيُّ بَغْدَادِيٌّ عَنْ أَبِي يُوسُفَ الْقَاضِي وَأَبُو بَكْرِ بْنِ عَيَّاشٍ .\n• اُنْظُرْ (دِيوَانَ ٥) ."],[79,"أَحْمَدُ بْنُ مُيْتُمِ بْنِ أَبِي نُعَيْمٍ الْفَضْلُ بْنُ دُكَيْنٍ كُوفِيّ عَنْ جَدِّهِ وَعَلِيِّ بْنِ قَادِمٍ .\n• اُنْظُرْ (دِيوَانَ ٦) ."],[80,"أَحْمَدُ بْنُ صَالِحٍ الْمَكِّيُّ السُّمُومِيُّ أَبُو جَعْفَرٍ يُحَدِّثُ عَنْهُ شُيُوخُنَا .\n• انْظُرْ (مِيزَانَ الاِعْتِدَالِ ١/١٠٤) ."],[81,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ خَالِدِ بْنِ مِرْدَاسٍ غُلَامُ خَلِيلٍ مَتْرُوكٌ .\n• قَالَ ابْنُ عِرَاقٍ: مَعْرُوفٌ بِالْوَضْعِ (تَنْزِيهُ الشَّرِيعَةِ ١/٣٣) ."],[82,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ مُفْلِسِ بْنِ الصَّلْتِ الْحِمَّانِيُّ أَبُو الْعَبَّاسِ ابْنُ أَخِي جُبَارَةَ بْنِ الْمُفْلِسِ الْبَغْدَادِيُّ عَنْ مَالِكٍ الزَّاهِدِ وَإِسْمَاعِيلَ بْنِ أَبِي أُوَيْسٍ وَأَبِى عُبَيْدٍ وَمَنْ بَعْدَهُمْ يَضَعُ الْحَدِيثَ .\n• انْظُرْ (لِسَانَ الْمِيزَانِ ١/٢٦٩، تَنْزِيهِ الشَّرِيعَةُ ١/٣٣) ."],[83,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ عَمْرِو بْنِ مُصْعَبِ بْنِ بِشْرٍ أَبُو بِشْرٍ الْمَرْوَزِيُّ يَضَعُ الْحَدِيثَ عَنْ أَبِيهِ عَنْ جَدِّهِ .\n• قَالَ ابْنُ عِرَاقٍ: كَذَّابٌ وَضَعَ شَيْئًا كَثِيرًا (تَنْزِيهُ الشَّرِيعَةِ ١/٣٣) ."],[84,"أَحْمَدُ بْنُ الْعَبَّاسِ الْهَاشِمِيُّ أَبُو بَكْرٍ الْبَصْرِيُّ زَوْجُ أُمِّ مُوسَى عَنْ مُحَمَّدِ بْنِ عَبْدِ الْأَعْلَى الصَّنْعَانِيِّ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: سَاقِطُ (دِيوَانٌ ٤) ."],[85,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَرْبٍ أَبُو الْحَسَنِ الْمُلْحِمِيُّ حَدَّثَ عَنْهُ شَيْخُنَا الْأَنْبَدُونِيُّ .\n• قَالَ ابْنُ عَدِيٍّ: يَتَعَمَّدُ الْكَذِبَ وَيَضَعُ (مِيزَانَ الاِعْتِدَالِ١/١٣٤)"],[86,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ الْفَضْلِ الْمَقْدِسِيَّ الْأَيْلِيُّ عَنْ نَصْرِ بْنِ عَلِيٍّ وَغَيْرِهِ .\n• قَالَ الذَّهَبِيُّ: دَجَّالٌ (دِيوَانٌ ٦) ."],[87,"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ الْأَزْهَرِ بْنِ حَرْفَا السِّجِسْتَانِيُّ حَدَّثُونَا عَنْهُ أَبُو الْعَبَّاسِ الْأَزْهَرِيُّ وَبَلَغَنِي أَنَّ ابْنَ خُزَيْمَةَ حَسَّنَ الرَّأْيَ فِيهِ .\n• قَالَ السُّلَمِيُّ: سَأَلْتُ الدَّارَقُطْنِيَّ عَنْ الْأَزْهَرِيِّ فَقَالَ مُنْكِرُ الْحَدِيثِ لَكِنْ بَلَغَنِي أَنَّ ابْنَ خُزَيْمَةَ حَسَّنَ الرَّأْيَ فِيهِ وَيَكْفِي بِهَذَا فَخْرًا (مِيزَانَ الِاعْتِدَالِ ١/١٣١) ."],[88,"أَحْمَدُ بْنُ عَلِيِّ بْنِ سَلْمَانَ الْمَرْوَزِيُّ عَنْ إبْرَاهِيمَ بْنِ الْمُنْذِرِ وَالْمَدَنِيِّينَ .\n• دِيوَانٌ ٥) ."],[89,"أَحْمَدُ بْنُ أَبِي سُلَيْمَانَ الْقَوَارِيرِيُّ بَغْدَادِيٌّ أَبُو جَعْفَرٍ عَنْ حَمَّادِ بْنِ سَلَمَةَ رَوَى عَنْهُ ابْنُ مَخْلَدٍ وَنَهْشَلٌ مِنْ بَابِ الشَّعِيرِ .\n• قَالَ ابْنُ حَجَرٍ: قَالَ الدَّارَقُطْنِيُّ رُوِىَ عَنْ حَمَّادِ بْنِ سَلَمَةَ مَقْلُوبَاتٌ كَانَ مُغَفَّلًا يُتْرَكُ وَلاَ يُحْتَجُّ بِهِ. وَقَالَ فِي الْعِلَلِ ضَعِيفٌ - (أَنْظُرُ لِسَانَ الْمِيزَانِ ١/١٨٣) ."],[90,"أَحْمَدُ بْنُ حَمِّكَ النَّيْسَابُورِيُّ أَبُو حَفْصٍ عَنْ ابْنِ مَاسَرْجَسَ وَنُظَرَائِهِ .\n• مِيزَانُ الاِعْتِدَالِ ١/٩٥."],[91,"أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ الْمُؤَدِّبُ أَبُو جَعْفَرٍ يُعْرَفُ بِالْهُشَيْمِيِّ عَنْ عَبْدِ الرَّزَّاقِ .\n• قَالَ ابْنُ عَدِىٍّ: كَانَ بِسَامِرَاءَ يَضَعُ الْحَدِيثَ. مِيزَانُ الاِعْتِدَالِ ١/١٠٩."],[92,"أَحْمَدُ بْنُ الْخَلِيلِ بْنِ مَالِكِ بْنِ مَيْمُونٍ أَبُو الْعَبَّاسِ بَغْدَادِيٌّ يُعْرَفُ بِجَوْرٍ عَنْ أَبِي بَكْرِ بْنِ عَيَّاشٍ وَالْأَصْمَعِيِّ وَزَيْنَبَ بِنْتِ سُلَيْمَانَ .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِىُّ ضَعِيفٌ لاَ يُحْتَجُّ بِهِ. مِيزَانُ الاِعْتِدَالِ ١/٩٦."],[93,"أَحْمَدُ بْنُ خَالِدٍ الشَّيْبَانِيُّ عَنْ عِيسَى بْنِ يُونُسَ .\n• قَالَ الذَّهَبِيُّ: جَرَحَهُ الدَّارَقُطْنِىُّ دِيوَانٌ ٣."],[94,"أَحْمَدُ بْنُ يَحْيَى بْنِ أَبِي الْعَبَّاسِ الْخُوَارِزْمِيُّ عَنْ ابْنٍ فَهَزَّادٍ وَغَيْرِهِ مَتْرُوكٌ .\n• لِسَانُ الْمِيزَانِ ١/٣٢١."],[95,"أَحْمَدُ بْنُ الْخَلِيلِ الْقَوْمَسِيُّ ضَعَّفَهُ أَبُو زُرْعَةَ الرَّازِيّ .\n• وَقَالَ أَبُو حَاتِم: كَذَّابٌ. الْجُرْحُ وَالتَّعْدِيلُ ١/ ١/٥٠، لِسَانُ الْمِيزَانِ ١/١٦٧."],[96,"أَحْمَدُ بْنُ عِيسَى بْنِ زَيْدٍ التَّنِيسَى عَنْ أَبِي حَفْصٍ وَعَبْدِ اللَّهِ بْنِ يُوسُفَ مِصْرِيٌّ لَيْسَ بِالْقَوِيِّ .\n• قَالَ أَبُو حَاتِمٍ: تَكَلَّمَ النَّاسُ فِيهِ. الْجُرْحُ وَالتَّعْدِيلُ ١/١/٦٤."],[97,"إسْمَاعِيلُ بْنُ أَبِي إِسْحَاقَ أَبُو إسْرَائِيلَ الْمُلَائِيُّ .\n• قَالَ ابْنُ حَجَرٍ: سَيِّئَ الْحِفْظُ- ت ق- مِنَ السَّابِعَةِ. تَقْرِيبُ التَّهْذِيبِ ٣٣."],[98,"إسْمَاعِيلُ بْنُ أَبَانَ الْفَنَوِيُّ كُوفِيٌّ أَبُو إِسْحَاقَ الْقَيْسِيُّ الْكُوفِيُّ عَنْ الْحَكَمِ وَعَطِيَّةُ وَفُضَيْلُ ابْنُ عَمْرٍو الْخَيَّاطُ عَنْ هِشَامِ بْنِ عُرْوَةَ .\n• مَتْرُوكٌ رُمِيَ بِالْوَضْعِ - تَمَيَّزَ- مِنَ التَّاسِعَةِ. تَقْرِيبُ التَّهْذِيبِ ٣١."],[99,"إسْمَاعِيلُ بْنُ سَلْمَانَ الْكُوفِيُّ الْأَزْرَقُ عَنْ أَبِيهِ وَالشَّعْبِيِّ وَابْنِ عُمَرَ .\n• قَالَ الذَّهَبِيُّ ضَعَّفُوهُ- ق- دِيوَانٌ ٢١."],[100,"إسْمَاعِيلُ بْنُ مُسْلِمٍ الْمَكِّيُّ أَصْلُهُ بَصْرِيٌّ عَنْ الْحَسَنِ وَابْنِ سِيرِينَ وَقَتَادَةَ وَالْحَكَمِ وَالْأَعْمَشِ وَالزُّهْرِيِّ .\n• مُتَّفَقٌ عَلَى ضَعْفِهِ. دِيوَانٌ ٢٣."],[101,"إسْمَاعِيلُ بْنُ يَعْلَى أَبُو أُمَيَّةَ الثَّقَفِيُّ بَصَرِيٌّ مَتْرُوكٌ .\n• ٨١قَالَ ابْنُ حَجَرٍ: ضَعِيفُ الْحِفْظِ مِنَ السَّابِعَةِ. تَقْرِيبُ التَّهْذِيبِ ٣٣."],[102,"إِسْمَاعِيلُ بْنُ رَافِعٍ هُوَ أَبُو رَافِعٍ مَدَنِيٌّ عَنْ أَنَسٍ وَابْنِ أَبِي مُلَيْكَةَ وَالْمَقْبُرِيِّ وَالزُّهْرِيِّ. شَيْخُ الْعَطَّافِ بْنُ خَالِدٍ وَالْوَلِيدُ بْنُ مُسْلِمٍ وَغَيْرُهُمَا- رَوَى عَنْ أَنَسٍ حَدِيثًا طَوِيلًا فِي الطَّهَارَةِ وَالْحَجِّ .\n• ٨٢قَالَ صَالِحٌ جَزْرُهُ: كَانَ يَضَعُ الْحَدِيثَ. تَنْزِيهُ الشَّرِيعَةُ ١/٤٠."],[103,"إسْمَاعِيلُ بْنُ يَحْيَى بْنِ عُبَيْدِ اللَّهِ التَّيْمِيُّ حَوَّالٌ عَنْ ابْنِ جُرَيْجٍ وَالثَّوْرِيُّ حَدَّثَ عَنْهُ هِلَالُ ابْنُ الْعَلَاءِ مَتْرُوكٌ كَذَّابٌ .\n• ٨٣دِيوَانُ ٢١."],[104,"إسْمَاعِيلُ بْنُ عَبَّادٍ بَصْرِيٌّ عَنْ ابْنِ أَبِي عُرُوبِهِ عَنْ قَتَادَةَ مَتْرُوكٌ .\n• ٨٤قَالَ ابْنُ طَاهِرٍ: كَذَّابٌ. تَنْزِيهُ الشَّرِيعَةُ ١/٣٩."],[105,"إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ يُوسُفَ الْجَبْرِينِىُّ أَبُو هَارُونَ عَنْ أَبِي عُبَيْدٍ وَعَنْ حَبِيبٍ كَاتَبَ مَالِكٌ وَغَيْرُهُ .\n• ٨٥اتَهُمْهُ ابْنُ عَدِيٍّ. تَنْزِيهُ الشَّرِيعَةُ ١/٣٨."],[106,"إسْمَاعِيلُ بْنُ رَجَاءٍ الْحِصْنِيُّ جَزَرِيٌّ عَنْ مُوسَى بْنِ أَعْيَنَ .\n• ٨٦لِسَانُ الْمِيزَانِ ١/٤٠٦."],[107,"إسْمَاعِيلُ بْنُ أَبِي زِيَادٍ وَهُوَ إسْمَاعِيلُ بْنُ مُسْلِمٍ السَّلُولِيُّ وَيُقَالُ الشَّعِيرِيُّ كُوفِيٌّ عَنْ دَاوُد بْنِ أَبِي هِنْدٍ وَابْنِ عَوْنٍ يَضَعُ كَذَّابٌ مَتْرُوكٍ .\n• ٨٧مِيزَانُ الاِعْتِدَالِ ١/٢٥٤."],[108,"إسْمَاعِيلُ بْنُ يَحْيَى بْنِ سَلَمَةَ بْنِ كُهَيْلٍ سَمِعْتُهُ يَقُولُ مَتْرُوكٌ .\n• ٨٨قَالَ الذَّهَبِيُّ: ضَعَّفَهُ غَيْرُ وَاحِدٍ. دِيوَانٌ ٢٢."],[109,"إسْمَاعِيلُ بْنُ عَمْرٍو الْبَجَلِيُّ الْأَصْبَهَانِيُّ ضَعِيفٌ ."],[110,"إِسْمَاعِيلُ بْنُ مُحَمَّدٍ الْمُزَنِيُّ كُوفِيٌّ حَدَّثُونَا عَنْهُ كَذَّابٌ."],[111,"إسْمَاعِيلُ بْنُ هُودٍ الْوَاسِطِىُّ لَيْسَ بِالْقَوِيِّ يُكَنّى أَبَا إِبْرَاهِيمَ .\n• مِيزَانُ الاِعْتِدَالِ ١/٢٤٦."],[112,"إِسْحَاقُ بْنُ بِشْرِ بْنِ مُقَاتِلٍ أَبُو يَعْقُوبَ الْكَاهِلِيُّ كُوفِيٌّ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: كَذَّابٌ. دِيوَانٌ ١٧."],[113,"إِسْحَاقُ بْنُ إدْرِيسَ الْأَسْوَارِيُّ بَصْرِيٌّ عَنْ هَمَّامٍ وَأَبَانَ مُنْكِرُ الْحَدِيثِ .\n• قَالَ الذَّهَبِيُّ: كَذَّابٌ. دِيوَانٌ ١٧."],[114,"إِسْحَاقُ بْنُ بِشْرٍ أَبُو حُذَيْفَةَ الْبُخَارِيُّ كَذَّابٌ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ. مَتْرُوكٌ مُتَّهَمٌ. دِيوَانٌ ١٧."],[115,"إِسْحَاقُ بْنُ نَجِيحٍ الْمُلَطِيُّ عَنْ عَطَاءٍ الْخُرَاسَانِيِّ وَابْنِ جُرَيْجٍ وَهِشَامُ بْنُ حَسَّانَ مَتْرُوكٌ .\n• قَالَ ابْنُ حَجَرٍ: كَذَّبُوهُ مِنَ التَّاسِعَةِ- تَمَيَّزَ- تَقْرِيبُ التَّهْذِيبِ ٣٠."],[116,"إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي فَرْوَةَ مَتْرُوكٌ . لَهُ ثَلاَثَةُ اخْوَةٌ ثِقَاتٌ- وَابْنُ عَمِّهِمْ أَبُو عَلْقَمَةَ ثِقَةٌ.\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ الرَّابِعَةِ- د ت ق- تَقْرِيبُ التَّهْذِيبِ ٢٩."],[117,"إِسْحَاقُ بْنُ الصَّبَّاحِ الأَشْعَثِيُّ مِنْ وَلَدِ الأَشْعَثِ بْنِ قَيْسٍ الْكِنْدِيِّ عَنْ عَبْدِ الْمَلِكِ ابْنِ عُمَيْرٍ رَوَى عَنْهُ الْخُرَيْبِيُّ. لِجَدِّهِ صَحْبَهُ .\n• قَالَ الذَّهَبِيُّ: ضَعْفُهُ يُحِيُّ وَالدَّارَقُطْنِيُّ، وَقَلْ مَا رَوَى. مِيزَانُ الاِعْتِدَالِ ١/١٩٢."],[118,"إِسْحَاقُ بْنُ أَبُو يَحْيَى الْكَعْبَةُ عَنْ ابْنِ جُرَيْجٍ رَوَى عَنْهُ عَلِيُّ بْنُ مَعْبَدٍ الْمِصْرِيُّ مُنْكَرُ الْحَدِيثِ .\n• قَالَ الذَّهَبِيُّ: هَالِكٌ يَأْتِي بِالْمَنَاكِيرِ عَنِ الأَثْبَاتِ. مِيزَانُ الاِعْتِدَالِ ١/٢٠٥."],[119,"إِسْحَاقُ بْنُ إِبْرَاهِيمَ بْنِ نِسْطَاسٍ مَدَنِيٌّ. أَبُو يَعْقُوبَ مَوْلَى آلِ كَثِيرِ بْنِ الصّلْتِ عَنْ سَعْدِ بْنِ إسْحَاقَ بْنِ كَعْبِ بْنِ عَجْرِهِ .\n• قَالَ الْبُخَارِيُّ. فِيهِ نَظَرٌ. التَّارِيخُ الْكَبِيرُ ١/١/٣٨٠."],[120,"إِسْحَاقُ بْنُ إبْرَاهِيمَ الطَّبَرِيُّ يَمَانِيٌّ مُنْكَرُ الْحَدِيثِ .\n• مِيزَانُ الاِعْتِدَالِ ١/١٧٧."],[121,"إِسْحَاقُ بْنُ سَعِيدٍ (بْنِ أَبُو كَعْبٍ) شَامِيٌّ مُنْكَرُ الْحَدِيثِ.\n• فِي الْحَاشِيَةِ ابْنِ أَرْكُونَ وَهُوَ الصَّوَابُ لِمُوَافَقَتِهِ لِكُتُبِ الرِّجَالِ. انْظُرْ مِيزَانَ الاِعْتِدَالِ ١/١٩٢."],[122,"إِسْحَاقُ بْنُ مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ الْعَيْزَمِيُّ أَخُو عَبْدِ الرَّحْمَنِ وَأَخُوهُ مَتْرُوكٌ رَأْسًا .\n• قَالَ الذَّهَبِيُّ: عَنْ إِسْحَاقَ تَكَلَّمَ فِيهِ. وَقَالَ عَنْ أَخِيهِ ضَعَّفَهُ الدَّارَقُطْنِيُّ. انْظُرْ مِيزَانَ الاِعْتِدَالِ ١/١١٩ دِيوَانٌ ١٩٠."],[123,"إِسْحَاقُ بْنُ وَهْبٍ الطَّهْرَمْسِيُّ مِنْ قُرَى مِصْرَ كَذَّابٌ مَتْرُوكٍ يُحَدِّثُ بِالْأَبَاطِيلِ عَنْ عَبْدِ اللَّهِ بْنِ وَهْبٍ وَغَيْرِهِ .\n• مِيزَانُ الاِعْتِدَالِ١/٢٠٣."],[124,"إِسْحَاقُ بْنُ عُمَرَ عَنْ عَائِشَةَ مَجْهُولٌ يُتْرَكُ .\n• مِيزَانُ الاِعْتِدَالِ ١/١٩٥."],[125,"أَبَانُ بْنُ أَبِي عَيَّاشٍ بَصْرِيٌّ وَهُوَ ابْنُ فَيْرُوزَ يُحَدِّثُ عَنْ أَنَسٍ مَتْرُوكٌ .\n• قَالَ الإِمَامُ أَحْمَدُ: تَرَكَ النَّاسُ حَدِيثَهُ. الْعِلَلُ وَمَعْرِفَةُ الرِّجَالِ ١٣٥."],[126,"أَبَانَ وَالِدُ يَزِيدَ بْنِ أَبَانَ الرَّقَاشِيُّ مَجْهُولٌ لَا يُعْرَفُ إِلَّا بِابْنِهِ لَهُ حَدِيثٌ وَاحِدٌ .\n• انْظُرْ دِيوَانَ ٧."],[127,"أَبَانُ بْنُ سُفْيَانَ جَزَرِيٌّ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: وَقِيلَ إِنَّهُ أَبْيَنُ مُتَّهَمٌ دِيوَانٌ ٧."],[128,"أَبَانُ بْنُ الْمَجْدِ رَوَى عَنْهُ مَرْوَانُ الْفَزَارِيُّ مُقِلٌّ مَتْرُوكٌ .\n• مِيزَانُ الاِعْتِدَالِ ١/١٥."],[129,"أَبَانُ بْنُ جَبَلَةَ كُوفِيٌّ .\n• مِيزَانُ الاِعْتِدَالِ ١/٦."],[130,"أَيُّوبُ بْنُ خَوْطٍ بَصْرِيٌّ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ. دِيوَانٌ ٢٦."],[131,"أَيُّوبُ بْنُ سَيَّارٍ مَدَنِيٌّ نَزَلَ فَيَدٌ يُعْرَفُ بِالْفَيدِيِّ مُنْكَرُ الْحَدِيثِ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكٌ. مِيزَانُ الاِعْتِدَالِ ١/٢٢٨."],[132,"أَيُّوبُ بْنُ مُدْرِكٍ الْحَنَفِيُّ شَامِلٌ مَتْرُوكٌ .\n• الضُّعَفَاءُ وَالْمَتْرُوكِينَ لِلنَّسَائِيِّ ١٥."],[133,"أَيُّوبُ بْنُ وَاقِدٍ نَزَلَ الْبَصْرَةَ مُقِلٌّ كُوفِيٌّ .\n• قَالَ النَّسَائِيُّ: بَصْرِي ضَعِيفُ الضُّعَفَاءِ وَالْمَتْرُوكِينَ ١٦."],[134,"أَصْلُهُ عَنْ عُثْمَانَ بْنِ حَكِيمٍ وَهِشَامِ بْنِ عُرْوَةَ مُنْكَرُ الْحَدِيثِ."],[135,"أَشْعَثُ بْنُ بَزَّارٍ بَصْرِيٌّ مُقِلٌّ مُنْكَرُ الْحَدِيثِ."],[136,"أَشْعَثُ بْنُ سَعِيدٍ أَبُو الرَّبِيعِ السَّمَّانُ بَصْرِيٌّ مَتْرُوكٌ."],[137,"أُسَيْدُ بْنُ زَيْدٍ الْحَمَّالُ . أَشْعَثُ بْنُ سَوَّارٍ كُوفِيٌّ ضَعِيفٌ. كُوفِيَ أَبُو مُحَمَّدٍ مَتْرُوكٌ سَمِعَ شَرِيكًا وَلَيْثَ بْنَ سَعْدٍ وَهُشَيْمٌ.\n• انْظُرْ الْكَامِلَ ١/١/٢٨٢."],[138,"أَصْرَمُ بْنُ حَوْشَبٍ الْهَمْدَانِىُّ أَبُو هِشَامٍ مُنْكَرُ الْحَدِيثِ."],[139,"أَصْرَمُ بْنُ غِيَاثٍ الْخُرَاسَانِيُّ مُنْكَرُ الْحَدِيثِ .\n• قَالَ الإِمَامُ أَحْمَدُ وَالْبُخَارِيُّ وَالرَّازِيُّ: مُنْكَرُ الْحَدِيثِ. التَّارِيخُ الْكَبِيرُ ٢/١/٥٦، الْجُرْحَ وَالتَّعْدِيلَ ١/١/٣٣٦، لِسَانَ الْمِيزَانِ ١/٤٦٢."],[140,"أَصْبَغُ بْنُ نَبَاتِهِ كُوفِيٌّ مُنْكَرُ الْحَدِيثِ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٢٢."],[141,"أَزْوَرُ بْنُ غَالِبٍ مُنْكَرُ الْحَدِيثِ .\n• قَالَ الذَّهَبِيُّ: مُنْكَرُ الْحَدِيثِ مَجْهُولٌ دِيوَانٌ ١٦."],[142,"أَبْيَضُ بْنُ أَبَانَ عَنْ عَطَاءِ بْنِ السَّايِبِ يَرْوِي عَنْهُ أَحْمَدُ بْنُ يُونُسَ .\n• لِسَانُ الْمِيزَانِ ١/١٢٨."],[143,"أَوْسُ بْنُ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ مَرْوَزِيٌّ مَتْرُوكٌ .\n• لِسَانُ الْمِيزَانِ ١/٤٧٠."],[144,"الْأَحْوَصُ بْنُ حَكِيمٍ الْحِمْصِيُّ مُنْكِرُ الْحَدِيثِ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفُ الْحِفْظِ مِنْ الْخَامِسَةِ- ق- تَقْرِيبُ التَّهْذِيبِ ٢٥."],[145,"إدْرِيسُ بْنُ سِنَانٍ عَنْ وَهْبِ بْنِ مُنَبِّهٍ رَوَى عَنْهُ ابْنُهُ عَبْدُ الْمُنْعِمِ .\n• دِيوَانٌ ١٥."],[146,"بِشْرُ بْنُ رَافِعٍ النَّجْرَانِيُّ مِنْ الْيَمَنِ الْحَارِثِيُّ أَبُو الْأَسْبَاطِ كَنَّاهُ حَاتِمُ بْنُ إِسْمَاعِيلَ مُنْكَرُ الْحَدِيثِ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفُ الْحَدِيثِ مِنَ السَّابِعَةِ- بَخ د ت ق- تَقْرِيبَ التَّهْذِيبِ ٤٤."],[147,"بِشْرُ بْنُ نُمَيْرٍ الْقُشَيْرِيُّ بَصْرِيٌّ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكٌ عِنْدَهُمْ- ق- دِيوَانٌ ٣٢."],[148,"بِشْرُ بْنُ حُسَيْبٍ حُسَيْنٌ أَصْبَهَانِيٌّ عَنِ الزُّبَيْرِ بْنِ عَدِيٍّ وَلَهُ عَنْهُ نُسْخَةٌ مَوْضُوعَةٌ. قَالَ وَالزُّبَيْرُ ثِقَةٌ .\n• دِيوَانٌ ٣١."],[149,"بِشْرُ بْنُ عُمَارَةَ الْخَثْعَمِيُّ. قَالَ لِي مَتْرُوكٌ .\n• قَالَ النَّسَائِيُّ: ضَعِيفُ الضُّعَفَاءِ وَالْمَتْرُوكِينَ ٢٤."],[150,"بَكْرُ بْنُ خُنَيْسٍ الْقَاضِي كَانَ بِبَغْدَادَ .\n• دِيوَانٌ ٣٤."],[151,"بِشْرُ بْنُ مَيْمُونٍ الْوَصْفِيُّ وَاسْطِي عَنْ مُجَاهِدٍ .\n• دِيوَانُ ٣٣."],[152,"بَحْرُ بْنُ كُنَيْزٍ السَّقَا بَصْرِيٌّ وَيُكَنَّى أَبَا الْفَضْلِ مَتْرُوكٌ عَنْ الْحَسَنِ وَالزُّهْرِيِّ .\n• قَالَ الذَّهَبِيُّ: مُتَّفَقٌ عَلَى تَرْكِهِ دِيوَانٌ ٢٨."],[153,"بَكْرُ بْنُ الشُّرُودِ صَنْعَانِيٌّ عَنْ الثَّوْرِيِّ وَمَالِكٍ وَمَعْمَرٍ .\n• لِسَانُ الْمِيزَانِ ٢/٥٢."],[154,"بُزَيْعُ بْنُ حَسَّانَ أَبُو الْخَلِيلِ مَتْرُوكٌ . كُوفِيَ عَنِ الأَعْمَشِ وَهِشَامِ بْنِ عُرْوَةَ بِوَاصِلٍ.\n• قَالَ ابْنُ حَجَرٍ: قَالَ الْبَرْقَانِيُّ عَنِ الدَّارَقُطْنِيِّ مَتْرُوكٌ- لِسَانُ الْمِيزَانِ ٢/١٢."],[155,"بَكْرُ بْنُ الْأَسْوَدِ أَبُو عُبَيْدِهْ النَّاجِي بَصْرِيٌّ عَنْ الْحَسَنِ وَابْنِ سِيرِينَ مَوَاعِظَ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكُ دِيوَانٍ ٣٤."],[156,"بُرَيْدَةُ بْنُ سُفْيَانَ بْنِ فُتُوَةَ الْآسْلَمِيُّ رَوَى عَنْهُ مُحَمَّدُ بْنُ إِسْحَاقَ وَأَفْلَحُ بْنُ سَعِيدٍ الْمَدَنِيُّ مَتْرُوكٌ .\n• دِيوَانٌ ٣٠."],[157,"بَابُ بْنُ عُمَيْرٍ عَنْهُ الْأَوْزَاعِيُّ وَيُحَيُّ بْنُ أَبِي كَثِيرٍ مَجْهُولٌ .\n• قَالَ الذَّهَبِيُّ: تَابِعِيٌّ مَجْهُولٌ- د- دِيوَانٍ ٢٨."],[158,"بُرْكُهُ بْنُ يَعْلَى عَنْ أَبِي سُوَيْدٍ الْعَبْدِيِّ عَنْ ابْنِ عُمَرَ مَجْهُولَانِ .\n• لِسَانُ الْمِيزَانِ ٢/٩."],[159,"تَمَّامُ بْنُ بَزِيعٍ أَبُو سَهْلٍ بَصْرِيٌّ مَتْرُوكٌ عَنْ مُحَمَّدِ بْنِ كَعْبٍ وَالْحَسَنِ وَالْعَامِرِ ابْنِ عُمَرَ الطَّفَّاوِيِّ .\n• لِسَانُ الْمِيزَانِ ٢/٧١."],[160,"ثَابِتُ بْنُ زُهَيْرٍ أَبُو زُهَيْرٍ بَصْرِيٌّ عَنْ نَافِعٍ وَهِشَامِ بْنِ عُرْوَةَ مُنْكَرُ الْحَدِيثِ .\n• لِسَانُ الْمِيزَانِ ٢/٧٦."],[161,"ثَابِتُ بْنُ أَبِي صَفِيَّةَ أَبُو حَمْزَةَ الثُّمَالِيُّ كُوفِيٌّ عَنْ زَاذَانَ وَعِكْرِمَةَ وَأَبِي جَعْفَرٍ .\n• قَالَ الذَّهَبِيُّ: مُتَّفَقٌ عَلَى ضَعْفِهِ- د- دَيْوَانَ ٣٨."],[162,"ثُوَيْرُ بْنُ أَبِي فَاخَتِهِ ضَعِيفٌ. مَوْلَى بَنِي هَاشِمٍ - وَأَسَمُ أَبِيهِ سَعِيدُ بْنُ عَلَاقَةَ كُوفِيّ ثِقَةٌ .\n• قَالَ الذَّهَبِيُّ: تَابِعِيٌّ وَاهْ كَذِبَهُ الثَّوْرِيُّ- ت- دِيوَانٌ ٤٠.\n• قَالَ ابْنُ حَجَرٍ: مَشْهُورٌ بِكُنْيَتِهِ ثِقَةٌ مِنَ الثَّالِثَةِ- ت ق- تَقْرِيبُ التَّهْذِيبِ. ١٢٥"],[163,"جَلْدُ بْنُ أَيُّوبَ كُوفِيٌّ عَنْ مُعَاوِيَةَ بْنِ فَرْوَةَ مَتْرُوكٌ .\n• دِيوَانٌ ٤٥."],[164,"جَابِرُ بْنُ زَيْدٍ الْجُعْفِيُّ أَنْ اُعْتُبِرَ لَهُ بِحَدِيثٍ بَعْدَ حَدِيثِ صَالِحٍ إِذَا كَانَ عَنْ الْأَئِمَّةِ .\n• قَالَ يَحْيَى بْنُ أَبِي بُكَيْرٍ عَنْ شُعْبَةَ: كَانَ جَابِرٌ إِذَا قَالَ أَخْبَرَنَا وَحَدَّثَنَا وَسَمِعْتُ فَهُوَ مِنْ أَوْثَقِ النَّاسِ، مِيزَانُ الاِعْتِدَالِ ٣/٣٧٩."],[165,"جَعْفَرُ بْنُ الزُّبَيْرِ الشَّامِيُّ عَنْ الْقَاسِمِ عَنْ أَبُو أُمَامَةَ مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: كَذَّبَهُ شُعْبَةُ وَتَرَكَهُ أَحْمَدُ، دِيوَانٌ ٤٤."],[166,"جَعْفَرُ بْنُ عَبْدِ الْوَاحِدِ الْهَاشِمِيُّ وَلَّى قَضَاءَ الثَّغْرِ يَضَعُ .\n• تَنْزِيهُ الشَّرِيعَةُ ١/٤٥."],[167,"جَعْفَرُ بْنُ أَبِي الْحَسَنِ الْخَوَارِيُّ يُحَدِّثُ عَنْهُ أَبُو غَنَّامٍ ..\n• مِيزَانُ الاِعْتِدَالِ ١/٤٠٥."],[168,"جِسْرُ بْنُ فَرْقَدٍ بَصْرِيٌّ عَنْ ثَابِتٍ وَالْحَسَنِ."],[169,"جُوَيْبِرُ بْنُ سَعِيدٍ خُرَاسَانِيٌّ مَتْرُوكٌ .\n• دِيوَانٌ ٤٧."],[170,"جَمِيعُ بْنُ ثَوْبٍ حِمْصِيٌّ عَنْ خَالِدِ بْنِ مَعْدَانَ مُقِلٌّ وَيُقَالُ جَمِيعُ مُنْكَرِ الْحَدِيثِ .\n• قَالَ الذَّهَبِيُّ: مُنْكَرُ الْحَدِيثِ وَاهٍ. دِيوَانٌ ٤٦."],[171,"جَارِيَةُ بْنُ هَرَمٍ الْفُقَيْمِيُّ أَبُو شَيْخٍ بَصْرِيٌّ مَتْرُوكٌ عَنْ يَعْقُوبَ بْنِ عَطَاءٍ وَإِسْمَاعِيلَ بْنِ مُسْلِمٍ وَابْنِ عَوْنٍ وَابْنِ جُرَيْجٍ رَوَى عَنْهُ مُحَمَّدُ بْنُ إِسْحَاقَ وَيُقْلِبُ اسْمَهُ لَا يُقَالُ فِيهِ .\n• قَالَ الذَّهَبِيُّ: بَصْرِي هَالِكٌ. مِيزَانُ الاِعْتِدَالِ ١/٣٨٥."],[172,"جِرَاحُ بْنُ مِنْهَالٍ أَبُو الْعَطَّافِ عَنِ الزُّهْرِيِّ وَأَبَى الزُّبَيْرُ وَالْحَكَمُ بْنُ عُتْبَةَ جَزَرِيٌّ رَوَى عَنْهُ يَزِيدُ بْنُ هَارُونَ وَالْمُعَافَا بْنُ عِمْرَانَ وَيَحْيَى بْنُ صَالِحٍ فِيهِ خَلَاعَةُ مَتْرُوكٍ .\n• مِيزَانُ الاِعْتِدَالِ ١/٣٩٠."],[173,"جَارُودُ بْنُ يَزِيدَ أَبُو الضَّحَّاكِ نَيْسَابُورِيٌّ مَتْرُوكٌ يُرْوَى عَنْ بَهْزِ بْنِ حَكِيمٍ وَعَمْرِو بْنِ ذَرٍّ .\n• دِيوَانٌ ٤١."],[174,"جَمِيلُ بْنُ زَيْدٍ الطَّائِيُّ كُوفِيٌّ عَنِ ابْنِ عُمَرَ رَوَى عَنْهُ الثَّوْرِيُّ وَعَبَّادُ بْنُ الْعَوَّامِ مُقِلُّ مَتْرُوكٍ. وَقَالَ مَرَّةً يُعْتَبَرُ بِهِ ."],[175,"الْحَارِثُ بْنُ عَبْدِ اللَّهِ الْأَعْوَرُ، كُوفِي هَمْدَانِيٌّ .\n• قَالَ ابْنُ حَجَرٍ: \"كَذَّبَهُ الشَّعْبِيُّ فِي رَأْيِهِ وَرُمِيَ بِالرَّفْضِ. وَفِي حَدِيثِ ضَعْفٍ\"- عَلِىٍّ- تَقْرِيبُ التَّهْذِيبِ ٦٠"],[176,"الْحَارِثُ بْنُ عِمْرَانَ، أَبُو سَهْلٍ الْجَعْفَرِيُّ، كُوفِي عَنْ مُحَمَّدِ بْنِ سُوقِهِ وَهِشَامِ ابْنِ عُرْوَةَ .\n• ضَعِيفٌ رَمَاهُ ابْنُ حِبَّانَ بِالْوَضْعِ مِنَ التَّاسِعَةِ –ق - تَقْرِيبُ التَّهْذِيبِ٦٠"],[177,"الْحَارِثُ بْنُ نَبْهَانَ الْجَرْمِيُّ، بَصْرِي عَنْ عَاصِمِ بْنِ بَهْدَلَةَ، وَأَيُّوبَ السِّخْتِيَانِيِّ، وَالْأَعْمَشُ، لَيْسَ بِالْقَوِيِّ .\n• مَتْرُوكٌ مِنَ الثَّامِنَةِ - ت ق - تَقْرِيبُ التَّهْذِيبِ ٦١."],[178,"الْحَارِثُ بْنُ شِبْلٍ الْبَصْرِيُّ، عَنْ أُمِّ النُّعْمَانِ، مُقِلٌّ، وَلَيْسَتْ بِمَعْرُوفَةٍ .\n• لِسَانُ الْمِيزَانِ ٢/ ١٥٢."],[179,"الْحَارِثُ بْنُ سُرَيْجٍ الْبَقَّالُ، بَغْدَادِيٌّ، عَنِ ابْنِ عُيَيْنَةَ، وَيَحْيَى الْقَطَّانِ، وَيَزِيدُ بْنُ زُرَيْعٍ، غَمَزَهُ يَحْيَى بْنُ مَعِينٍ، وَهُوَ كَمَا قَالَ .\n• لِسَانُ الْمِيزَانِ ٢/١٤٩."],[180,"الْحَارِثُ بْنُ حَصِيرِهِ، يَغْلُو فِي التَّشَيُّعِ .\n• مِيزَانُ الاِعْتِدَالِ ١/٤٣٢."],[181,"الْحَارِثُ بْنُ حَجَّاجِ بْنِ أَبِي الْحَجَّاجِ، مَجْهُولَانِ .\n• قَالَ ابْنُ حَجَرٍ: \"قَالَ الدَّارَقُطْنِيُّ مَجْهُولاَنِ لِسَانُ الْمِيزَانِ ٢/١٤٩."],[182,"حَكَمُ بْنُ ظُهَيْرٍ الْفَزَارِيُّ، عَنْ عَاصِمٍ، وَعَلْقَمَةَ بْنِ مَرْثَدٍ السُّدِّيِّ، يَرْوِي عَنْهُ مَرْوَانُ الْفَزَارِيُّ، يَقُولُ ابْنُ أَبِي خَالِدٍ."],[183,"حَكَمُ بْنُ عَبْدِ اللَّهِ بْنِ سَعْدٍ الْأَيْلِيُّ، قُرَشِيٌّ، عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ وَابْنِ أَبِي مُلَيْكَةَ وَالزُّهْرِيِّ وَابْنِ أَبِي عَلِيٍّ، مَتْرُوكٌ .\n• قَالَ الذَّهَبِيُّ: \"ضَعِّفُوهُ وَلَمْ يَتْرَكْ\" دِيوَانٌ ٧١."],[184,"حَكَمُ بْنُ عَبْدِ اللَّهِ، أَبُو مُطِيعٍ الْخُرَاسَانِيُّ، بَلْخِي، عَنْ إِبْرَاهِيمَ بْنِ طَهْمَانَ، وَأَبِي حَنِيفَةَ."],[185,"حَكِيمُ بْنُ جُبَيْرٍ، كُوفِيٌّ عَنْ سَعِيدِ بْنِ جُبَيْرٍ، وَالنَّخَعِيِّ وَالشَّعْبِيِّ"],[186,"حَمَّادُ بْنُ عَمْرٍو النَّصِيبِيُّ، أَبُو إِسْمَاعِيلَ عَنِ الْأَعْمَشِ، وَزَيْدُ بْنِ رَفِيعٍ .\n• انْظُرْ مِيزَانَ الاِعْتِدَالِ ١/٥٩٨."],[187,"حَمَّادُ بْنُ عِيسَى، غَرِيقُ الْجُحْفَةِ .\n• قَالَ ابْنُ حَجَرٍ: \"حَمَّادُ بْنُ عِيسَى بْنِ عُبَيْدٍ غَرِقَ بِالْجُحْفَةِ سَنَةَ ثَمَانٍ وَمِائَتَيْنِ\" تَقْرِيبُ التَّهْذِيبِ ٨٢"],[188,"حَمَّادٌ الْمَالِكِيُّ، قَدَرِيٌّ، عَنِ الْحَسَنِ، كَذَّابٌ."],[189,"حُمَيْدُ بْنُ عَطَاءٍ وَقِيلَ: ابْنُ عَامِرٍ الْمَكْتَبُ، عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ، مَتْرُوكٌ."],[190,"حَفْصُ بْنُ عُمَرَ الْفَرْخُ الْعَدَنِيُّ، عَنْ الْحَكَمِ بْنِ أَبَانَ .\n• قَالَ ابْنُ حَجَرٍ: \"حَفْصُ بْنُ عُمَرَ الْفَرْخُ بِالْفَاءِ وَسُكُونِ الرَّاءِ وَالْخَاءِ الْمُعْجَمَةِ\" تَقْرِيبُ التَّهْذِيبِ ٧٨"],[191,"حَفْصُ بْنُ عُمَرَ بْنِ أَبِي سُلَيْمَانَ أَبُو عِمْرَانَ الإِمَامُ النَّجَّارُ الْوَاسِطِيُّ."],[192,"حَفْصُ بْنُ سُلَيْمَانَ بْنِ الْمُغِيرَةِ أَبُو دَاوُدَ، هُوَ الْقَارِي وَهُوَ حَفْصُ بْنُ أَبِي دَاوُدَ سُلَيْمَانُ."],[193,"حَبِيبٌ، كَاتِبُ مَالِكَ، مَتْرُوكٌ."],[194,"حَبِيبٌ الِاسْكَافُ، أَبُو عَمِيرَةَ كُوفِيٌّ عَنْ أَنَسٍ .\n• قَالَ الذَّهَبِيُّ: \"قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ\" مِيزَانُ الاِعْتِدَالِ ١/٤٥٦"],[195,"حَبِيبُ بْنُ حِبَّانَ، هُوَ ابْنُ أَبِي الأَشْرَسِ، ضَعِيفٌ."],[196,"حَجَّاجُ بْنُ بَصِيرٍ، بَصْرِيٌّ، أَجْمَعُوا عَلَى تَرْكِهِ."],[197,"حَجَّاجُ بْنُ فَرُّوخَ، وَاسْطِي، عَنِ الْعَوَّامِ بْنِ حَوْشَبٍ، وَابْنُ جُرَيْجٍ مَتْرُوكٌ."],[198,"حِبَّانُ بْنُ عَلِيٍّ الْعَنَزِيُّ، عَنِ الأَعْمَشِ، وَلَيْثِ بْنِ أَبِي سُلَيْمٍ، ضَعِيفٌ وَأَخُوهُ مِنْدَلٌ ضَعِيفٌ أَيْضًا."],[199,"حَرَامُ بْنُ عُثْمَانَ مَدَنِيٌّ، عَنْ ابْنَيْ جَابِرٍ .\n• قَالَ الإِمَامُ أَحْمَدُ: \"تَرَكُ النَّاسَ حَدِيثَهُ\" مِيزَانُ الاِعْتِدَالِ ١/٤٦٨"],[200,"حَبُّهُ بْنُ جُوَيْنٍ الْعُرَنِيُّ، عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ .\n• قَالَ الذَّهَبِيُّ: \"قَالَ الدَّارَقُطْنِيُّ ضَعِيفٌ\". دِيوَانٌ ٤٩."],[201,"حُصَيْنُ بْنُ مُخَارِقٍ، مَتْرُوكٌ."],[202,"حُصَيْنُ بْنُ عُمَرَ أَبُو عُمَرَ الْأَحْمَسِيُّ، كُوفِي عَنْ مُخَارِقِ بْنِ عَبْدِ اللَّهِ، وَإِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ الثَّامِنَةِ -ت- تَقْرِيبُ التَّهْذِيبِ ٧٦."],[203,"حَمْزَةُ بْنُ أَبِي حَمْزَةَ النَّصِيبِيُّ، عَنْ أَبِي الزُّبَيْرِ، وَعَمْرِو بْنِ دِينَارٍ .\n• قَالَ الذَّهَبِيُّ: \"قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ\" مِيزَانُ الاِعْتِدَالِ ١/٦٠٦."],[204,"حُسَّامُ بْنُ مِصْكَ أَبُو سَهْلٍ، بَصْرِي، عَنْ قَتَادَةَ وَعَبْدِ اللَّهِ بْنِ بُرَيْدَةَ.\n• قَالَ الذَّهَبِيُّ: \"قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ\" مِيزَانُ الاِعْتِدَالِ ١/٤٧٧."],[205,"حُدَيْجُ بْنُ مُعَاوِيَةَ الْكُوفِيُّ، يَغْلِبُ عَلَيْهِ الْوَهْمُ، عَنْ أَبِي إِسْحَاقَ."],[206,"حَسَّانُ بْنُ سِيَاهٍ، كُوفِيٌّ، عَنْ ثَابِتٍ وَعَاصِمِ بْنِ أَبِي النَّجُودِ. آخِرُ مَا وُجِدَ فِي كِتَابِ الْبَرْقَانِيِّ."],[207,"حَسَنُ بْنُ دِينَارٍ وَقِيلَ ابْنُ وَاصِلٍ وَقِيلَ ابْنُ دِينَارٍ زَوْجُ أُمِّهِ عَنْ الْحَسَنِ وَابْنِ سِيرِينَ وَأَيُّوبَ .\n• قَالَ ابْنُ حَجَرٍ: \"تَرَكَهُ وَكِيعٌ وَابْنُ حَنْبَلٍ\". لِسَانُ الْمِيزَانِ ٢/٢٠٣."],[208,"حَسَنُ بْنُ عُمَارَةَ كُوفِيٌّ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ الثَّامِنَةِ -ت ق- تَقْرِيبُ التَّهْذِيبِ ٧١."],[209,"حَسَنُ بْنُ زِيَادٍ اللُّؤْلُؤِيُّ .\n• قَالَ الذَّهَبِيُّ: \"كَذَّبَهُ ابْنُ مَعِينٍ\". دِيوَانُ ٥٧."],[210,"حَسَنُ بْنُ عَلِيٍّ الْهَاشِمِيُّ، عَنِ الْأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ مِنَ الثَّامِنَةِ -ت ق- تَقْرِيبُ التَّهْذِيبِ ٧١."],[211,"حَسَنُ بْنُ أَبِي جَعْفَرٍ، وَفِي نُسْخَةٍ حَسَنِ بْنِ أَبِي جَعْفَرٍ الْجَفْرِيِّ، بَصْرِيٌّ، يَرْوِي عَنْ أَيُّوبَ، وَمُحَمَّدِ بْنِ جُحَادَةَ، وَأَبِي الزُّبَيْرِ .\n• مِيزَانُ الاِعْتِدَالِ١/٤٨٢."],[212,"حَسَنُ بْنُ يَحْيَى الْخُشَنِيُّ شَامِيٌّ، عَنْ هِشَامِ بْنِ عُرْوَةَ، مَتْرُوكٌ."],[213,"حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ ضُمَيْرَةَ، عَنْ أَبِيهِ عَنْ جَدِّهِ مَدَنِيٍّ .\n• قَالَ الْبُخَارِيُّ: \"مُنْكَرُ الْحَدِيثِ\". التَّارِيخُ الْكَبِيرُ ٢/١/٢٨٨."],[214,"حُسَيْنُ بْنُ عُلْوَانَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، وَالأَعْمَشُ، كَذَّابٌ."],[215,"حَلْبَسُ بْنُ مُحَمَّدٍ الْمِصْرِيُّ، الْكَلْبِيُّ، عَنْ الثَّوْرِيِّ .\n• قَالَ الذَّهَبِيُّ: \"قَالَ الدَّارَقُطْنِيُّ مَتْرُوكُ الْحَدِيثِ\". مِيزَانُ الاِعْتِدَالِ ١/٥٨٧."],[216,"حُسَيْنُ بْنُ قَيْسٍ الرَّحَبِيُّ، وَيُقَالُ حَنَشَ، عَنْ عِكْرِمَةَ، وَعَنْ عَطَاءٍ، وَاسِطِي .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ مَتْرُوكٌ. مِيزَانُ الاِعْتِدَالِ ١/٥٤٦."],[217,"حُسَيْنُ بْنُ خَالِدٍ الأَشْقَرُ، كُوفِيٌّ، عَنْ شَرِيكٍ، وَقَيسٌ، وَجَعْفَرٍ الأَحْمَرُ، وَهُرَيْمُ ابْنِ سُفْيَانَ. لَيْسَ بِالْقَوِيِّ."],[218,"خَالِدُ بْنُ الْقَاسِمِ أَبُو الْهَيْثَمِ مَدَائِنِيٌّ مِنْ الْحُفَّاظِ، عَنْ كَعْبِ بْنِ سَعِيدٍ وَهُشَيْمٍ .\n• قَالَ يَعْقُوبُ بْنُ شَيْبَةَ: \"خَالِدٌ الْمَدَائِنِيُّ صَاحِبُ حَدِيثٍ مُتَّقِنٍ، مَتْرُوكُ الْحَدِيثِ\"، مِيزَانُ الاِعْتِدَالِ ١/٢٣٨."],[219,"خَالِدُ بْنُ إِلْيَاسَ مَدَنِيٌّ، عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، وَهِشَامِ بْنِ عُرْوَةَ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكُ الْحَدِيثِ مِنَ السَّابِعَةِ -ت ق- تَقْرِيبُ التَّهْذِيبِ ٨٧."],[220,"خَالِدٌ الْعَبْدِيُّ بَصْرِيٌّ، أَكْثَرُ رِوَايَتِهِ عَنِ الْحَسَنِ، مَتْرُوكٌ."],[221,"خَالِدُ بْنُ يَزِيدَ بْنِ أَبِي مَالِكٍ، شَامِيٌّ، عَنْ أَبِيهِ، وَأَبُوهُ مِنَ الثِّقَاتِ."],[222,"خَالِدُ بْنُ مَحْدُوجٍ، أَبُو رَوْحٍ وَاسْطِي، عَنْ أَنَسٍ .\n• قَالَ الذَّهَبِيُّ: دِيوَانٌ ٨٣. مِيزَانُ الاِعْتِدَالِ ١/٦٤٢."],[223,"خَالِدُ بْنُ عَمْرٍو الْأُمَوِيُّ، كُوفِي، عَنْ الثَّوْرِيِّ وَالنَّاسِ مِنْ وَلَدِ سَعِيدٍ ابْنِ الْعَاصِ .\n• رَمَاهُ ابْنُ مَعِينٍ بِالْكَذِبِ مِنَ التَّاسِعَةِ -دَقَّ- تَقْرِيبَ التَّهْذِيبِ ٨٩."],[224,"خَالِدُ بْنُ طَلِيقِ بْنِ مُحَمَّدِ بْنِ عِمْرَانَ بْنِ حُصَيْنٍ، بَصْرِيٌّ عَنْ أَبِيهِ عَنْ جَدِّهِ."],[225,"خُلَيْدُ بْنُ دَعْلَجٍ، شَامِيٌّ، عَنْ قَتَادَةَ وَالْحُسَيْنِ .\n• قَالَ النَّسَائِيُّ: \"لَيْسَ بِثِقَةٍ\". الضُّعَفَاءُ وَالْمَتْرُوكُونَ ٣٧."],[226,"خَارِجَةُ بْنُ مُصْعَبٍ سَرَخْسِيٌّ عَنْ الْعَالِمِ .\n• قَالَ النَّسَائِيُّ: \"مَتْرُوكُ الْحَدِيثِ\". الضُّعَفَاءُ وَالْمَتْرُوكُونَ ٣٧."],[227,"خُصَيْبُ بْنُ جَحْدَرٍ، بَصْرِي عَنْ أَبِي صَالِحٍ، وَعَمْرِو بْنِ دِينَارٍ، وَالنُّعْمَانِ ابْنِ نُعَيْمٍ، لاَ يُعْرَفُ إِلاَّ بَرُوَاتُهُ."],[228,"خَصِيبٌ عَنْهُ خَالِدُ بْنُ إِسْمَاعِيلَ، أَبُو الْوَلِيدِ الْمَخْزُومِيُّ مَدَنِيٌّ."],[229,"خَارِجَةُ بْنُ عَبْدِ اللَّهِ بْنِ سُلَيْمَانَ بْنِ زَيْدِ بْنِ ثَابِتٍ، مَدَنِيٌّ ضَعِيفٌ."],[230,"دَاوُدُ بْنُ الْمُحَبَّرِ، يَضَعُ بَصْرِيٌّ كَانَ بِبَغْدَادَ، مَتْرُوكٌ."],[231,"دَاوُدُ بْنُ عَبْدِ الْجَبَّارِ أَبُو سُلَيْمَانَ، كُوفِيٌّ، عَنْ إِبْرَاهِيمَ بْنِ جَرِيرٍ، وَسَلَمَةُ ابْنِ الْمَجْنُونِ .\n• قَالَ الذَّهَبِيُّ: \"تَرُكُوهُ\" دِيوَانٌ ٩٢."],[232,"دُجَيْنُ بْنُ ثَابِتٍ أَبُو الْغُصْنِ بَصْرِيٌّ عَنْ أَسْلَمَ مَوْلَى عُمَرَ، وَعَنْ هِشَامِ بْنِ عُرْوَةَ .\n• قَالَ الذَّهَبِيُّ: بَصْرِي لاَ يُحْتَجُّ بِهِ. دِيوَانُ ٩٥."],[233,"دِينَارٌ أَبُو سَعِيدٍ عَقِيصًا، كُوفِي عَنْ عَلِيٍّ مَنَاكِيرَ، رَمَاهُ أَبُو بَكْرِ بْنُ عَيَّاشٍ بِالْكَذِبِ."],[234,"دَهْثَمُ بْنُ قِرَانٍ قَدِمَ الْمَدِينَةَ عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، وَنَحْرَانَ لَا يُعْرَفُ إِلَّا بِهِ مَجْهُولٌ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ الثَّامِنَةِ -ق- تَقْرِيبُ التَّهْذِيبِ ٩٨."],[235,"دَرَسْتُ بْنَ زِيَادٍ الْقُشَيْرِيَّ، بَصْرِي عَنْ يَزِيدَ الرَّقَاشِيِّ، وَأَبَانَ بْنِ طَارِقٍ، لَا يُرْوَى عَنْهُ غَيْرُهُ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ مِنَ الثَّامِنَةِ- دَقَّ- تَقْرِيبُ التَّهْذِيبِ ٩٧."],[236,"دَرَسْتُ بْنَ حَمْزَةَ بَصْرِيٌّ، عَنْ مَطَرٍ الْوَرَّاقِ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانُ ٩٥."],[237,"ذُؤَيْبُ بْنُ عُمَامَةَ بْنِ عَمْرٍو السَّهْمِيُّ، عَنْ مَالِكٍ، وَالْمَدَنِيِّينَ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانُ ٩٨."],[238,"رَبِيعُ بْنُ بَدْرٍ، وَيُقَالُ عُلَيْلَةُ بْنُ بَدْرٍ، بَصْرِيٌّ عَنِ الأَعْمَشِ، وَيُونُسَ بْنِ عُبَيْدٍ، مُنْكَرُ الْحَدِيثِ، عَنْ مَالِكٍ وَالْمَدَنِيِّينَ .\n• قَالَ الذَّهَبِيُّ: تَرَكَهُ الدَّارَقُطْنِيُّ وَغَيْرُهُ. دِيوَانٌ ١٠٠."],[239,"رَبِيعُ بْنُ حَبِيبٍ، أَخُو عَابِدٍ كُوفِيٌّ عَنْ نَوْفَلِ بْنِ عَبْدِ الْمَلِكِ عَنْ أَبِيهِ عَنْ عَلِيٍّ"],[240,"فَأَمَّا الرَّبِيعُ بْنُ حَبِيبٍ الرَّقَاشِيُّ، فَهُوَ بَصْرِيٌّ مُقِلٌّ يَرْوِي عَنْ الْمِصْرِيِّينَ لَا يُتْرَكُ .\n• وَثَّقَهُ الإِمَامُ أَحْمَدُ وَابْنُ مَعِينٍ، مِيزَانُ الاِعْتِدَالِ ٢/ ٤٠."],[241,"رَبِيعُ بْنُ سَهْلِ بْنِ الدُّكَيْنِ، كُوفِيٌّ عَنْ سَعِيدِ بْنِ عُبَيْدٍ، وَعَبْدِ اللَّهِ بْنِ شَرِيكٍ الْعَامِرِيِّ."],[242,"رِشْدِينُ بْنُ سَعْدٍ أَبُو الْحَجَّاجِ، بَصْرِيٌّ، ضَعِيفٌ."],[243,"رِشْدِينُ بْنُ كُرَيْبٍ مَدَنِيٌّ .\n• مِيزَانُ الاِعْتِدَالِ ٢/٥١."],[244,"رَشِيدٌ الْهَجَرِيُّ، عَنْ أَبِيهِ عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو .\n• مِيزَانُ الاِعْتِدَالِ ٢/٥١."],[245,"رَوْحُ بْنُ أَسْلَمَ، أَبُو حَاتِمٍ بَصْرِيٌّ عَنْ حَمَّادِ بْنِ سَلَمَةَ."],[246,"رَوْحُ بْنُ عَطَاءِ بْنِ أَبِي مَيْمُونَةَ عَنْ أَبِيهِ."],[247,"رَوْحُ بْنُ مُسَافِرٍ، كُوفِي عَنْ أَبِي إِسْحَاقَ، وَحَبِيبِ بْنِ أَبِي ثَابِتٍ، كَنَّاهُ لُؤَيٌّ أَبُو الْمُعَطَا."],[248,"رَوْحُ بْنُ غُطَيْفٍ جَزَرِيٌّ، عَنِ الزُّهْرِيِّ، وَعَمْرِو بْنِ مُصْعَبٍ الْكُوفِيِّ."],[249,"رَبَاحُ بْنُ عُبَيْدِ اللَّهِ بْنِ عُمَرَ الْقُرَشِيُّ، قَالَ بَعْضُهُمْ: أَبُو بَكْرٍ مَدَنِيٌّ."],[250,"رَكْنُ بْنُ عَبْدِ اللَّهِ الشَّامِيُّ، عَنْ مَكْحُولٍ، مُقِلٌّ."],[251,"رَوَّادُ بْنُ الْجَرَّاحِ أَبُو عِصَامٍ عَسْقَلانِيٌّ، عَنِ الثَّوْرِيِّ، وَسَعِيدٍ."],[252,"زَيْدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ أَسْلَمَ، عَنْ أَبِيهِ مُنْكَرُ الْحَدِيثِ."],[253,"زَيْدُ بْنُ الْحَسَنِ بَصْرِيٌّ، يُحَدِّثُ عَنْ مَالِكِ بْنِ أَنَسٍ بِمَنَاكِيرَ."],[254,"زَيْدُ بْنُ جُبَيْرِهِ بْنِ مَحْمُودِ بْنِ أَبِي جُبَيْرِهِ الْأَنْصَارِيُّ، عَنْ أَبِيهِ لَا يُعْرَفُ أَبُوهُ إِلَّا بِهِ، وَعَنْ دَاوُدَ بْنِ الْحُصَيْنِ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ الثَّامِنَةِ -ت ق- تَقْرِيبُ التَّهْذِيبِ ١١٢."],[255,"فَهْدُ بْنُ عَوْفٍ أَبُو رَبِيعَةَ وَيُقَالُ زَيْدٌ، بَصْرِي عَنْ حَمَّادِ بْنِ سَلَمَةَ .\n• قَالَ الذَّهَبِيُّ: زَيْدُ بْنُ عَوْفٍ وَلَقَبُهُ فَهْدٌ. قَالَ الدَّارَقُطْنِيُّ: ضَعِيفٌ. مِيزَانُ الاِعْتِدَالِ ٢/١٠٥."],[256,"زِيَادُ بْنُ الْمُنْذِرِ أَبُو الْجَارُودِ، كُوفِيٌّ عَنْ أَبِي الطُّفَيْلِ، وَأَبِي جَعْفَرٍ مُحَمَّدِ ابْنِ عَلِيٍّ .\n• قَالَ الإِمَامُ أَحْمَدُ: مَتْرُوكٌ. دِيوَانٌ ١١٢."],[257,"زِيَادُ بْنُ أَبِي حَسَّانَ، أَبُو عَمَّارٍ بَصْرِيٌّ عَنْ أَنَسٍ، وَعَنْ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ .\n• قَالَ الذَّهَبِيُّ: تَرَكَهُ الْجَمَاعَةُ. دِيوَانٌ ١١١."],[258,"زِيَادُ بْنُ مَيْمُونٍ أَبُو عَمَّارٍ عَنْ أَنَسٍ .\n• قَالَ الذَّهَبِيُّ: يُقَالُ لَهُ زِيَادُ بْنُ أَبِي حَسَّانَ وَزِيَادُ بْنُ أَبِي عَمَّارٍ هَالِكٌ اعْتَرَفَ بِالْكَذِبِ. دِيوَانٌ ١١٢."],[259,"زِيَادُ بْنُ أَبِي زِيَادٍ الْجَصَّاصُ عَنِ الْحَسَنِ، وَابْنِ سِيرِينَ، وَأَبِي عُثْمَانَ النَّهْدِيِّ .\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ ١١٢."],[260,"زِيَادُ بْنُ الْمُنْذِرِ، وَإِنَّمَا هُوَ مُنْذِرُ بْنُ زِيَادٍ الطَّائِيُّ، بَصْرِي عَنْ زَيْدِ بْنِ أَسْلَمَ عَنْ أَبِيهِ عَنْ عُمَرَ حَدِيثٌ مُنْكَرٌ، وَلَهُ أَيْضًا مَنَاكِيرُ .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ: مُنْذِرُ بْنُ زِيَادٍ الطَّائِيُّ، مَتْرُوكٌ وَوَهَمَ فِيهِ مِنْ قَلْبِهِ، فَقَالَ: زِيَادُ بْنُ الْمُنْذِرِ. مِيزَانُ الاِعْتِدَالِ ٤/١٨١."],[261,"زَكَرِيَّا بْنُ حَكِيمٍ الْحَبَطِيُّ، كُوفِيٌّ عَنِ الشَّعْبِيِّ."],[262,"زَكَرِيَّا بْنُ يَحْيَى الْكِسَائِيُّ، الْكُوفِيُّ عَنْ يَحْيَى بْنِ سَالِمٍ الأَسَدِيِّ، مَتْرُوكَ أَيْضًا."],[263,"زَنْفَلٌ أَبُو عَبْدِ اللَّهِ الْعُرَنِيُّ عَنِ ابْنِ أَبِي مُلَيْكَةَ."],[264,"زُبَيْرُ بْنُ سَعِيدٍ الْهَاشِمِيُّ النَّوْفَلِيُّ، مَدَنِيٌّ حَمَلَ عَنْهُ ابْنُ الْمُبَارَكِ، وَجَرِيرُ بْنُ حَازِمٍ. يُعْتَبَرُ بِهِ بِمَا رَوَاهُ عَنْ عَبْدِ اللَّهِ بْنِ عَلِيِّ بْنِ زَيْدِ بْنِ رُكَّانِهِ؛ فَأَمَّا مَا يَرْوِيهِ عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ فَإِنَّهُ يُتْرَكُ .\n• قَالَ ابْنُ حَجَرٍ: لَيْنَ الْحَدِيثِ مِنَ السَّابِعَةِ – د ت ق - تَقْرِيبُ التَّهْذِيبِ ١٥٦."],[265,"سَلَمَةُ بْنُ صَالِحٍ الْأَحْمَرُ، كُوفِيٌّ سَكَنَ وَاسِطٌ وَبَغْدَادُ عَنْ أَبِي إِسْحَاقَ وَحَمَّادِ بْنِ أَبِي سُلَيْمَانَ، وَمَالِكِ بْنِ أَوْسٍ الْحَدَثَانِيِّ .\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ. دِيوَانٌ ١٢٨."],[266,"سَلَمَةُ بْنُ وَرْدَانَ، مَدِينِي عَنْ أَنَسٍ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ مِنْ الْخَامِسَةِ -بخ ت ق- تَقْرِيبَ التَّهْذِيبِ ١٣١، دِيوَانٌ ١١٦."],[267,"سُلَيْمَانُ بْنُ عَبْدِ اللَّهِ بْنِ سُلَيْمَانَ، أَبُو بَكْرٍ الْهُذَلِيُّ، بَصْرِيٌّ عَنِ الْحَسَنِ، وَابْنِ سِيرِينَ"],[268,"سُرِيُّ بْنُ إِسْمَاعِيلَ الْكُوفِيُّ، عَنِ الشَّعْبِيِّ، ضَعَّفَهُ يَحْيَى الْقَطَّانُ وَغَيْرُهُ."],[269,"سَرِيُّ بْنُ عَاصِمٍ بَغْدَادِيٌّ، عَنْ أَيُّوبَ، وَحَفْصِ بْنِ غِيَاثٍ، وَغُنْدَرٍ وَالنَّاسِ .\n• قَالَ الذَّهَبِيُّ: مُتَّهَمٌ. دِيوَانٌ ١١٦."],[270,"سُلَيْمَانُ بْنُ أَرْقَمَ أَبُو مُعَاذٍ، عَنِ الزُّهْرِيِّ، وَابْنِ سِيرِينَ، وَقِيلَ أَنَّ دَاوُدَ عَنِ الزُّهْرِيِّ حَدِيثُ الصَّدَقَاتِ أَنَّهُ هُوَ."],[271,"سُلَيْمَانُ بْنُ الْحَكَمِ بْنِ عَوَانَةَ، وَاسِطِي، عَنِ الأَعْمَشِ."],[272,"سُلَيْمَانُ بْنُ خَالِدٍ وَاسْطِي، عَنْ قَتَادَةَ، وَطَلْحَةَ بْنِ مُصَرِّفٍ، هُوَ أَخُو الْعَلاَءِ ابْنُ خَالِدٍ وَالْعَلاَءُ يُعْتَبَرُ بِهِ."],[273,"سُلَيْمَانُ بْنُ دَاوُدَ الْخَوْلانِيُّ عَنِ الزُّهْرِيِّ."],[274,"سُلَيْمَانُ بْنُ دَاوُدَ أَبُو أَيُّوبَ الشَّاذَكُونِيُّ، بَصْرِي."],[275,"سُلَيْمَانُ بْنُ زَيْدٍ أَبُو ادَامَ. عَنْ ابْنِ أَبِي أَوْفَى .\n• قَالَ ابْنُ مَعِينٍ: لَيْسَ بِثِقَةٍ. التَّارِيخُ ٢/ ٢٣١."],[276,"سُلَيْمَانُ بْنُ سُفْيَانَ مَدِينِي، أَبُو سُفْيَانَ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، وَبِلَالِ بْنِ يَحْيَى، سَمِعَ مِنْهُ أَبُو عَامِرٍ الْعَقَدِيُّ، وَمَعْمَرُ بْنُ سُلَيْمَانَ .\n• قَالَ ابْنُ مَعِينٍ: لَيْسَ بِثِقَةٍ. التَّارِيخُ ٢/٢٣١."],[277,"سُلَيْمَانُ بْنُ سُفْيَانَ الْجُهَنِيُّ مَدَايِنِي، عَنْ قَيْسِ بْنِ الرَّبِيعِ عَنْ وَرْقَاءَ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفُوهُ. دِيوَانٌ ١٣١."],[278,"سُلَيْمَانُ بْنُ عَمْرٍو النَّخَعِيُّ، أَبُو دَاوُد كُوفِيٌّ .\n• قَالَ الذَّهَبِيُّ: كَذَّابٌ. دِيوَانٌ ١٣٢."],[279,"سُلَيْمَانُ بْنُ يُسَيْرٍ، أَبُو الصَّبَّاحِ كُوفِيٌّ، عَنِ النَّخَعِيِّ، وَالْحَكَمِ، وَقَيْسُ بْنِ رُومِىٍّ، وَقَالَ سُلَيْمَانُ بْنُ بَشِيرٍ .\n• مِيزَانُ الاِعْتِدَالِ ٢/٢٢٨."],[280,"سُلَيْمَانُ بْنُ أَبِي سُلَيْمَانَ الْقَافِلانِيُّ، أَبُو مُحَمَّدٍ بَصْرِيٌّ، عَنِ الْحَسَنِ، وَابْنِ سِيرِينَ، رَوَى عَنْهُ عُبَيْدُ اللَّهِ بْنُ مُوسَى، فَقَالَ: سُلَيْمَانُ الْخُوْزِيُّ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكُ الْحَدِيثِ بَصْرِيٌّ مُقِلٌّ. مِيزَانُ الاِعْتِدَالِ ٢/ ٢١٠."],[281,"سَالِمُ بْنُ عَبْدِ الْأَعْلَى أَبُو الْفَيْضِ، كُوفِيٌّ عَنْ نَافِعٍ وَغَيْرِهِ .\n• مِيزَانُ الاِعْتِدَالِ ٢/١١٢."],[282,"سَالِمٌ الْخَيَّاطُ، عَنِ الْحَسَنِ، وَابْنِ سِيرِينَ\n• هُوَ سَالِمُ بْنُ عَبْدِ اللَّهِ الْخَيَّاطُ، قَالَ ابْنُ حَجَرٍ: صَدُوقُ سَيْءِ الْحِفْظِ مِنَ السَّادِسَةِ، تَقْرِيبُ التَّهْذِيبِ ١١٥."],[283,"سُلَيْمَانُ بْنُ أَبِي سِرَاجٍ .\n• الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٣١."],[284,"سَلَمُ بْنُ سَالِمٍ الْبَلْخِيُّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ، وَابْنِ جُرَيْجٍ، وَالثَّوْرِيِّ .\n• دِيوَانٌ ١٢٧."],[285,"سُلَيْمَانُ بْنُ مُسْلِمٍ الْخَشَّابُ، مَكِّيٌّ، عَنِ ابْنِ جُرَيْجٍ، وَالْمَكِّيِّينَ .\n• مِيزَانُ الاِعْتِدَالِ ٢/٢٢٣."],[286,"سَلاَّمُ بْنُ أَبِي خَبْزَةَ بَصْرِيٌّ، عَنِ الْعَالِمِ."],[287,"سَلاَّمُ بْنُ سُلَيْمَانَ وَقِيلَ: ابْنُ سَلْمَانَ، وَقِيلَ: ابْنُ سَالِمٍ الطَّوِيلُ الْمَدَايِنِيُّ، مَتْرُوكٌ عَنْ زَيْدٍ الْعَمِّيِّ."],[288,"سَعْدُ بْنُ طَرِيفٍ الِاسْكَافُ، كُوفِيٌّ عَنْ عِكْرِمَةَ، وَالْأَصْبَغُ .\n• مِيزَانُ الاِعْتِدَالِ ٢/ ١٢٢."],[289,"سَعْدُ بْنُ سِنَانٍ، وَقِيلَ: سِنَانُ بْنُ سَعْدٍ، عَنْ أَنَسٍ، رَوَى عَنْهُ يَزِيدُ بْنُ أَبِي حَبِيبٍ .\n• قَالَ ابْنُ حَجَرٍ: صَدُوقٌ لَهُ أَفْرَادٌ مِنَ الْخَامِسَةِ -د ت ق- تَقْرِيبَ التَّهْذِيبِ ١١٨."],[290,"سَعْدُ بْنُ سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيُّ، أَخُو عَبْدِ اللَّهِ .\n• قَالَ ابْنُ حَجَرٍ: لَيْنَ الْحَدِيثِ مِنَ الثَّامِنَةِ -ق- تَقْرِيبُ التَّهْذِيبِ ١١٨."],[291,"سَعِيدُ بْنُ سَلامٍ الْعَطَّارُ، أَبُو الْحَسَنِ بَصْرِيٌّ نَزَلَ مَكَّةَ، عَنِ الثَّوْرِيِّ، وَالْعَالِمِ .\n• قَالَ الذَّهَبِيُّ: قَالَ الإِمَامُ أَحْمَدُ: كَذَّابٌ، وَتَرَكَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٢١."],[292,"سَعِيدُ بْنُ سِنَانٍ أَبُو مَهْدِيٍّ، حِمْصِيٌّ، عَنْ أَبِي الزَّاهِرِيَّةِ .\n• قَالَ الذَّهَبِيُّ: هَالِكٌ -ق- دِيوَانٌ ١٢١."],[293,"سَعِيدُ بْنُ زَوْنٍ بَصْرِيٌّ، عَنْ أَنَسٍ .\n• سَعِيدُ بْنُ زَونٍ بِضَمِّ الزَّايِ وَسُكُونِ الْوَاوِ وَبَعْدَهَا نُونٌ -ضَعِيفٌ عِنْدَهُمْ- دِيوَانٌ ١٢٥."],[294,"سَعِيدُ بْنُ زَرْبِىٍّ أَبُو مُعَاوِيَةَ بَصْرِيٌّ، عَنِ ابْنِ سِيرِينَ، وَأَبِي الْمَلِيحِ مَتْرُوكٌ"],[295,"سَعِيدُ بْنُ عَبْدِ الْجَبَّارِ الْحِمْصِيُّ، الْعَطَّارُ، عَنْ أَبِي بَكْرِ بْنِ أَبِي مَرْيَمَ، وَالْحِمَصِيِّينَ .\n• قَالَ النَّسَائِيُّ: لَيْسَ بِثِقَةٍ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٥٢."],[296,"سَعِيدُ بْنُ وَاصِلٍ أَبُو عَمْرٍو الْحَرَشِيُّ، وَيُقَالُ أَبُو عُمَرَ بَصْرِيٌّ عَنْ شُعْبَةَ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٥٤."],[297,"سَعِيدُ بْنُ رَاشِدٍ أَبُو مُحَمَّدٍ السِّمَاكُ الْمَازِنِيُّ بَصْرِيٌّ عَنْ عَطَاءٍ، وَالزُّهْرِيِّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكٌ بَصْرِيٌّ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٥٤."],[298,"سُهَيْلُ بْنُ ذَكْوَانَ وَاسِطِي، عَنْ عَائِشَةَ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكٌ. دِيوَانٌ ١٣٧."],[299,"سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ الْعَطَّارُ، بَصْرِيٌّ .\n• قَالَ ابْنُ حَجَرٍ: صَدُوقٌ يَرْوِي عَنِ الضُّعَفَاءِ. تَقْرِيبُ التَّهْذِيبِ."],[300,"سَوَّارُ بْنُ مُصْعَبٍ .\n• قَالَ أَحْمَدُ وَالدَّارَقُطْنِيُّ: مَتْرُوكٌ. دِيوَانٌ ١٣٨."],[301,"سُوَيْدٌ، أَبُو حَاتِمٍ بَصْرِيٌّ، عَنْ قَتَادَةَ .\n• هُوَ سُوَيْدُ بْنُ إِبْرَاهِيمَ. مِيزَانُ الاِعْتِدَالِ ٢/٢٤٧."],[302,"سُدِيرُ بْنُ حَكِيمٍ الصَّيْرَفِيُّ، كُوفِيَ لَهُ مَقَاطِيعُ."],[303,"سَيْفُ بْنُ مُحَمَّدِ بْنِ أُخْتِ الثَّوْرِيِّ، كُوفِيٌّ عَنِ الْأَعْمَشِ، وَحُصَيْنٌ، وَالثَّوْرِيِّ .\n• قَالَ ابْنُ حَجَرٍ: كَذَّبُوهُ مِنْ صِغَارِ الثَّامِنَةِ -ت- تَقْرِيبُ التَّهْذِيبِ ١٤٢."],[304,"سَيْفُ بْنُ هَارُونَ الْبَرْجُمِيُّ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، كُوفِيٍّ أَخُو سِنَانٍ، وَسِنَانٌ يُعْتَبَرُ بِهِ .\n• قَالَ ابْنُ حِحْرٍ: ضَعِيفٌ أَفْحَشُ ابْنُ حِبَّانَ الْقَوْلُ فِيهِ مِنْ صِغَارِ الثَّامِنَةِ، تَقْرِيبُ التَّهْذِيبِ ١٤٢."],[305,"سَيْفُ بْنُ عُمَرَ الْأُسَيْدِيُّ، كُوفِي عَنِ الْعَالِمِ، الْكُوفِيِّينَ وَالْبَصْرِيِّينَ وَالْحِجَازِيِّينَ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ فِي الْحَدِيثِ. عُمْدَةٌ فِي التَّارِيخِ، تَقْرِيبُ التَّهْذِيبِ ١٤٢."],[306,"سَيْفُ بْنُ أَبِي الْمُغِيرَةِ كُوفِيٌّ، عَنْ مُجَالِدٍ وَغَيْرِهِ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٤٠."],[307,"شَبِيبُ بْنُ سُلَيْمٍ بَصْرِيٌّ، لَهُ مَقَاطِعُ."],[308,"شَبِيبُ بْنُ شَيْبَةَ أَبُو مَعْمَرٍ الْخَطِيبُ، بَصْرِيٌّ، عَنِ الْبَصْرِيِّينَ وَهِشَامُ ابْنِ عُرْوَةَ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفُوهُ. دِيوَانٌ ١٤٢."],[309,"صَالِحُ بْنُ بَشِيرٍ الْمُرِّيُّ، رَجُلٌ صَالِحٌ قَلَّ مَا يُوَافِقُ فِيمَا يَرْوِيهِ عَنِ الْحَسَنِ وَالْجُرَيْرِيِّ."],[310,"صَالِحُ بْنُ حَسَّانَ مَدَنِيٌّ، عَنْ مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ، وَعُرْوَةَ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ أَبُو حَاتِمٍ وَالنَّاسُ. دِيوَانٌ ١٤٧."],[311,"صَالِحُ بْنُ حِبَّانَ، كُوفِيٌّ عَنِ ابْنِ بُرَيْدَةَ رَوَى عَنْهُ زُهَيْرٌ وَسَمَّاهُ وَاصِلٌ وَهُمْ فِي اسْمِهِ لَيْسَ بِالْقَوِيِّ."],[312,"صَالِحُ بْنُ مُحَمَّدِ بْنِ زَايِدَةَ أَبُو قُدَامَةَ اللَّيْثِيُّ، مَدَنِيٌّ ضَعِيفٌ."],[313,"صَالِحُ بْنُ مُوسَى بْنِ عَبْدِ اللَّهِ الطَّلْحِيُّ، كُوفِيٌّ عَنْ مَنْصُورٍ، وَعَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ، وَهِشَامٍ، وَعَبْدِ اللَّهِ بْنِ الْحَسَنِ بْنِ الْحَسَنِ أَبُوهُ ثِقَةٌ، رَوَى عَنْهُ أَبُو أُسَامَةَ، وَعِيسَى ابْنُ دَاوُدَ."],[314,"صَالِحُ بْنُ أَحْمَدَ بْنِ مُقَاتِلٍ الْقِيرَاطِيُّ، حَدَّثُونَا عَنْهُ."],[315,"صِلَةُ بْنُ سُلَيْمَانَ وَاسْطِي، يَتْرُكُ حَدِيثَهُ عَنِ ابْنِ جُرَيْجٍ، وَشُعْبَةَ، وَيُعْتَبَرُ بِحَدِيثِهِ عَنْ أَشْعَثَ بْنِ عَبْدِ الْمَلِكِ الْحُمْرَانِيِّ."],[316,"صَالِحُ بْنُ سَهْلٍ أَبُو سَهْلٍ، كُوفِيٌّ سَكَنَ الْبَصْرَةَ عَنْ حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ، وَمُحَمَّدِ بْنِ عَمْرٍو."],[317,"صَلَّتُ بْنُ دِينَارٍ. أَبُو شُعَيْبٍ الْمَجْنُونُ بَصْرِيٌّ مَتْرُوكٌ."],[318,"صَفَذِيُّ بْنُ سِنَانٍ، بَصْرِي اسْمُهُ عُمَرُ عَنْ يُونُسَ، وَخَالِدٍ .\n• مِيزَانُ الاِعْتِدَالِ ٢/ ٣١٦."],[319,"صَدَقَةُ بْنُ عَبْدِ اللَّهِ السَّمِينُ أَبُو مُعَاوِيَةَ شَامِيٌّ ضَعِيفٌ."],[320,"ضَحَّاكُ بْنُ حَمْزَةَ وَاسِطِي سَكَنَ الشَّامِ .\n• قَالَ الذَّهَبِيُّ: يَضَعُ الْحَدِيثَ، قَالَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٥٢."],[321,"ضَحَّاكُ بْنُ نَبْرَاسَ، بَصْرِي، عَنْ ثَابِتٍ وَيَحْيَى بْنِ أَبِي كَثِيرٍ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٥٨."],[322,"ضِرَارُ بْنُ صُرَدٍ، أَبُو نُعَيْمٍ كُوفِيٌّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٥٩."],[323,"ضِرَارُ بْنُ عَمْرٍو، بِبَغْدَادَ وَالْبَصْرَةُ عَنْ يَزِيدَ الرَّقَاشِيِّ، يَرْوِي عَنْ بَكْرِ بْنِ حُبَيْشٍ الْقَاصِّ مَتْرُوكٌ أَيْضًا."],[324,"طَلْحَةُ بْنُ عَمْرٍو الْمَكِّيُّ عَنْ عَطَاءٍ، وَابْنُ الْمُنْكَدِرِ\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٠."],[325,"طَلْحَةُ بْنُ زَيْدٍ الشَّامِيُّ، عَنْ الْأَوْزَاعِيِّ، وَالْوَضِينُ بْنُ عَطَاءٍ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٥."],[326,"طَرِيفُ بْنُ سُلَيْمَانَ، أَبُو عَاتِكَةَ، كُوفِي عَنْ أَنَسٍ .\n• قَالَ النَّسَائِيُّ: لَيْسَ بِثِقَةٍ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٥."],[327,"طَرِيفُ بْنُ عِيسَى جَزَرِيٌّ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٥٤."],[328,"طَرِيفُ بْنُ عُبَيْدٍ الْمَوْصِلِيُّ، حَدَّثَ عَنْهُ الشَّافِعِيُّ أَبُو بَكْرٍ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ١٥٤."],[329,"طَرِيفُ بْنُ شِهَابٍ السَّعْدِيُّ، أَبُو سُفْيَانَ، ضَعِيفٌ."],[330,"عَبْدُ اللَّهِ بْنُ زِيَادِ بْنِ سَمْعَانَ، مَدَنِيٌّ مَتْرُوكٌ، وَسَعِيدُ بْنُ سَمْعَانَ ثِقَةٌ تَابِعِيٌّ مَدَنِيٌّ."],[331,"عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيُّ، أَبُو عَبَّادٍ مَدَنِيٌّ، وَأَخُوهُ يَحْيَى مَتْرُوكٌ."],[332,"عَبْدُ اللَّهِ بْنُ مُسْلِمِ بْنِ هُرْمُزَ، مَكِّيٌّ، عَنْ مُجَاهِدٍ، وَعَطَاءٍ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ مِنْ السَّادِسَةِ -بْخٌ مدٌّ ت ق- تَقْرِيبُ التَّهْذِيبِ ١٨٩."],[333,"عَبْدُ اللَّهِ بْنُ وَاقِدٍ، أَبُو قَتَادَةَ الْحَرَّانِيُّ .\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ التَّاسِعَةِ، تَقْرِيبُ التَّهْذِيبِ١٩٣."],[334,"عَبْدُ اللَّهِ بْنُ سَلَمَةَ الْأَفْطَسُ، عَنِ الْأَعْمَشِ، وَهِشَامٌ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ، الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٥."],[335,"عَبْدُ اللَّهِ بْنُ جَعْفَرِ بْنِ نَجِيحٍ الْمَدِينِيُّ. وَالِدُ عَلِيٍّ كَثِيرُ الْمَنَاكِيرِ."],[336,"عَبْدُ اللَّهِ بْنُ مَيْسَرَةَ الْكُوفِيُّ عَنِ الشَّعْبِيِّ، وَإِبْرَاهِيمُ بْنُ أَبِي حُرَّةَ يُكْنِيهِ هُشَيْمٌ: أَبَا إِسْحَاقَ، وَأَبُو عَبْدِ الْجَلِيلِ، وَغَيْرُهُ يُكَنِيهِ: أَبَا لَيْلَى .\n• قَالَ الذَّهَبِيُّ: عَبْدُ اللَّهِ بْنُ مَيْسَرَةَ أَبُو لَيْلَى، وَهُوَ أَبُو إِسْحَاقَ، وَأَبُو جَرِيرٍ، وَأَبُو عَبْدِ الْجَلِيلِ كُنَّاهُ بِهَذِهِ الأَرْبَعَةِ هُشَيْمٍ يُدَلِّسُهُ."],[337,"عَبْدُ اللَّهِ بْنُ عَامِرٍ الأَسْلَمِيُّ، مَدَنِيٌّ ضَعِيفٌ."],[338,"عَبْدُ اللَّهِ بْنُ بَشِيرٍ الشَّامِيُّ، عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ وَأَبِي كَبْشَةَ صَحَابِيَّانَ، وَقِيلَ: أَنَّ اسْمَ أَبِي كَبْشَةَ عُمَرُ بْنُ سَعِيدٍ."],[339,"عَبْدُ اللَّهِ بْنُ حَكِيمٍ أَبُو بَكْرٍ الدَّاهِرِيُّ، أَصْلُهُ بِوَاسِطٍ عَنْ هِشَامِ بْنِ عُرْوَةَ .\n• مِيزَانُ الاِعْتِدَالِ ٢/٤١٠."],[340,"عَبْدُ اللَّهِ بْنُ مُحَرِّرٍ بَصَرِيٌّ سَكَنَ الشَّامُ، عَنِ الزُّهْرِيِّ، وَقَتَادَةَ .\n• قَالَ ابْنُ حِحْرٍ: مَتْرُوكٌ مِنَ الثَّامِنَةِ –ق- تَقْرِيبُ التَّهْذِيبِ ١٨٧."],[341,"عَبْدُ اللَّهِ بْنُ عَبْدِ الْقُدُّوسِ، كُوفِيٌّ، سَكَنَ الرَّيُّ، عَنِ الْأَعْمَشِ .\n• صَدُوقٌ رُمِيَ بِالرَّفْضِ وَكَانَ أَيْضًا يُخْطِئُ مِنَ التَّاسِعَةِ -خْتٌ ت- تَقْرِيبُ التَّهْذِيبِ ١٨٠."],[342,"عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ حَسَّانَ الْوَاقِعِيُّ بَصْرِيٌّ، يَكْذِبُ عَنْ شَرِيكٍ."],[343,"عَبْدُ اللَّهِ بْنُ لَهِيعَةَ بْنِ عُقْبَةَ، وَرُبَّمَا نُسِبَ إِلَى جَدِّهِ يُعْتَبَرُ بِمَا يَرْوِي عَنْهُ الْعَبَادِلَةُ ابْنُ الْمُبَارَكِ، وَالْمُقْرِئُ، وَابْنُ وَهْبٍ."],[344,"عَبْدُ اللَّهِ بْنُ مِسْوَرٍ، أَبُو جَعْفَرٍ الْمَدَايِنِيُّ، يُرْسِلُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَنِ ابْنِ مَسْعُودٍ، وَابْنِ عَبَّاسٍ."],[345,"عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ سِنَانٍ الدُّوحِيُّ، مَتْرُوكٌ حَدَّثَ بِالدِّيْنُورِ، وَوَلِيَ قَضَاءَهَا."],[346,"عَبْدُ اللَّهِ بْنُ خِرَاشٍ كُوفِيٌّ عَنْ الْعَوَّامِ بْنِ حَوْشَبٍ .\n• ضَعِيفٌ وَأَطْلَقَ عَلَيْهِ ابْنُ عَمَّارٍ الْكَذِبَ."],[347,"عَبْدُ اللَّهِ بْنُ حَمْدَانَ بْنِ وَهْبٍ الدِّينَوَرِيُّ، حَدَّثُونَا عَنْهُ .\n• قَالَ الذَّهَبِيُّ: مُتَّهَمٌ. مِيزَانُ الاِعْتِدَالِ ٢/ ٤١٢."],[348,"عُبَيْدُ اللَّهِ بْنُ زَحْرٍ، عَنْ عَلِيِّ بْنِ زَيْدٍ نُسْخَةً بَاطِلَةٌ."],[349,"عُبَيْدُ اللَّهِ بْنُ الْوَلِيدِ الْوَصَّافِيُّ، كُوفِيٌّ عَنْ عَطِيَّةَ .\n• قَالَ الذَّهَبِيُّ: ضَعَّفُوهُ. دِيوَانٌ ٢٥٦."],[350,"عُبَيْدُ اللَّهِ بْنُ تَمَّامِ بْنِ قَيْسٍ، بَصْرِي عَنْ التَّيْمِيِّ، وَدَاوُدَ بْنُ أَبِي هِنْدٍ، وَيُونُسَ مَقْلُوبَةٌ .\n• مِيزَانُ الاِعْتِدَالِ ٢/٤."],[351,"عُبَيْدُ اللَّهِ بْنُ أَبِي حُمَيْدٍ، وَهُوَ ابْنُ غَالِبٍ بَصْرِيٌّ عَنْ أَبِي الْمَلِيحِ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٧."],[352,"عَبْدُ الرَّحْمَنِ بْنُ زَيْدٍ عَنْ أَبِيهِ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ الْعُمَرِيِّ عَنْ أَبِيهِ، وَعَمِّهِ سَعِيدٍ، وَأَخِيهِ الْقَاسِمِ، مَتْرُوكٍ."],[353,"عَبْدُ الرَّحْمَنِ بْنُ قَيْسٍ الزَّعْفَرَانِيُّ، أَبُو مُعَاوِيَةَ بَصْرِيٌّ خَرَجَ إِلَى نَيْسَابُورَ، عَنْ شُعْبَةَ، وَالثَّوْرِيِّ، وَحُمَيْدٍ، وَمُحَمَّدِ بْنِ عَمْرٍو .\n• قَالَ النَّسَائِيُّ: ضَعِيفٌ مَدَنِيٌّ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٧."],[354,"عَبْدُ الرَّحْمَنِ بْنُ مَالِكِ بْنِ مِغْوَلٍ، كُوفِيٌّ عَنْ أَبِيهِ، وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ .\n• قَالَ الذَّهَبِيُّ: يَأْتِي بِالطَّامَاتِ. دِيوَانٌ ١٩٠."],[355,"عَبْدُ الرَّحْمَنِ بْنُ مُسْهِرٍ، أَخُو عَلِيِّ بْنِ مُسْهِرٍ عَنْ أَبِي سَعْدٍ الْبَقَّالِ وَهِشَامِ بْنِ عُرْوَةَ، وَأَخُوهُ ثِقَةٌ."],[356,"عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ تَمِيمٍ، شَامِيٌّ أَبُو أُسَامَةَ يَغْلَطُ فِي نَسَبِهِ يَرْوِي عَنِ الزُّهْرِيِّ، وَإِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ بْنِ أَبِي الْمُهَاجِرِ الدِّمَشْقِيِّ، وَإِسْمَاعِيلَ هَذَا ثِقَةٌ."],[357,"عَبْدُ الرَّحْمَنِ بْنُ زِيَادِ بْنِ أَنْعُمٍ الإِفْرِيقِيُّ، لَيْسَ بِالْقَوِيِّ."],[358,"عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ بْنِ الْحَارِثِ أَبُو شَيْبَةَ وَاسْطِيٌّ عَنِ النُّعْمَانِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، لاَ يُعْرَفُ إِلاَّ بِهِ.\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ – د ت - تَقْرِيبُ التَّهْذِيبِ."],[359,"عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ الْعَزْرَمِيُّ، أَخُو إِسْحَاقَ، وَإِسْحَاقُ مَتْرُوكٌ أَيْضًا، وَلَهُمَا أَخٌ ثَالِثٌ يُسَمَّى حَسَنَ لَهُ مَقَاطِيعُ يُعْتَبَرُ بِهِ."],[360,"عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمُلَيْكِيِّ، ابْنُ أُخَيِّ بْنِ أَبِي مُلَيْكَةَ عَنِ ابْنِ أَبِي مُلَيْكَةَ، وَالزُّهْرِيِّ .\n• قَالَ ابْنُ حَجَرٍ: ضَعِيفٌ مِنَ السَّابِعَةِ – ز ق - تَقْرِيبُ التَّهْذِيبِ ١٩٩."],[361,"عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ، يُعْرَفُ بِعَبَّادٍ، يُرْمِى بِالْقَدَرِ ضَعِيفَ الْحَدِيثِ رَوَى عَنِ الزُّهْرِيِّ، رَوَى عَنْهُ إِبْرَاهِيمُ بْنُ طَهْمَانَ، وَأَسْمَاءُ، وَعَبَّادٌ، وَالْبَصْرِيُّونَ رَوَوْا فَقَالُوا عَبْدُ الرَّحْمَنِ ابْنُ إِسْحَاقَ .\n• قَالَ ابْنُ حَجَرٍ: صَدُوقٌ رَمْيٍ بِالْقَدَرِ مِنْ السَّادِسَةِ - خَتٌّ بَخ م ع - تَقْرِيبُ التَّهْذِيبِ ١٩٨."],[362,"عَبْدُ الرَّحِيمِ بْنُ زَيْدٍ الْعَمِّيُّ، بَصْرِي عَنْ أَبِيهِ، أَبُوهُ صَالِحٌ .\n• انْظُرْ: تَقْرِيبَ التَّهْذِيبِ ٢١٢، تَهْذِيبُ التَّهْذِيبِ ٣/٤٠٨."],[363,"عَبْدُ الْوَاحِدِ بْنُ زَيْدٍ الْقَاضِي، بَصْرِيٌّ عَنِ الْحَسَنِ، وَثَابِتٌ .\n• انْظُرْ: لِسَانَ الْمِيزَانِ ٤/٨٠."],[364,"عَبْدُ الْوَاحِدِ بْنُ قَيْسٍ."],[365,"عَبْدُ الْوَاحِدِ بْنُ مَيْمُونٍ، أَبُو حَمْزَةَ مَدَنِيٌّ، عَنْ عُرْوَةَ .\n• قَالَ النَّسَائِيُّ: لَيْسَ ثِقَةً. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٩."],[366,"عَبْدُ الْوَهَّابِ بْنُ مُجَاهِدٍ، مَكِّيٌّ، عَنْ أَبِيهِ، وَعَطَاءٍ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٦٩."],[367,"عَبْدُ الْوَهَّابِ بْنُ الضَّحَّاكِ الْعَرَضِيُّ، حِمْصِيٌّ عَنْ إِسْمَاعِيلَ بْنِ أَبِي عَيَّاشٍ لَهُ مَقْلُوبَاتٌ وَبَوَاطِيلُ."],[368,"عَبْدُ الْأَعْلَى بْنُ أَبِي الْمُسَاوِرِ، كُوفِيٌّ عَنْ حَمَّادٍ، وَالشَّعْبِيِّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٧٠."],[369,"عَبْدُ الْعَزِيزِ بْنُ أَبَانَ، أَبُو خَالِدٍ الْقُرَشِيُّ كُوفِيٌّ عَنْ الثَّوْرِيِّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٧٢."],[370,"عَبْدُ الْعَزِيزِ بْنُ عِمْرَانَ أَبُو ثَابِتٍ الزُّهْرِيُّ مَدَنِيٌّ .\n• قَالَ النَّسَائِيُّ: مَتْرُوكُ الْحَدِيثِ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٧٢."],[371,"عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الرَّحْمَنِ الْبَالِسِيُّ عَنْ خُصَيْفٍ .\n• قَالَ النَّسَائِيُّ: لَيْسَ بِثِقَةٍ. الضُّعَفَاءُ وَالْمَتْرُوكِينَ ٧٢."],[372,"عَبْدُ الْحَمِيدِ بْنُ سُلَيْمَانَ مَدَنِيٌّ، أَخُو فُلَيْحٍ عَنْ أَبِي حَازِمٍ، وَأَخُوهُ ثِقَةٌ."],[373,"عَبْدُ الْحَمِيدِ بْنُ الْحَسَنِ الْهِلَالِيُّ، كُوفِي حَدَثَ بِالْبَصْرَةِ عَنْ أَبِي إِسْحَاقَ، وَعَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ .\n• قَالَ ابْنُ حَجَرٍ: صَدُوقٌ يُخْطِئُ مِنَ الثَّامِنَةِ -ت- تَقْرِيبُ التَّهْذِيبِ ١٩٦."],[374,"عَبْدُ الصَّمَدِ بْنُ سُلَيْمَانَ الْوَاسِطِيُّ، الأَزْرَقُ، ضَعِيفٌ عَنِ الضُّعَفَاءِ عَنْ سُلَيْمَانَ بْنِ أَبِي سِرَاجٍ، وَخَصِيبِ بْنِ جَحْدَرٍ مَتْرُوكٌ"],[375,"عَبْدُ الرَّزَّاقِ بْنُ عُمَرَ، الشَّامِيُّ ضَعِيفٌ."],[376,"عَبْدُ الْجَبَّارِ بْنُ عُمَرَ الأَيْلِيُّ، ضَعِيفٌ."],[377,"عَبْدُ الْغَفَّارِ بْنُ الْقَاسِمِ، أَبُو مَرْيَمَ كُوفِيٌّ ضَعِيفٌ حَدَّثَ عَنْهُ شُعْبَةُ وَلَعَلَّهُ لَمْ يُخْبِرْهُ."],[378,"عَبْدُ الْغَفُورِ بْنُ عَبْدِ الْعَزِيزِ بْنِ سَعِيدٍ، أَبُو الصَّبَّاحِ الْوَاسِطِيُّ لَهُ عَنْ أَبِي هَاشِمٍ الرُّمَّانِيِّ نُسْخَةَ."],[379,"عَبْدُ الْخَالِقِ بْنُ زَيْدِ بْنِ وَاقِدٍ دِمَشْقِيٌّ، عَنْ أَبِيهِ، وَأَبُوهُ ثِقَةٌ رَوَى عَنْ حِزَامِ بْنِ حَكِيمٍ، وَمَكْحُولٍ .\n• قَالَ النَّسَائِيُّ: لَيْسَ بِثِقَةٍ. دِيوَانٌ ١٨٥."],[380,"عَبْدُ الْمُنْعِمِ بْنُ إِدْرِيسَ بْنِ سِنَانٍ، سَكَنَ بَغْدَادُ، عَنْ أَبِيهِ، وَأَبُوهُ مَتْرُوكٌ عَنْ وَهْبِ ابْنِ مُنَبِّهٍ .\n• انْظُرْ: دِيوَانٌ ١٥-٢٠١."],[381,"عَبْدُ الْمُنْعِمِ بْنُ نُعَيْمٍ أَبُو سَعِيدٍ بَصْرِيٌّ رِيَاحِيٌّ، عَنْ يَحْيَى بْنِ مُسْلِمٍ مَجْهُولٍ لَا يُعْرَفُ إِلَّا بِهِ، وَعَنْ الْأَعْمَشِ .\n• قَالَ الذَّهَبِيُّ: مُقِلٌّ ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ٢٠١."],[382,"عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ، أَبُو أُمَيَّةَ الْبَصْرِيُّ، عَنْ نَافِعٍ، وَابْنِ سِيرِينَ، وَالْحَسَنِ، يَرْوِي عَنْهُ ابْنُ أَبِي لَيْلَى. وَيَرْوِي عَنْهُ، وَعَنْ الْجَزَرِيِّ الثَّوْرِيِّ، وَابْنِ جُرَيْجٍ يَرْوِيَانِ عَنْهُ، وَعَنْ عَبْدِ الْكَرِيمِ الْجَزَرِيِّ .\n• قَالَ ابْنُ حَجَرٍ: عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ ضَعِيفٌ مِنَ السَّادِسَةِ، وَقَدْ شَارَكَ الْجَزَرِيُّ فِي بَعْضِ الْمَشَايِخِ فَرُبَّمَا الْتَبَسَ بِهِ عَلَى مَنْ لاَ فَهْمَ لَهُ. تَقْرِيبُ التَّهْذِيبِ ٢١٧."],[383,"عَبْدُ الْمَلِكِ بْنُ هَارُونَ بْنِ عَنْتَرَةَ الْكُوفِيُّ، رُوِىَ عَنْ حَبِيبِ بْنِ أَبِي ثَابِتٍ، وَأَبِي إِسْحَاقَ .\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ. دِيوَانٌ ٢٠١."],[384,"عَبْدُ الْمَلِكِ بْنُ حُسَيْنٍ أَبُو مَالِكٍ النَّخَعِيُّ، عَنِ الْبَصْرِيِّينَ، وَالْكُوفِيِّينَ."],[385,"عَبْدُ السَّلاَمِ بْنُ أَبِي الْجَنُوبِ، عَنِ الزُّهْرِيِّ، وَخَالِدُ بْنُ قُدَامَةَ."],[386,"عَبْدُ الْقُدُّوسِ بْنُ حَبِيبٍ، شَامِيٌّ أَبُو سَعِيدٍ عَنِ الشَّعْبِيِّ، وَعِكْرِمَةَ، وَالْحَسَنِ، وَالزُّهْرِيِّ .\n• قَالَ الذَّهَبِيُّ: مَتْرُوكٌ لَقِيَ التَّابِعِينَ. دِيوَانٌ ١٩٧."],[387,"عَلَّاءُ بْنُ زَيْدَلٍ، بَصْرِيٌّ عَنْ أَنَسٍ"],[388,"عَلاَءُ بْنُ زَيْدٍ، أَيْضًا، مَتْرُوكٌ مِنْ أَهْلِ الْبَصْرَةِ."],[389,"عُمَرُ بْنُ هَارُونَ الْبَلْخِيُّ، ضَعِيفٌ."],[390,"عُمَرُ بْنُ رِيَاحٍ الضَّرِيرُ بَصْرِيٌّ، وَيُقَالُ عُمَرُ بْنُ أَبِي عُمَرَ عَنِ ابْنِ طَاوُسٍ، وَهِشَامُ ابْنُ عُرْوَةَ .\n• انْظُرْ: مِيزَانَ الاِعْتِدَالِ ٣/١٩٧."],[391,"عُمَرُ بْنُ حَفْصٍ أَبُو حَفْصٍ بَصْرِيٌّ، عَنْ ثَابِتٍ، وَيَزِيدُ الرَّقَاشِيُّ."],[392,"عُمَرُ بْنُ إِسْمَاعِيلَ بْنِ مُجَالِدٍ، بَغْدَادِيٌّ عَنْ أَبِيهِ، وَأَبِي مُعَاوِيَةَ، وَيَحْيَى الأُمَوِيِّ."],[393,"عُمَرُ بْنُ مُوسَى بْنِ وَجِيهٍ الْوَجِيهِيُّ، كُوفِيَ عَنْ أَبِي الزُّبَيْرِ، وَأَبِي إِسْحَاقَ، وَقَتَادَةَ، يَرْوِي عَنْهُ يَحْيَى بْنُ يَعْلَى الأَسْلَمِيُّ، فَيَقُولُ: عَنْ عُبَيْدِ اللَّهِ بْنِ مُوسَى، وَقِيلَ: إِنَّهُ عُمَرُ هَذَا .\n• انْظُرْ: مِيزَانَ الاِعْتِدَالِ ٢/٢٢٤."],[394,"عُمَرُ بْنُ سَعِيدٍ أَبُو حَفْصٍ الدِّمَشْقِيُّ، عَنْ سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ، وَسَعِيدِ بْنِ بَشِيرٍ بَوَاطِيلَ."],[395,"عُمَرُ بْنُ صَالِحِ بْنِ أَبِي الزَّاهِرِيَّةِ وَاسْطِيٌّ عَنْ أَبِي حَمْزَةَ."],[396,"عُمَرُ بْنُ غِيَاثٍ، وَقِيلَ: عَمْرٌو كُوفِيٌّ، عَنْ عَاصِمٍ، وَعَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ .\n• انْظُرْ: مِيزَانَ الاِعْتِدَالِ ٢/٢١٦."],[397,"عُمَرُ بْنُ عَبْدِ اللَّهِ بْنِ يَعْلَى بْنِ مُرَّةَ الثَّقَفِيُّ، عَنْ أَبِيهِ عَنْ جَدِّهِ، وَأَبُوهُ لَا يُعْرَفُ إِلَّا بِهِ، وَرَوَى أَيْضًا عَنْ زِيَادِ بْنِ عِلَاقَةَ عَنِ الْمِنْهَالِ بْنِ عَمْرٍو .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ: مَتْرُوكٌ. مِيزَانُ الاِعْتِدَالِ ٣/٢١١."],[398,"عُمَرُ بْنُ مُحَمَّدِ بْنِ صُهْبَانَ، مَدَنِيٌّ عَنِ الزُّهْرِيِّ، وَأَبِي حَازِمٍ .\n• قَالَ الذَّهَبِيُّ: قُلْتُ: هُوَ عُمَرُ بْنُ صُهْبَانَ نُسِبَ إِلَى جَدِّهِ. مِيزَانُ الاِعْتِدَالِ ٣/٢٢٠."],[399,"عُمَرُ بْنُ قَيْسٍ. سَنْدَلٌ مَكِّيٌّ، عَنِ الزُّهْرِيِّ، وَعَطَاءٍ، وَعَمْرِو بْنِ دِينَارٍ."],[400,"عُمَرُ بْنُ رَاشِدٍ الْيَمَامِيُّ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ."],[401,"عُمَيْرُ بْنُ عِمْرَانَ الْحَنَفِيُّ، عَنْ عَلاَءِ بْنِ خَالِدٍ، وَالْعَلاَءِ يَعْتَبِرُ بِهِ."],[402,"عُمَارَةُ بْنُ جُوَيْنٍ، أَبُو هَارُونَ الْعَبْدِيُّ مُتَلَوِّنٌ خَارِجِيٌّ، وَشِيعِيٌّ، يَصْلُحُ أَنْ يُعْتَبَرَ لَهُ بِمَا يَرْوِيهِ عَنْهُ الثَّوْرِيُّ، وَالْحَمَّادَانِ .\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ: مُتَلَوِّنٌ خَارِجِي، وَشِيعِيٌّ، فَيُعْتَبَرُ بِمَا رَوَى عَنْهُ الثَّوْرِيُّ. مِيزَانُ الاِعْتِدَالِ ٣/١٧٣."],[403,"عُمَارَةُ بْنُ زَاذَانَ الصَّيْدَلاَنِيُّ، بَصْرِيٌّ عَنْ ثَابِتٍ، وَأَبِي غَالِبٍ حَزُوْرٌ.\n• قَالَ الإِمَامُ أَحْمَدُ: كَذَّابٌ، دِيوَانٌ ١٦٥."],[404,"عَبَّادُ بْنُ جُوَيْرِيَةَ بَصْرِيٌّ، عَنِ الأَوْزَاعِيِّ."],[405,"عَبَّادُ بْنُ كَثِيرٍ بَصْرِيٌّ، نَزَلَ مَكَّةَ عَنِ الْحُسَيْنِ."],[406,"عَبَّادُ بْنُ كَثِيرٍ، رَمْلِيٌّ فَلِسَطِينِي، عَنِ الْبَصْرِيِّينَ، وَعَنْ قُتَيْلَةَ عَنِ ابْنِهَا."],[407,"عَمْرُو بْنُ جَابِرٍ أَبُو زُرْعَةَ، مِصْرِيٌّ تَابِعِيٌّ عَنْ جَابِرٍ."],[408,"عَمْرُو بْنُ جُمَيْعٍ، كُوفِي، وَكَانَ بِحُلْوَانَ."],[409,"عَمْرُو بْنُ عَطِيَّةَ الْعَوْفِيُّ، ضَعِيفٌ."],[410,"عَمْرُو بْنُ أَبِي رَوْقٍ.\n• قَالَ الذَّهَبِيُّ: اسْمُ أَبِيهِ عَطِيَّةُ، ضَعَّفَهُ الدَّارَقُطْنِيُّ. دِيوَانٌ ٢٣٥."],[411,"عَطِيَّةُ بْنُ الْحَارِثِ، ضَعِيفٌ."],[412,"عَمْرُو بْنُ الْحُصَيْنِ الْعُقَيْلِيُّ، مَتْرُوكٌ عَنِ الأَعْمَشِ، وَيَحْيَى بْنِ سَعِيدٍ، وَابْنِ جُرَيْجٍ."],[413,"عَمْرُو بْنُ زِيَادٍ الثَّوْبَانِيُّ، يَضَعُ الْحَدِيثَ."],[414,"عَمْرُو بْنُ عُثْمَانَ الْكِلاَبِيُّ، ضَعِيفٌ."],[415,"عَمْرُو بْنُ وَاقِدٍ دِمَشْقِيٌّ، عَنْ عُمَرَ بْنِ يَزِيدَ الْبَصْرِيِّ، وَيُونُسَ بْنِ مَيْسَرَةَ.\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مِنَ السَّادِسَةِ -د ق- تَقْرِيبُ التَّهْذِيبِ ٢٦٣."],[416,"عَمْرُو بْنُ الأَزْهَرِ بَصْرِيٌّ، قَاضِي جُرْجَانَ كَذَّابٌ، عَنِ الْبَصْرِيِّينَ."],[417,"عُبَيْدُ بْنُ الْقَاسِمِ كُوفِيٌّ ضَعِيفٌ."],[418,"عُبَيْدُ بْنُ إِسْحَاقَ الْعَطَّارُ، كُوفِيٌّ ضَعِيفٌ."],[419,"عَمْرُو بْنُ جَرِيرٍ أَبُو سَعِيدٍ الْبَجَلِيُّ، كُوفِي، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، وَإِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ.\n• قَالَ الذَّهَبِيُّ: مُتَّهَمٌ وَاهٍ. دِيوَانٌ ٢٣٤."],[420,"عَمْرُو بْنُ قَائِدٍ بَصْرِيٌّ، قَدْ رُوِىَ عَنْ بَصْرِيِّينَ، وَمَكِّيِّينَ، وَمَدْنِينَ."],[421,"عَمْرُو بْنُ شِمْرٍ أَبُو عَبْدِ اللَّهِ، كُوفِيٌّ، عَنْ جَابِرٍ، وَعَنْ جَعْفَرِ بْنِ مُحَمَّدٍ."],[422,"عَمْرُو بْنُ عُبَيْدٍ أَبُو عُثْمَانَ، بَصْرِيٌّ عَنِ الْحَسَنِ"],[423,"عَمْرُو بْنُ ثَابِتِ بْنِ هُرْمُزَ، أَبُو الْمِقْدَامِ، كُوفِيٌّ.\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ. دِيوَانٌ ٢٣٤."],[424,"عَمْرُو بْنُ خَالِدٍ أَبُو خَالِدٍ الْوَاسِطِيُّ، كَذَّابٌ، عَنْ أَبِي هَاشِمٍ الرُّمَّانِيِّ، وَزَيْدِ بْنِ عَلِيٍّ."],[425,"عُثْمَانُ بْنُ عَبْدِ الرَّحْمَنِ يُعْرَفُ بِالْوَقَّاصِيِّ مَدَنِيٌّ، عَنِ الزُّهْرِيِّ، وَابْنِ أَبِي مُلَيْكَةَ."],[426,"عُثْمَانُ بْنُ مِقْسَمٍ الْبَرِّيُّ بَصْرِيٌّ، أَبُو سَلَمَةَ عَنْ يَحْيَى بْنِ سَعِيدٍ، وَهِشَامِ بْنِ عُرْوَةَ.\n• قَالَ الذَّهَبِيُّ: كَذَّبَهُ جَمَاعَةٌ. دِيوَانٌ ٢١١."],[427,"عُثْمَانُ بْنُ عُمَيْرٍ أَبُو الْيَقْظَانِ، كُوفِيٌّ، عَنْ أَبِي الطُّفَيْلِ، وَسَعِيدِ بْنِ جُبَيْرٍ."],[428,"عُثْمَانُ بْنُ مَطَرٍ بَصْرِيٌّ، عَنْ ثَابِتٍ"],[429,"عَلِيُّ بْنُ يَزِيدَ الدِّمَشْقِيُّ، أَبُو عَبْدِ الْمَلِكِ بْنُ الْقَاسِمِ."],[430,"عَلِيُّ بْنُ أَبِي عَلِيٍّ اللَّهَبِيُّ، مَكِّيٌّ، عَنِ ابْنِ الْمُنْكَدِرِ، وَجَعْفَرِ بْنِ مُحَمَّدٍ، وَالزُّهْرِيِّ."],[431,"عَلِيُّ بْنُ حَزُّورٍ، وَهُوَ ابْنُ أَبِي فَاطِمَةَ، كُوفِيَ عَنْ أَصْبَغَ بْنِ نُبَاتَةَ، وَأَبِي مَرْيَمَ الْحَنَفِيِّ.\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ: ضَعِيفٌ، وَيُقَالُ لَهُ عَلِيُّ بْنُ أَبِي فَاطِمَةَ يُدَلِّسُ بِذَلِكَ. مِيزَانُ الاِعْتِدَالِ ٣/ ١١٨."],[432,"عَلِيُّ بْنُ ظَبْيَانَ، كُوفِي عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ، وَأَبِي حَنِيفَةَ."],[433,"عَاصِمُ بْنُ سُلَيْمَانَ الْكُوزِيُّ، بَصْرِيٌّ كَذَّابٌ، عَنْ هِشَامٍ، وَغَيْرِهِ."],[434,"عِيسَى بْنُ أَبِي عِيسَى الْحَنَّاطُ، مَدَنِيٌّ، عَنِ الشَّعْبِيِّ، وَأَخُوهُ مُوسَى بْنُ أَبِي عِيسَى صَالِحٌ الْحَدِيثِ وَاسْمُ أَبِي عِيسَى مَيْسَرَةُ.\n• قَالَ الذَّهَبِيُّ: عِيسَى بْنُ أَبِي عِيسَى مَيْسَرَةُ الْمَدَنِيُّ الْحَنَّاطُ، وَهُوَ الْخَيَّاطُ. مِيزَانُ الاِعْتِدَالِ ٣/ ٣٢٠."],[435,"عِيسَى بْنُ مَيْمُونٍ، عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، وَهِشَامِ بْنِ عُرْوَةَ."],[436,"فَأَمَّا عِيسَى بْنُ مَيْمُونٍ الْمَكِّيُّ، فَهُوَ ثِقَةٌ يُعْرَفُ بِابْنِ دَايِهٍ يَرْوِي عَنْ ابْنِ أَبِي نَجِيحٍ سَكَنَ الْبَصْرَةِ"],[437,"عِيسَى بْنُ قِرْطَاسٍ، كُوفِيَ عَنْ عِكْرِمَةَ، وَالنَّخَعِيِّ."],[438,"عِيسَى بْنُ هَاشِمٍ الْبَرِّيُّ، أَبُو مُعَاوِيَةَ"],[439,"عِيسَى بْنُ الْمُسَيِّبِ، كُوفِيٌّ، عَنْ عَطِيَّةَ، وَالشَّعْبِيِّ"],[440,"عِيسَى بْنُ مِهْرَانَ الْمُسْتَعْطِفُ، بَغْدَادِيٌّ، رَجُلُ سُوءٍ وَمَذْهَبُ سُوءٍ، رَوَى عَنْهُ ابْنُ جَرِيرٍ الطَّبَرِيُّ.\n• قَالَ الْخَطِيبُ: كَانَ مِنْ شَيَاطِينِ الرَّافِضَةِ وَمَرَدَّتِهِمْ وَقَعَ إِلَيَّ كِتَابٌ مِنْ تَصْنِيفِهِ فِي الطَّعْنِ عَلَى الصَّحَابَةِ، وَتَضْلِيلِهِمْ، وَإِكْفَارِهِمْ، وَتَفْسِيقِهِمْ؛ فَوَاللَّهِ لَقَدْ وَقَفَ شِعْرِي عِنْدَ نَظَرِي فِيهِ، وَعَظْمَ تَعَجُّبِي مِمَّا أَوْدَعَ ذَلِكَ الْكِتَابَ مِنَ الأَحَادِيثِ الْمَوْضُوعَةِ. تَارِيخُ بَغْدَادَ ١١/ ١٦٧."],[441,"عَنْبَسَةُ بْنُ سَعِيدٍ أَخُو الرَّبِيعِ السَّمَّانُ أَشْعَثُ بْنُ سَعِيدٍ، ضَعِيفٌ، عَنِ الزُّهْرِيِّ"],[442,"عِيسَى بْنُ مَيْمُونٍ بَصْرِيٌّ، أَبُو عُبَيْدَةَ عَنْ يَزِيدَ الرَّقَاشِيِّ، وَيَحْيَى بْنِ أَبِي كَثِيرٍ."],[443,"عَنْبَسَةُ بْنُ عَبْدِ الرَّحْمَنِ الْقُرَشِيُّ، أَظُنُّهُ بَغْدَادِيٌّ عَنْ زَيْدِ بْنِ أَسْلَمَ، وَعَبْدِ اللَّهِ بْنِ نَافِعٍ."],[444,"عُقْبَةُ بْنُ عَبْدِ اللَّهِ الرَّفَاعِيُّ، الأَصَمُّ بَصْرِيٌّ عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ، وَالْحَسَنِ."],[445,"عَطَاءُ بْنُ عَجْلاَنَ بَصْرِيٌّ، عَنْ أَنَسٍ، وَأَبِي ضَمْرَةَ.\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ: ضَعِيفٌ لاَ يُعْتَبَرُ بِهِ، وَقَالَ مَرَّةً: مَتْرُوكٌ. مِيزَانُ الاِعْتِدَالِ ٣/ ٧٥."],[446,"عَبَّاسُ بْنُ بَكَّارٍ الضَّبِّيُّ بَصْرِيٌّ، كَذَّابٌ"],[447,"عَبَّاسُ بْنُ الْفَضْلِ الأَنْصَارِيُّ مَوْصِلِيٌّ، ضَعِيفٌ."],[448,"عَطَّافُ بْنُ خَالِدٍ الْمَخْزُومِيُّ مَدَنِيٌّ، ضَعِيفٌ.\n• فِي أَصْلِ الْمَخْطُوطِ: عَطَّافِ بْنِ خَالِدٍ الْعَزْرَمِيِّ، وَالتَّصْوِيبُ مِنْ كُتُبِ الرِّجَالِ. انْظُرْ: مِيزَانَ الاِعْتِدَالِ ٣/ ٦٩، تَقْرِيبُ التَّهْذِيبِ ٢٤٠."],[449,"غِيَاثُ بْنُ إِبْرَاهِيمَ كُوفِيٌّ عَنِ الْعَالِمِ.\n• قَالَ الذَّهَبِيُّ. تَرَكُوهُ دِيوَانٌ ٢٤٥."],[450,"غِيَاثُ بْنُ كَلُّوبٍ لَهُ نُسْخَةٌ عَنْ مُطَرِّفِ بْنِ سَمُرَةَ بْنِ جُنْدُبٍ لاَ يُعْرَفُ إِلاَّ بِهِ وَيَرْوِي عَنْ شَرِيكٍ."],[451,"غَالِبُ بْنُ عُبَيْدِ اللَّهِ الْجَزَرِيُّ عَنْ عَطَاءٍ وَالزُّهْرِيِّ وَأَبِي إِسْحَاقَ."],[452,"غَانِمُ بْنُ الأَحْوَصِ حِجَازِيٌّ عَنْ أَبِي صَالِحٍ السَّمَّانِ."],[453,"غُطَيْفُ بْنُ أَعْيَنَ كُوفِيٌّ عَنْ مُصْعَبِ بْنِ سَعْدٍ.\n• قَالَ الْحَافِظُ: وَيُقَالُ بِالضَّادِ الْمُعْجَمَةِ. تَقْرِيبُ التَّهْذِيبِ ٢٧٤."],[454,"غُطَيْفٌ الْجَزَرِيُّ وَيُقَالُ الطَّائِفِيُّ رُوِيَ عَنْهُ أَسَدُ بْنُ عَمْرٍو الْبَجَلِيُّ وَيَرْوِي عَنْهُ الْقَاسِمُ بْنُ مَالِكٍ فَيَقُولُ رَوْحُ بْنُ غُطَيْفٍ. هُوَ. هُوَ."],[455,"فَايِدُ بْنُ عَبْدِ الرَّحْمَنِ أَبُو الْوَرْقَاءِ كُوفِيٌّ عَنِ ابْنِ أَبِي أَوْفَى وَمُحَمَّدِ بْنِ الْمُنْكَدِرِ.\n• قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ اتَّهَمُوهُ مِنْ صِغَارِ الْخَامِسَةِ- ت ق- تَقْرِيبُ التَّهْذِيبِ ٢٧٤."],[456,"فُرَاتُ بْنُ السَّائِبِ جَزَرِيٌّ عَنْ مَيْمُونِ بْنِ مِهْرَانَ وَأَبِي إِسْحَاقَ.\n• قَالَ الْبُخَارِيُّ تَرَكُوهُ مُنْكَرَ الْحَدِيثِ. التَّارِيخُ الْكَبِيرُ ٤/ ١/ ١٣٠."],[457,"فَرْقَدُ بْنُ يَعْقُوبَ السَّبْخِيُّ أَبُو يَعْقُوبَ بَصْرِيٌّ عَنْ مَرَّةَ الطَّيِّبِ وَالنَّخَعِيِّ.\n• قَالَ الذَّهَبِيُّ: وَثَّقَهُ ابْنُ مَعِينٍ وَقَالَ أَحْمَدُ لَيْسَ بِقَوِيٍّ وَقَالَ الدَّارَقُطْنِيُّ ضَعِيفٌ، دِيوَانٌ ٢٤٧."],[458,"فَهَدَ بْنُ حَيَّانَ بَصْرِيٌّ عَنْ شُعْبَةَ وَأَبِي عَوَانَةَ.\n• قَالَ الذَّهَبِيُّ: ضَعَّفُوهُ. دِيوَانٌ ٢٥٠."],[459,"فَهَدَ بْنُ عَوْفٍ أَبُو رَبِيعَةَ وَيُقَالُ زَيْدٌ. بَصْرِي. عَنْ حَمَّادِ بْنِ زَيْدٍ.\n• قَالَ ابْنُ الْمَدِينِيِّ كَذَّابٌ. دِيوَانٌ ٢٥٠."],[460,"فِطْرُ بْنُ مُحَمَّدٍ الْعَطَّارُ الأَحْدَبُ. حَدَّثُوا عَنْهُ. كَذَّابٌ."],[461,"قَاسِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ الْعُمَرِيُّ عَنْ أَبِيهِ وَعَمِّهِ وَعَبْدِ اللَّهِ بْنِ دِينَارٍ."],[462,"قَاسِمُ بْنُ إِبْرَاهِيمَ الْمُلَطِيُّ عَنْ مَالِكٍ يَكْذِبُ.\n• فِي أَصْلِ الْمَخْطُوطِ قَاسِمُ بْنُ إِبْرَاهِيمَ الْمَطْلِيِّ وَالتَّصْوِيبُ مِنْ مِيزَانِ الاِعْتِدَالِ ٣/ ٣٦٧."],[463,"قَاسِمُ بْنُ أَبِي شَيْبَةَ عَنِ الْبَصْرِيِّينَ وَالْكُوفِيِّينَ.\n• قَالَ الذَّهَبِيُّ: الْقَاسِمُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَهٍ أَخُو أَبِي بَكْرٍ. دِيوَانٌ ٢٥٢."],[464,"قَاسِمُ بْنُ مُحَمَّدِ بْنِ حَمَّادٍ الدَّلاَلُ كُوفِيٌّ."],[465,"قَزَعَةُ بْنُ سُوَيْدٍ الْبَصْرِيُّ يَغْلِبُ عَلَيْهِ الْوَهْمُ."],[466,"كَثِيرُ بْنُ سُلَيْمٍ بَصْرِيٌّ عَنْ أَنَسٍ."],[467,"كَثِيرُ بْنُ عَبْدِ اللَّهِ الأَبْلِيُّ أَبُو هَاشِمٍ عَنْ أَنَسٍ.\n• قَالَ الذَّهَبِيُّ: ذَهَبَ ابْنُ حِبَّانَ إِلَى أَنَّ هَذَا وَكَثِيرَ بْنَ سُلَيْمٍ وَاحِدٌ وَلَيْسَ هَذَا بِشَيْءٍ. مِيزَانُ الاِعْتِدَالِ ٣/ ٤٠٦."],[468,"كَثِيرُ بْنُ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عَوْفٍ الْمُزَنِيُّ عَنْ أَبِيهِ عَنْ جَدِّهِ."],[469,"كَثِيرُ بْنُ مَرْوَانَ الْمَقْدِسِيُّ عَنْ إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ."],[470,"كَوْثَرُ بْنُ حَكِيمٍ الْحَلَبِيُّ عَنْ نَافِعٍ."],[471,"لُوطُ بْنُ يُحَيٍّ الْكُوفِيُّ أَبُو مِخْنَفٍ إِخْبَارِيٌّ. ضَعِيفٌ."],[472,"مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ مَكِّيٌّ.\n• قَالَ الذَّهَبِيُّ: تَرَكُوهُ وَاجْمَعُوا عَلَى ضَعْفِهِ وَهُوَ مُحَمَّدٌ الْمُحْرِمُ دِيوَانٌ ٢٧٦."],[473,"مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ عَنْ أَبِيهِ. وَزَيْدُ بْنِ أَسْلَمَ. وَعَطَاءٍ، وَالْحَكَمِ، وَعُبَيْدُ اللَّهِ هَذَا. لَيْسَ بِصَاحِبِ عَلِيٍّ. ذَاكَ عُبَيْدُ اللَّهِ بْنُ عَلِيِّ بْنِ أَبِي رَافِعٍ."],[474,"مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ بْنِ أَبِي سُلَيْمَانَ الْعَزْرَمِيُّ. وَهُوَ ابْنُ أَخِي عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ."],[475,"مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ. أَبُو جَابِرٍ الْبَيَاضِيُّ عَنِ ابْنِ الْمُسَيِّبِ."],[476,"مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ. يَمَانِيٌّ. عَنْ أَبِيهِ وَأَبُوهُ يُعْتَبَرُ بِهِ."],[477,"مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الْمُلَيْكِيُّ الْقُرَشِيُّ الْجَدْعَانِيُّ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ، وَابْنِ أَبِي مُلَيْكَةَ.\n• فِي أَصْلِ الْمَخْطُوطِ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الْمَكِّيِّ وَالتَّصْوِيبِ مِنْ كُتُبِ الرِّجَالِ. أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٣/ ٦١٩، دِيوَانٌ ٢٧٩."],[478,"مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَبِيبِهِ. مَرَاسِيلَ. عَنْ سَعْدٍ وَابْنِ عُمَرَ.\n• قَالَ ابْنُ حَجَرٍ: مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ لَبِيبَةَ بِفَتْحِ اللَّاَمِ وَكَسْرِ الْمُوَحَّدَةِ وَسُكُونِ التَّحْتَانِيَّةِ وَفَتْحِ الْمُوَحَّدَةِ الأُخْرَى. وَيُقَالُ ابْنُ أَبِي لَبِيبَةَ. تَقْرِيبُ التَّهْذِيبِ ٩/ ٣٠١، تَقْرِيبُ التَّهْذِيبِ ٣٠٨."],[479,"مُحَمَّدُ بْنُ عَبْدِ الْعَزِيزِ بْنِ عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ عَنْ أَبِي الزِّنَادِ، وَالزُّهْرِيِّ."],[480,"مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ الأَنْصَارِيُّ. مَدَنِيٌّ. عَنْ نَافِعٍ وَالزُّهْرِيِّ وَابْنِ الْمُنْكَدِرِ."],[481,"مُحَمَّدُ بْنُ حَجَّاجٍ الْمُصَفَّرُ بَغْدَادِيٌّ. عَنْ شُعْبَةَ وَمَالِكٍ."],[482,"مُحَمَّدُ بْنُ حَجَّاجٍ اللَّخْمِيُّ. الْوَاسِطِيُّ. يَكْذِبُ. عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ وَمُجَالِدٍ."],[483,"مُحَمَّدُ بْنُ حَجَّاجِ بْنِ سُوَيْدٍ الْبُرْجُمِيُّ كُوفِيٌّ عَنْ هِشَامِ بْنِ عُرْوَةَ. مِنَ الشِّيعَةِ."],[484,"مُحَمَّدُ بْنُ سَعِيدِ بْنِ أَبِي قَيْسٍ الْمَصْلُوبُ شَامِيٌّ عَنْ عُبَادَةَ بْنِ أَنَسِيٍّ، وَالزُّهْرِيِّ، وَإِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ بْنِ أَبِي الْمُهَاجِرِ.\n• قَالَ الذَّهَبِيُّ: كَذَّابٌ صُلْبٌ فِي الزَّنْدَقَةِ أَخْرَجَهُ الْبُخَارِيُّ فِي أَمَاكِنَ مِنْ تَارِيخِهِ لاِخْتِلاَفِهِمْ فِي اسْمِهِ وَنَسَبِهِ وَتَقَلُّصِ اسْمِهِ عَلَى وُجُوهٍ. دِيوَانٌ ٢٧٣."],[485,"مُحَمَّدُ بْنُ سَالِمٍ أَبُو سَهْلٍ كُوفِيٌّ عَنِ الشَّعْبِيِّ وَالْحَكَمِ."],[486,"مُحَمَّدُ بْنُ كُرَيْبٍ مَدَنِيٌّ عَنْ أَبِيهِ"],[487,"مُحَمَّدُ بْنُ عُثَيْمٍ أَبُو ذَرٍّ عَنِ ابْنِ الْبَيْلَمَانِيِّ."],[488,"مُحَمَّدُ بْنُ عَوْنٍ الْخُرَاسَانِيُّ سَكَنَ الْكُوفَةَ عَنْ نَافِعٍ وَسَعِيدِ بْنِ جُبَيْرٍ."],[489,"مُحَمَّدُ بْنُ زِيَادٍ الْمَيْمُونِيُّ.\n• هُوَ مُحَمَّدُ بْنُ زِيَادٍ الْيَشْكُرِيُّ الْمَيْمُونِيُّ الطَّحَّانُ. مِيزَانُ الاِعْتِدَالِ ٣/ ٥٥٢."],[490,"مُحَمَّدُ بْنُ مِهْرَانَ يَكْذِبُ.\n• قَالَ الذَّهَبِيُّ: مُحَمَّدُ بْنُ مُسْلِمٍ وَيُقَالُ مُحَمَّدُ بْنُ مِهْرَانَ بْنِ مُسْلِمِ بْنِ الْمُثَنَّى، مِيزَانُ الاِعْتِدَالِ ٤/ ٣٦."],[491,"مُحَمَّدُ بْنُ السَّائِبِ الْكَلْبِيُّ."],[492,"مُحَمَّدُ بْنُ زَاذَانَ شَامِيٌّ. عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ وَأُمِّ سَعْدٍ الأَنْصَارِيَّةِ. هِيَ لاَ تُعْرَفُ إِلاَّ بِهِ."],[493,"مُحَمَّدُ بْنُ زَيْدٍ الْعَبْدِيُّ بِالْبَصْرَةِ عَنْ أَبِي الأَعْيَنِ وَسَعِيدِ بْنِ جُبَيْرٍ."],[494,"مُحَمَّدُ بْنُ مَرْوَانَ السُّدِّيُّ أَبُو عَبْدِ الرَّحْمَنِ كُوفِيٌّ. مُصَنَّفٌ. عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ وَيَزِيدَ بْنِ أَبِي زِيَادٍ."],[495,"مُحَمَّدُ بْنُ مُعَاوِيَةَ النَّيْسَابُورِيُّ حَدَّثَ بِبَغْدَادَ ثُمَّ بِمَكَّةَ وَلَيْسَ هُوَ ابْنُ مَالِجٍ، ابْنُ صَالِحٍ ثِقَةٌ.\n• قَالَ الذَّهَبِيُّ مُحَمَّدُ بْنُ مُعَاوِيَةَ النَّيْسَابُورِيُّ وَهُوَ مُحَمَّدُ بْنُ مُعَاوِيَةَ ابْنُ أَعْيَنَ الْهِلالِيُّ يُكَنَّى أَبَا عَلِيٍّ. وَقَالَ ابْنُ حَجَرٍ. ابْنُ مَالِجٍ بِمِيمٍ وَجِيمٍ وَاسْمُ جَدِّهِ يَزِيدُ الأَنْمَاطِيُّ. وَأَبُو جَعْفَرٍ الْبَغْدَادِيُّ صَدُوقٌ رُبَّمَا وَهَمَ. أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٣/ ٤٤، تَقْرِيبُ التَّهْذِيبِ ٣١٩."],[496,"مُحَمَّدُ بْنُ كَثِيرٍ الْقَصَّابُ السُّلَمِيُّ بَصْرِيٌّ. وَقَالَ يُحَيُّ بْنُ مَعِينٍ ثِقَةٌ عَنْ يُونُسَ ابْنِ عُبَيْدٍ."],[497,"مُحَمَّدُ بْنُ الْحَسَنِ بْنِ زُبَالَةَ. مَدَنِيٌّ. عَنْ مَالِكٍ، وَسُلَيْمَانَ بْنِ بِلاَلٍ."],[498,"مُحَمَّدُ بْنُ الْحَسَنِ بْنِ آتَشَ صَنْعَانِيٌّ."],[499,"مُحَمَّدُ بْنُ الْفَضَاءِ الْمُعَبِّرُ بَصْرِيٌّ عَنْ أَبِيهِ عَنْ عَلْقَمَةَ بْنِ عَبْدِ اللَّهِ عَنْ أَبِيهِ. لاَ يُعْرَفُونَ إِلاَّ بِهِ.\n• مُحَمَّدُ بْنُ فَضَا بِفَتْحِ الْفَاءِ وَالْمُعْجَمَةِ مَعَ الْمَدِّ. تَقْرِيبُ التَّهْذِيبِ ٣١٥."],[500,"مُحَمَّدُ بْنُ فُرَاتٍ كُوفِيٌّ عَنْ أَبِي إِسْحَاقَ وَعَبْدِ اللَّهِ بْنِ الْحَسَنِ."],[501,"مُحَمَّدُ بْنُ عُمَرَ الْوَاقِدِيُّ مُخْتَلَفٌ فِيهِ. فِيهِ ضَعْفٌ بَيِّنٌ فِي حَدِيثِهِ.\n• فِي أَصْلِ الْمَخْطُوطِ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ وَالصَّوَابُ مَا هُوَ مُثْبِتٌ قَالَ ابْنُ حَجَرٍ: مَتْرُوكٌ مَعَ سَعَةِ عِلْمِهِ مِنْ التَّاسِعَةِ- ق- تَقْرِيبُ التَّهْذِيبِ ٣١٢."],[502,"مُحَمَّدُ بْنُ الْقَاسِمِ الأَسَدِيُّ. أَبُو إِبْرَاهِيمَ. كُوفِيٌّ يَكْذِبُ. عَنْ الثَّوْرِيِّ، وَالْأَوْزَاعِيِّ"],[503,"مُحَمَّدُ بْنُ ذَكْوَانَ بَصْرِيٌّ. خَالَ وَلَدَ حَمَّادِ بْنِ زَيْدٍ، يُرْوَى عَنْ عَمْرِو بْنِ دِينَارٍ وَابْنِ الْمُنْكَدِرِ وَمُجَالِدٍ."],[504,"مُحَمَّدُ بْنُ أَبِى حُمَيْدٍ وَيُقَالُ حَمَّادٌ. مَدَنِيٌّ، عَنِ ابْنِ الْمُنْكَدِرِ، وَنَافِعٍ، وَزَيْدِ بْنِ أَسْلَمَ."],[505,"مُحَمَّدُ بْنُ يُحَيٍّ الزُّهْرِيُّ. أَبُوغَزِيَّةُ مَدَنِيٌّ عَنْ عَبْدِ الْوَهَّابِ بْنِ مُوسَى يَضَعُ."],[506,"مُحَمَّدُ بْنُ الْفَضْلِ بْنِ عَطِيَّةَ الْخُرْسَانِيُّ ضَعِيفٌ عَنْ أَبِى إِسْحَاقَ وَمَنْصُورٍ مِنَ الْمُتَأَخِّرِينَ."],[507,"مُحَمَّدُ بْنُ زَكَرِيَّا الْغَلابِيُّ بَصْرِيٌّ يَضَعُ."],[508,"مُحَمَّدُ بْنُ عِيسَى بْنِ حَيَّانَ الْمَدَايِنِيُّ. عَنِ ابْنِ عُيَيْنَةَ وَمُحَمَّدِ بْنِ الْفَضْلِ بْنِ عَطِيَّةَ.\n• هُنَا عِبَارَةٌ لَمْ أَتَبَيَّنْهَا وَلَمْ أَجِدْهَا فِي كُتُبِ الرِّجَالِ."],[509,"مُحَمَّدُ بْنُ عَبْدِ بْنِ عَامِرٍ. طَوَافٌ. فِي الْبُلْدَانِ يَكْذِبُ وَيَضَعُ.\n• أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٣/ ٦٣٣."],[510,"مُحَمَّدُ بْنُ يُونُسَ بْنِ مُوسَى الشَّامِيُّ الْكُدَيْمِيُّ.\n• قَالَ الذَّهَبِيُّ: سُئِلَ عَنْهُ الدَّارَقُطْنِيُّ فَقَالَ: يُتَّهَمُ بِوَضْعِ الْحَدِيثِ. وَمَا أَحْسَنَ فِيهِ الْقَوْلَ إِلاَّ مَنْ لَمْ يُخْبِرْ حَالَهُ. مِيزَانُ الاِعْتِدَالِ ٤/ ٧٥."],[511,"مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ زِيَادٍ الرَّازِيُّ."],[512,"مُحَمَّدُ بْنُ عُكَّاشَةَ الْكَرْمَانِيُّ. بَصْرِيٌّ يَضَعُ الْحَدِيثَ."],[513,"مُحَمَّدُ بْنُ عُكَّاشَةَ. كُوفِيٌّ. ضَعِيفٌ."],[514,"مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ غَزْوَانَ. هُوَ ابْنُ زَيْدٍ، مَتْرُوكٌ بَغْدَادِيٌّ."],[515,"مُحَمَّدُ بْنُ أَيُّوبَ بْنِ سُوَيْدٍ الرَّمْلِيُّ. ضَعِيفٌ."],[516,"مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نَمْرَانَ. ضَعِيفٌ."],[517,"مُحَمَّدُ بْنُ عِيسَى الْهُذَلِيُّ. ضَعِيفٌ. يُرْوَى عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ يُكَنَّى أَبَا يَحَيٍّ."],[518,"مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ إِبْرَاهِيمَ بْنِ ثَابِتٍ الأَشْنَانِيُّ كَذَّابُ دَجَّالٍ () يَضَعُ الأَحَادِيثَ.\n• هُنَا عِبَارَةٌ غَيْرُ وَاضِحَةٍ. وَأَنْظُرُ تَارِيخَ بَغْدَادَ ٥/ ٤٣٩."],[519,"مُحَمَّدُ بْنُ هَارُونَ بْنِ عِيسَى بْنِ بَرِيِّهٍ. الْهَاشِمِيُّ."],[520,"مَعْبَدٌ الْجُهَنِيُّ. قَدَرِي. عَنْ حُمْرَانَ"],[521,"مُحَرَّرُ بْنُ هَارُونَ بْنِ عَبْدِ اللَّهِ التَّيْمِيُّ الْهَدِيرِيُّ. مَدَنِيٌّ عَنِ الأَعْرَجِ عَنْ أَبِيهِ لاَ يُعْرَفُ إِلاَّ بِهِ.\n• قَالَ ابْنُ حَجَرٍ: مُحَرَّرٌ بِرَاءَيْنِ وَزْنَ مُحَمَّدٍ عَلِيٌّ الصَّحِيحِ. تَقْرِيبُ التَّهْذِيبِ ٣٢٩."],[522,"مُبَارَكُ بْنُ سُحَيْمٍ أَبُوسُحَيْمُ بَصْرِيٌّ. مَوْلَى عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ.\n• مُبَارَكُ بْنُ سُحَيْمٍ بِمُهْمَلَتَيْنِ مُصَغَّرًا. تَقْرِيبُ التَّهْذِيبِ ٣٢٧."],[523,"مُبَشِّرُ بْنُ عُبَيْدٍ الْحِمْصِيُّ. يَكْذِبُ. عَنِ الزُّهْرِيِّ، وَزَيْدِ بْنِ أَسْلَمَ وَحَجَّاجِ ابْنِ أَرْطَأَهِ."],[524,"مَهْدِيُّ بْنُ هِلاَلٍ. يَضَعُ عَنْ هِشَامِ بْنِ عُرْوَةَ. وَجَعْفَرٍ."],[525,"مِينًا. مُوَلِّي عَبْدًا لِرَحْمَنِ بْنِ عَوْفٍ عَنِ ابْنِ مَسْعُودٍ."],[526,"مُطَيْرُ بْنُ خَالِدٍ. وَقِيلَ، مَطَرُ الاِسْكَافِ عَنْ أَنَسٍ. (٣. ٥) مُعَلَّى بْنُ عُرْفَانَ. كُوفِيٌّ. عَنْ أَبِي وَائِلٍ."],[527,"مُعَلَّى بْنُ هِلاَلِ بْنِ سُوَيْدٍ الطَّحَّانُ. كُوفِيٌّ يَكْذِبُ. عَنْ أَبِي إِسْحَاقَ وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ. يَرْوِي عَنْهُ الْحِمَّانِيُّ فَيَقُولُ عَلِيُّ بْنُ سُوَيْدٍ. وَيَرْوِي فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ فَيَقُولُ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ وَيَرْوِي عَنْهُ غَيْرُهُمَا فَيَقُولُ أَبُو عَبْدِ اللَّهِ الطَّحَّانُ.\n• أَنْظُرُ تَهْذِيبَ التَّهْدِيبِ ١٠/ ٢٤٠."],[528,"مُعَلَّى بْنُ عَبْدِ الرَّحْمَنِ. وَاسْطِي. عَنْ شَرِيكٍ، وَعَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ.\n• قَالَ الذَّهَبِيُّ: قَالَ الدَّارَقُطْنِيُّ كَذَّابٌ دِيوَانٌ ٣٠٤."],[529,"مَسْعَدَةُ بْنُ الْيَسَعِ بَاهِلِي، بَصْرِي. عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، وَابْنِ جُرَيْجٍ وَمُحَمَّدِ ابْنِ عَمْرٍو."],[530,"مُسَيَّبُ بْنُ شَرِيكٍ. كُوفِيٌّ. أَبُو سَعِيدٍ عَنِ الأَعْمَشِ وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ وَهِشَامِ ابْنِ عُرْوَةَ. رَوَى عَنْهُ إِسْحَاقُ بْنُ بَهْلُولٍ فَقَالَ أَبُو سَعِيدٍ الشَّقْرِيُّ. وَرَوَى عَنْهُ عَلِيُّ بْنُ الْجَعْدِ فَقَالَ أَبُوسَعِيدُ. ضَعِيفٌ.\n• أَنْظُرُ لِسَانَ الْمِيزَانِ ٦/ ٣٨."],[531,"مِسْوَرُ بْنُ الصَّلْتِ. مَدَنِيٌّ عَنْ نَافِعٍ وَابْنِ الْمُنْكَدِرِ وَزَيْدِ بْنِ أَسْلَمَ."],[532,"مَيْسَرَةُ بْنُ عَبْدِ رَبِّهِ بَغْدَادِيٌّ. عَنْ زَيْدِ بْنِ أَسْلَمَ كِتَابُ الْعَقْلِ لِدَاوُدَ بْنِ الْمُحَبَّرِ تَصْنِيفُهُ.\n• قَالَ الْخَطِيبُ الْبَغْدَادِيُّ. رَوَى عَنْهُ شُعَيْبُ بْنُ حَرْبٍ الْمَدَائِنِيُّ خُطْبَةَ الْوَدَاعِ. وَدَاوُدُ بْنُ الْمُحَبِّرِ بْنِ قَحْذَمٍ أَحَادِيثُ بَاطِلَةٌ فِي كِتَابِ الْعَقْلِ. تَارِيخُ بَغْدَادَ ١٣/ ٢٢٢."],[533,"مُعَاوِيَةُ بْنُ يُحَيِّ الصَّدَفِيُّ يَكْتُبُ مَا رُوِيَ الْهَقْلُ عَنْهُ وَيَتَجَنَّبُ مَا سِوَاهُ خَاصَّةً مَا رَوَى عَنْهُ إِسْحَاقُ بْنُ سُلَيْمَانَ الرَّازِيّ"],[534,"مُعَاوِيَةُ بْنُ عُمَرَ أَبُو مُطِيعٍ الاِطْرَابُلُسِيُّ. رَوَى عَنْهُ الْوَلِيدُ بْنُ مُسْلِمٍ وَشُعْبَةُ وَهِشَامُ بْنُ عُرْوَةَ وَعَلِيُّ بْنُ عَيَّاشٍ."],[535,"مُوسَى بْنُ مُطَيْرٍ كُوفِيٌّ. عَنْ أَبِيهِ، وَعَاصِمِ بْنِ بَهْدَلِهِ. وَمُوسَى بْنُ طَلْحَةَ. وَمُطَيْرٌ أَبُو لاَ يُعْرَفُ إِلاَّ بِهِ."],[536,"مُوسَى بْنُ عُمَيْرٍ أَبُو هَارُونَ الْجَعْدِيُّ الْمَخْزُومِيُّ. مَوْلَى بَنِي جَعْدَةَ بْنِ هُبَيْرَةَ عَنِ الْحَكَمِ وَأَبِي إِسْحَاقَ."],[537,"مُوسَى بْنُ سَعْدٍ أَبُو عَلِيٍّ الْحَنَفِيُّ. حَدِيثٌ مُنْكَرٌ عَنِ الْحَكَمِ فَقَالَ حَدَّثَنَا أَبُو هَارُونَ الشَّامِيُّ.\n• أَنْظُرُ لِسَانَ الْمِيزَانِ ٧/ ١١٦."],[538,"مُوسَى بْنُ عُمَيْرٍ الْعَنْبَرِيُّ. ثِقَةٌ عَنْ عَلْقَمَةَ بْنِ وَائِلِ بْنِ حُجْرٍ.\n• وَثَّقَهُ ابْنُ مَعِينٍ وَأَبُو حَاتِمٍ وَالْعِجْلِيُّ تَهْذِيبُ التَّهْذِيبِ ١٠/ ٣٦٤."],[539,"مُوسَى بْنُ عُبَيْدَةَ الرَّبَذِيُّ. لاَ يُتَابَعُ عَلَى حَدِيثِهِ. وَأَخُوهُ عَبْدُ اللَّهِ صَالِحٌ."],[540,"مُوسَى بْنُ مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ. عَنْ أَبِيهِ وَالزُّهْرِيِّ، وَمُجَاهِدٍ."],[541,"مُوسَى بْنُ دِينَارٍ مَكِّيٌّ عَنْ هِشَامٍ."],[542,"مُوسَى بْنُ طَرِيفٍ كُوفِيٌّ. عَنْ عُبَايَةَ بْنِ رِبْعِيٍّ. مَتْرُوكٌ."],[543,"مُوسَى بْنُ عُمَيْرٍ الْعَنْبَرِيُّ عَنْ عَبْدِ الْجَبَّارِ وَأَبِي وَائِلِ بْنِ حُجْرٍ.\n• أَنْظُرُ التَّرْجَمَةَ السَّابِقَةَ. وَلَعَلَّ هَذَا التَّكْرَارَ سَبْقُ قَلَمٍ مِنَ النَّاسِخِ."],[544,"مُوسَى بْنُ سَهْلٍ أَلْوَشَاءُ عَنْ إِسْمَاعِيلَ بْنِ عُلَيَّةَ حَدَّثُونَا عَنْهُ هُوَ غَيْرُ مُوسَى بْنِ سَهْلِ بْنِ عَبْدِ الْحَمِيدِ الْجَوْنِيِّ. وَالْجَوْنِيُّ صَالِحٌ الْحَدِيثِ."],[545,"مُوسَى بْنُ دِهْقَانَ حَدَّثُونَا عَنْهُ بَصْرِيٌّ عَنِ ابْنِ كَعْبِ بْنِ مَالِكٍ."],[546,"مُوسَى بْنُ مُحَمَّدِ بْنِ عَطَاءٍ الْمَقْدِسِيُّ أَبُو طَاهِرٍ عَنْ مَالِكٍ وَالْمُوَقِّرِيِّ."],[547,"مُغِيرَةُ بْنُ سَعِيدٍ الْكُوفِيُّ. دَجَّالٌ. أُحْرِقَ بِالنَّارِ زَمَنَ النَّخَعِيِّ أَدْعَى النُّبُوَّةَ.\n• قَالَ الْجُوزَجَانِيُّ قَتَلَ الْمُغِيرَةُ عَلِيٌّ ادِّعَاءَ النُّبُوَّةِ كَانَ أَشْعَلَ النِّيرَانِ بِالْكُوفَةِ عَلَيَّ التَّمْوِيهَ وَالشَّعْوَذَةِ حَتَّى أَجَابَهُ خَلْقٌ. مِيزَانُ الاِعْتِدَالِ ٤/ ١٦١."],[548,"مَسْلَمَةُ بْنُ عَلِيٍّ الْخُشَنِيُّ عَنِ الأَوْزَاعِيِّ، وَهِشَامُ بْنُ عُرْوَةَ وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ."],[549,"مُقَاتِلُ بْنُ سُلَيْمَانَ. خُرَاسَانِيٌّ. يَكْذِبُ."],[550,"مَيْمُونٌ أَبُو حَمْزَةَ الْقَصَّابُ الأَعْوَرُ. كُوفِي عَنْ النَّخَعِيِّ وَالْحَسَنِ"],[551,"مَرْوَانُ بْنُ سَالِمٍ الْجَزَرِيُّ. قَرْقُسَانِيٌّ. عَنْ عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ وَالزُّهْرِيِّ. (قَالَ الْبَرْقَانِيُّ اسْتَدْرَكْتُ مَنْ هُنَا إِلَيَّ آخِرَهُ مِنْ كِتَابِ غَيْرِي)."],[552,"مَطَرُ بْنُ مَيْمُونٍ الْمُحَارِبِيُّ."],[553,"مُطْرَحُ بْنُ يَزِيدَ. شَامِيٌّ."],[554,"مُجَالِدُ بْنُ سَعِيدٍ. كُوفِيٌّ. لَيْسَ بِقَوِيٍّ."],[555,"الْمُثَنَّى بْنُ الصَّبَّاحِ مَكِّيٌّ."],[556,"مُجَاشِعُ بْنُ عَمْرٍو."],[557,"مُنْذِرُ بْنُ زِيَادٍ الطَّائِيُّ."],[558,"مَعَارِكُ بْنُ عَبَّادٍ عَنْ عَبْدِ اللَّهِ بْنِ سَعِيدٍ الْمَقْبُرِيِّ."],[559,"نَاصِحُ بْنُ عَبْدِ اللَّهِ أَبُوعَبْدُ اللَّهِ كُوفِيٌّ. عَنْ سِمَاكِ بْنِ حَرْبٍ."],[560,"نَاصِحُ بْنُ الْعَلاَءِ أَبُو الْعَلاَءِ بَصْرِيٌّ. عَنْ عَمَّارِ بْنِ أَبِي عَمَّارٍ."],[561,"نُوْحُ بْنُ أَبِي مَرْيَمَ أَبُو عِصْمَةَ."],[562,"نَوْحُ بْنُ دَرَّاجٍ. كُوفِيٌّ."],[563,"النَّضْرُ بْنُ عَبْدِ الرَّحْمَنِ الْخَزَّازُ. كُوفِيٌّ. عَنْ عِكْرِمَةَ."],[564,"النَّضْرُ بْنُ سَلَمِهْ. شَاذَّانَ."],[565,"النَّضْرُ بْنُ مُطَرِّقٍ كُوفِيَ أَبَا لَيْنَةَ."],[566,"نَصْرُ بْنُ طَرِيفٍ أَبُو جَزِيٍّ."],[567,"نَصْرُ بْنُ بَابٍ. خُرَاسَانِيٌّ."],[568,"نَصْرُ بْنُ حَمَّادٍ. أَبُو الْحَارِثِ الْوَرَّاقُ. عَنْ شُعْبَةَ."],[569,"نَصْرُ بْنُ مُزَاحِمٍ الْمِنْقِرِيُّ. كُوفِيٌّ."],[570,"نُفَيْعُ بْنُ الْحَارِثِ أَبُو دَاوُدَ الأَعْمَى. كُوفِيٌّ."],[571,"نَافِعٌ. أَبُو هُرْمُزَ بَصْرِيٌّ عَنْ أَنَسٍ وَعَطَاءٍ.\n• قَالَ الذَّهَبِيُّ: نَافِعُ بْنُ هُرْمُزَ أَبُو هُرْمُزَ وَسَمَّاهُ الْعُقَيْلِيُّ نَافِعَ بْنَ عَبْدِ الْوَاحِدِ. مِيزَانُ الاِعْتِدَالِ ٤/ ٢٤٣."],[572,"نَجِيحٌ. أَبُو مَعْشَرٍ.\n• قَالَ الذَّهَبِيُّ: نَجِيحٌ أَبُو مَعْشَرٍ السِّنْدِيُّ الْهَاشِمِيُّ مَوْلاهُمُ الْمَدَنِيُّ صَاحِبُ الْمَغَازِي. مِيزَانُ الاِعْتِدَالِ ٤/ ٢٤٦."],[573,"نَهْشَلُ بْنُ سَعِيدٍ، خُرَاسَانِيٌّ"],[574,"نُعَيْمُ بْنُ الْمُوَرِّعِ بْنِ تَوْبَةَ. عَنِ الأَعْمَشِ، وَهِشَامِ بْنِ عُرْوَةَ."],[575,"نَوْفَلُ بْنُ سُلَيْمَانَ الْهِنَائِيُّ. حِجَازِيٌّ."],[576,"وَاقِدُ بْنُ سَلامَةَ مَدَنِيٌّ. وَقِيلَ وَافِدٌ بِالْفَاءِ عَنْ يَزِيدَ الرَّقَاشِي\n• قَالَ الذَّهَبِيُّ: وَافِدٌ بِالْفَاءِ أَوْ بِقَافٍ. ضَعَّفُوهُ مِيزَانَ الاِعْتِدَالِ ٤/ ٣٣٠."],[577,"وَاصِلُ بْنُ السَّائِبِ الرَّقَاشِيُّ. كُوفِيٌّ."],[578,"وَازَعَ بْنُ نَافِعٍ الْعُقَيْلِيُّ. جَزَرِيٌّ."],[579,"وَهْبُ بْنُ وَهْبٍ أَبُو الْبَخْتَرِيِّ. بَغْدَادِيٌّ. كَذَّابٌ."],[580,"وَلَيْدُ بْنُ مُحَمَّدٍ الْمُوَقِّرِيُّ. شَامِيٌّ.\n• قَالَ الذَّهَبِيُّ: الْوَلِيدُ بْنُ مُحَمَّدٍ الْمُوَقِّرِيُّ صَاحِبُ الزُّهْرِيِّ يُكَنَّى أَبَا بُثَيْرٍ الْبَلْقَاوِيَّ مَوْلَى بَنِي أُمَيَّةَ. وَالْمُوَقِّرُ حِصْنٌ بِالْبَلْقَاءِ. مِيزَانُ الاِعْتِدَالِ ٤/ ٣٤٦. قَالَ الذَّهَبِيُّ: الْوَلِيدُ بْنُ مُحَمَّدٍ الْمُوَقِّرِيُّ صَاحِبُ الزُّهْرِيِّ يَكْنِّي أَبَا بُثَيْرٍ الْبَلْقَاوِيَّ مُوَلِّي بَنِي أُمَيَّةَ. وَالْمُوَقِّرُ حِصْنٌ بِالْبَلْقَاءِ. مِيزَانُ الاِعْتِدَالِ ٤/ ٣٤٦."],[581,"وُلَيْدُ بْنُ الْعَبَّاسِ بْنِ مُسَافِرٍ. الْخَوْلانِيُّ. مِصْرِيٌّ."],[582,"وَلَيْدُ بْنُ وَلِيدٍ الدِّمَشْقِيُّ عَنِ ابْنِ ثَوْبَانَ. وَسَعِيدُ بْنُ بَشِيرٍ."],[583,"هِشَامُ بْنُ زِيَادٍ أَبُو الْمِقْدَامِ بَصْرِيٌّ عَنْ مُحَمَّدِ بْنِ كَعْبٍ. وَهِشَامُ بْنُ عُرْوَةَ وَأَخُوهُ الْوَلِيدُ ثِقَةٌ."],[584,"هِشَامُ بْنُ مُحَمَّدِ بْنِ السَّائِبِ الْكَلْبِيُّ عَنْ أَبِي مِخْنَفٍ وَمُجَاهِدٍ.\n• قَالَ الذَّهَبِيُّ: النَّسَّابَةُ الْعَلاَمَةُ وَقِيلَ أَنَّ تَصَانِيفَهُ أَزْيَدُ مِنْ مِائَةٍ وَخَمْسِينَ مُصَنِّفًا. مِيزَانُ الاِعْتِدَالِ ٤/ ٣٠٤."],[585,"هَيْثَمُ بْنُ جَمَّازٍ الْبُكَاءُ بَصْرِيٌّ."],[586,"هَيْثَمُ بْنُ عَدِيٍّ الطَّائِيُّ."],[587,"هَيْثَمُ بْنُ عَبْدِ الْغَفَّارِ بَصْرِيٌّ."],[588,"هُذَيْلُ بْنُ بِلاَلٍ الْمَدَائِنِيُّ يُكَنَّى أَبَا الْبَهْلُولِ."],[589,"هَارُونُ بْنُ هَارُونَ مَدَنِيٌّ.\n• هَارُونُ بْنُ هَارُونَ بْنِ عَبْدِ اللَّهِ بْنِ مُحْرِزِ بْنِ الْهَدِيرِ أَخُو مُحْرِزِ ابْنُ هَارُونَ. مِيزَانُ الاِعْتِدَالِ ٤/ ٢٨٧"],[590,"هَارُونُ بْنُ حَيَّانَ الرَّقِّىُّ عَنِ ابْنِ الْمُنْكَدِرِ وَلَيْثِ بْنِ أَبِي سُلَيْمٍ."],[591,"هَارُونُ بْنُ دِينَارٍ.\n• قَالَ الذَّهَبِيُّ: شَيْخٌ بَصَرِيٌّ. ضَعَّفَهُ الدَّارَقُطْنِيُّ وَغَيْرُهُ. مِيزَانُ الاِعْتِدَالِ ٤/ ٢٨٣."],[592,"يُحَيُّ بْنُ عُبَيْدِ اللَّهِ بْنِ مَوْهَبٍ عَنْ أَبِيهِ."],[593,"يُحَيُّ بْنُ أَبِي أُنَيْسَةَ الْجَزَرِيُّ."],[594,"يُحِيُّ بْنُ مُسْلِمٍ الْبُكَاءُ بَصْرِيٌّ. عَنِ ابْنِ عُمَرَ."],[595,"يُحَيُّ بْنُ سَلَمَةَ بْنِ كُهَيْلٍ."],[596,"يُحَيُّ بْنُ عُقْبَةَ بْنِ أَبِي الْعَيْزَارِ."],[597,"يُحَيُّ بْنُ أَبِي حَيَّةَ. أَبُو جَنَابٍ الْكَلْبِيُّ.\n• يَحِيِ ابْنُ أَبِي حَيَّةَ بِمُهْمَلَةٍ وَتَحْتَانِيَّةُ أَبُو جَنَابٍ بِحِيَمٍ وَنُونٍ خَفِيفَتَيْنِ. تَقْرِيبُ التَّهْذِيبِ ٣٧٤."],[598,"يُحَيُّ بْنُ سَعِيدٍ الْمَدِينِيُّ. التَّمِيمِيُّ وَهُوَ الْفَارِسِيُّ قَاضِي شِيرَازَ عَنِ الزُّهْرِيِّ وَهِشَامِ بْنِ عُرْوَةَ."],[599,"يُحَيُّ بْنُ كَثِيرٍ أَبُو النَّضْرِ. بَصْرِيٌّ ضَعِيفٌ. عَنْ أَيُّوبَ، وَسُلَيْمَانَ التَّيْمِيِّ وَعَامِرٍ. الأَحْوَلُ، وَعَطَاءُ بْنُ السَّايِبِ، وَدَاوُدُ بْنُ أَبِي هِنْدٍ."],[600,"يُحَيُّ بْنُ الْعَلاَءِ الرَّازِيُّ الْبَجَلِيُّ."],[601,"يُحَيُّ بْنُ مَيْمُونِ بْنِ عَطَاءٍ أَبُو أَيُّوبَ التُّمَّارُ بَصْرِيٌّ."],[602,"يُحَيُّ بْنُ بِسْطَامَ بْنِ حُرَيْثٍ بَصْرِيٌّ."],[603,"يُحَيُّ بْنُ هَاشِمٍ السِّمْسَارُ. أَبُو زَكَرِيَّا. كَانَ بِبَغْدَادَ."],[604,"يُحَيُّ بْنُ عَمْرِو بْنِ مَالِكٍ. بَصْرِي."],[605,"يُحَيُّ بْنُ رَاشِدٍ. بَصْرِي."],[606,"يُحَيُّ بْنُ سَالِمٍ. كُوفِيٌّ."],[607,"يُحِيُّ بْنُ ثَعْلَبِهِ أَبُو الْمُقَوِّمِ.\n• أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٤/ ٢٦٧."],[608,"يُحَيُّ بْنُ عَنْبَسَةَ بَغْدَادِيٌّ كَذَّابٌ."],[609,"يَزِيدُ بْنُ عِيَاضِ بْنِ جَعْدُبَةَ. مَكِّيٌّ.\n• يَزِيدُ بِهِ عِيَاضُ بْنُ جَعْدُبَةَ بِضَمِّ الْجِيمِ وَالْمُهْمَلَةُ بَيْنَهُمَا مُهْمَلَةٌ سَاكِنَةٌ. تَقْرِيبُ التَّهْذِيبِ ٣٨٤."],[610,"يَزِيدُ بْنُ سِنَانٍ أَبُو فَرْوَةَ الرَّهَاوِيُّ."],[611,"يَزِيدُ بْنُ رَبِيعَةَ أَبُو كَامِلٍ الرَّحَبِيُّ. مِنْ صَنْعَاءِ دِمَشْقَ."],[612,"يَزِيدُ بْنُ سُفْيَانَ أَبُو الْمُهَزَّمِ بَصْرِيٌّ ضَعَّفَهُ شُعْبَةُ.\n• أَبُو الْمُهَزَّمِ بِتَشْدِيدِ الزَّايِ الْمَكْسُورَةِ اسْمُهُ يَزِيدُ وَقِيلَ عَبْدُ الرَّحْمَنِ. تَقْرِيبُ التَّهْذِيبِ ٤٢٨."],[613,"يَزِيدُ بْنُ عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ بْنِ نَوْفَلٍ مَدَنِيٌّ."],[614,"يَزِيدُ بْنُ إِبَّانِ الرَّقَاشِيِّ عَنْ أَنَسٍ."],[615,"يَزِيدُ بْنُ بَيَانِ الْمُعَلِّمُ."],[616,"يَزِيدُ بْنُ يُوسُفَ الشَّامِيُّ."],[617,"يَزِيدُ بْنُ عَطَاءٍ مُولِي أَبِي عَوَانَةَ وَاسْطِي."],[618,"يَعْقُوبُ بْنُ الْوَلِيدِ مَدَنِيٌّ."],[619,"يُوسُفُ بْنُ مُحَمَّدِ بْنِ الْمُنْكَدِرِ عَنْ أَبِيهِ."],[620,"يُوسُفُ بْنُ السَّفَرِ أَبُو الْفَيْضِ عَنِ الأَوْزَاعِيِّ رَوَى عَنْهُ عَبْدُ اللَّهِ بْنُ عِمْرَانَ الْعَابِدِيُّ فَقَالَ يُوسُفُ بْنُ الْفَيْضِ شَامِيٌّ.\n• أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٤/ ٤٦٦."],[621,"يُوسُفُ بْنُ خَالِدٍ السَّمْتِيُّ بَصْرِيٌّ."],[622,"يُوسُفُ بْنُ عَطِيَّةَ الصَّفَّارُ أَبُو سَهْلٍ بَصْرِيٌّ."],[623,"يُوسُفُ بْنُ عَطِيَّةَ الْوَرَّاقُ كُوفِيٌّ. أَبُو الْمُنْذِرِ."],[624,"يُوسُفُ بْنُ مَيْمُونٍ الصَّبَّاغُ كُوفِيٌّ. عَنْ عَطَاءٍ."],[625,"يُونُسُ بْنُ خَبَّابٍ كُوفِي سَيْءُ الْمَذْهَبِ.\n• مَا بَيْنَ الْقَوْسَيْنِ كَلِمَةٌ غَيْرُ وَاضِحَةٍ وَقَدْ وُجِدَتْ تَرْجَمَةٌ هَدَا الرَّجُلِ فِي مِيزَانِ الِاِعْتِدَالِ وَتَهْذِيبِ التَّهْذِيبِ وَعَثَرَتْ فِيهِمَا عَلَيَّ قَوْلُ الدَّارَقُطْنِيِّ وَنَصُّهُ. \"كَانَ رَجُلٌ سُوءٍ فِيهِ شِيعِيَّةٌ مُفْرِطَةٌ كَانَ يَسُبُّ عُثْمَانَ \" أَنْظُرُ مِيزَانَ الاِعْتِدَالِ ٤/ ٤٧٩، تَهْذِيبُ التَّهْذِيبِ ١١/ ٤٣٨."],[626,"يَعْلَى بْنُ الأَشْدَقِ."],[627,"يَاسِينُ بْنُ مُعَاذٍ أَبُو خَلَفِ الزَّيَّاتُ كُوفِيٌّ."],[628,"يَمَانُ بْنُ الْمُغِيرَهْ أَبُو حُذَيْفِهْ الْعَنَزِيُّ بَصْرِيٌّ.\n• جَعَلَ الذَّهَبِيُّ هَذِهِ التَّرْجَمَةَ وَمَا بَعْدَهَا لِرَجُلٍ وَاحِدٍ. مِيزَانُ الاِعْتِدَالِ ٤/ ٤٦٠"],[629,"يَمَانٌ أَبُو حُذَيْفَةَ. وَقِيلَ ابْنُ حُذَيْفَةَ. بَصْرِي."],[630,"يَمَانُ بْنُ سَعِيدٍ. أَبُو رِضْوَانَ شَامِيٌّ."],[631,"يَمَانُ بْنُ عَدِيٍّ أَبُو عَدِيٍّ الْحَضْرَمِيُّ ضَعِيفٌ."],[632,"يَمَانُ بْنُ رِئَابٍ خُرَاسَانِيٌّ يَرَى رَأْيَ الْخَوَارِجِ."],[633,"أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَبْرَةَ مَدِينِيٌّ.\n• قِيلَ اسْمُهُ عَبْدُ اللَّهِ وَقِيلَ مُحَمَّدٌ. تَقْرِيبُ التَّهْذِيبِ ٣٩٦"],[634,"أَبُوحَامِدُ الْحَنَفِيُّ مَجْهُولٌ."],[635,"أَبُودَاوُدُ النَّخَعِيُّ كَذَّابٌ رَمَاهُ أَحْمَدُ بْنُ حَنْبَلٍ بِالْكَذِبِ."],[636,"أَبُوكَرْزٌ الْقُرَشِيُّ مَجْهُولٌ.\n• عَبْدُ اللَّهِ بْنُ كُرْزٍ الْقُرَشِيُّ لِسَانُ الْمِيزَانِ ٧/ ٩٨."],[637,"أَبُو نَاشِرَةَ مَجْهُولٌ."],[638,"أَبُو سَوْرَةَ مَجْهُولٌ يَرْوِي عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ.\n• قَالَ الذَّهَبِيُّ: يُقَالُ أَنَّهُ أَبْنَ أَخِي أَبِي أَيُّوبَ. مِيزَانُ الاِعْتِدَالِ ٤/ ٥٣٥."],[639,"أَبُو أَدَامَ كُوفِيَ سُلَيْمَانُ بْنُ زَيْدٍ الْمُحَارِبِيُّ عَنِ ابْنِ أَبِي أَوْفِيٍّ ضَعِيفٍ."],[640,"أَبُو هَمْدَانَ. الْقَاسِمُ بْنُ بَهْرَامَ قَاضِي هَيْتٍ مَتْرُوكٍ."],[641,"أَبُو تَوْبَةَ الْقَاصُّ بَصْرِيٌّ ضَعِيفٌ."],[642,"أَبُو سُفْيَانَ الصُّوفِيُّ. وَيُقَالُ الْعَوْفِيُّ. قَالَ الدَّارَقُطْنِيُّ لَيْسَ أَعْرِفُهُ."],[643,"أَبُو حَمَّادٍ الْكُوفِيُّ الْحَنَفِيُّ الْمُفَضَّلُ بْنُ صَدَقَةَ لَيْسَ بِالْقَوِيِّ."],[644,"أَبُو حَفْصٍ الْعَبْدِيُّ عُمَرُ بْنُ حَفْصٍ ضَعِيفٌ."],[645,"أَبُو أُمَيَّةَ بْنُ يَعْلَى الثَّقَفِيُّ ضَعِيفٌ.\n• قَالَ الذَّهَبِيُّ: هُوَ إِسْمَاعِيلُ. مِيزَانُ الاِعْتِدَالِ ٤/ ٤٩٣."],[646,"أَبُو سُفْيَانَ السَّعْدِيُّ طَرِيفٌ ضَعِيفٌ."],[647,"أَبُو عَبْدِ السَّلاَمِ مَجْهُولٌ.\n• قَالَ الذَّهَبِيُّ: قِيلَ اسْمُهُ الزُّبَيْرُ وَقِيلَ أَيُّوبُ. مِيزَانُ الاِعْتِدَالِ ٤/ ٥٤٨."],[648,"أَبُو صَفْوَانَ عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ مِنْ الثِّقَاتِ عَنْ يُونُسَ ابْنِ مَالِكٍ"],[649,"سَعِيدُ بْنُ مَسْلَمَةَ بْنِ هِشَامِ بْنِ عَبْدٍ. الْمَلِكُ ضَعِيفٌ يُعْتَبَرُ بِهِ."],[650,"وَمَسْلَمَةُ بْنُ سَعِيدِ بْنِ عَبْدِ الْمَلِكِ يُعْتَبَرُ بِهِ ضَعِيفٌ."],[651,"بَقِيَّةُ يَرْوِي عَنْ قَوْمٍ مَتْرُوكِينَ مِثْلَ."],[652,"مُجَاشِعُ بْنُ عَمْرٍو.\n• انْظُرْ مِيزَانَ الاِعْتِدَالِ ٣/ ٤٣٦."],[653,"وَعُبَيْدُ اللَّهِ بْنُ يُحَيٍّ لَا أَعْرِفُهُ وَلَا أَعْلَمُ رَوَى عَنْهُ غَيْرَ بَقِيَّةِ"],[654,"وَعَبْدُ الْحَمِيدِ بْنُ السَّرِيِّ الْغَنَوِيُّ يَرْوِي عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ يُقَالُ لَهُ أَبُو الْيُسْرِ ضَعِيفٌ.\n• قَالَ الذَّهَبِيُّ: مِنَ الْمَجَاهِيلِ. ضَعَّفَهُ الدَّارَقُطْنِيُّ. مِيزَانُ الاِعْتِدَالِ ٢/ ٥٤١."],[655,"الْوَلِيدُ بْنُ مُسْلِمٍ يُرْسِلُ، يَرْوِي عَنِ الأَوْزَاعِيِّ أَحَادِيثَ الأَوْزَاعِيِّ عَنْ شُيُوخِ ضُعَفَاءَ عَنْ شُيُوخٍ قَدْ أَدْرَكَهُمُ الأَوْزَاعِيُّ مِثْلَ نَافِعٍ وَعَطَاءٍ وَالزُّهْرِيِّ فَيُسْقِطُ أَسْمَاءَ الضُّعَفَاءِ وَيَجْعَلُهَا عَنِ الأَوْزَاعِيِّ عَنْ عَطَاءٍ يَعْنِي مِثْلَ عَبْدِ اللَّهِ بْنِ عَامِرٍ الأَسْلَمِيِّ وَإِسْمَاعِيلَ بْنِ مُسْلِمٍ. (آخِرَ الْكِتَابِ وَالْحَمْدُ لِلَّهِ وَحْدَهُ وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا) ... وَهُوَ حَسْبُنَا وَنِعْمَ الْوَكِيلُ. بَلَغَ الْعَرْضَ.\n• قَالَ الذَّهَبِيُّ: إِذَا قَالَ الْوَلِيدُ بْنُ مُسْلِمٍ عَنِ ابْنِ جُرَيْجٍ أَوْ عَنِ الأَوْزَاعِيِّ فَلَيْسَ بِمُعْتَمَدٍ لأَنَّهُ يُدَلِّسُ عَنْ كَذَّابَيْنَ فَإِذَا قَالَ حَدَّثَنَا فَهُوَ حُجَّةٌ. مِيزَانُ الاِعْتِدَالِ ٤/ ٣٤٨."]]);
